# Ботът предричаше за осем спорта, а стаи имаше за пет: хокеят, тенисът,
# бейзболът и американският футбол оставаха само в общата витрина 27.
# make_rooms.py ги създава в групата и записва номерата им в rooms_state.json.
# Тук те просто се вливат — така създаването и ползването им са ЕДНО качване,
# а не две, и ако утре се появи девети спорт, не се пипа този файл.
#
# Ако файлът липсва или е повреден, нищо не се чупи: спортът просто остава
# без своя стая, точно както беше досега. Тиха загуба, не тих провал.
ROOMS_STATE_FILE = (os.environ.get("ROOMS_STATE_FILE") or "rooms_state.json").strip()


def _stai_ot_fayl(path):
    """Спорт -> номер на стая, от паметта на make_rooms.py. {} при липса."""
    try:
        with open(path, encoding="utf-8-sig") as f:
            d = json.load(f)
    except Exception:                             # noqa: BLE001
        return {}
    if not isinstance(d, dict):
        return {}
    out = {}
    for sport, zapis in d.items():
        thread = (zapis or {}).get("thread") if isinstance(zapis, dict) else None
        try:
            n = int(thread)
        except (TypeError, ValueError):
            continue
        if n > 0 and str(sport).strip():
            out[str(sport).strip()] = str(n)
    return out


for _sport, _stay in _stai_ot_fayl(ROOMS_STATE_FILE).items():
    SPORT_ROOM.setdefault(_sport, _stay)      # закованите отгоре имат превес
PICKS_THREAD = (os.environ.get("PICKS_THREAD_ID") or "4").strip()

# 🚫 Новините са чужди. Всичко останало, което пипаме, е изброено поименно.
FORBIDDEN_THREADS = {"26"}
ALLOWED_THREADS = ({PREDICT_THREAD, PICKS_THREAD}
                   | set(SPORT_ROOM.values())) - FORBIDDEN_THREADS

DRY_RUN = (os.environ.get("PREDICT_DRY_RUN") or "").strip() in ("1", "true", "yes", "да")


def env_int(name, default, lo, hi):
    try:
        v = int((os.environ.get(name) or "").strip())
    except ValueError:
        v = default
    return max(lo, min(hi, v))


def env_float(name, default, lo, hi):
    try:
        v = float((os.environ.get(name) or "").strip())
    except ValueError:
        v = default
    return max(lo, min(hi, v))


# 🔴 КЛЮЧ, КОЙТО НЕ СТИГА ДО ПРОЦЕСА, Е МЪРТВА РЪЧКА (01.09.2026).
# Измерено: predictor.py чете 93 ключа от средата, а predict.yml подаваше 43.
# Между неподадените бяха ТРИ неща, направени същия ден — денонощните часове,
# прагът за пресмелите карти и местният тенис на маса. Кодът ги четеше,
# самопроверката ги мереше зелени, и въпреки това собственикът нямаше как да
# ги завърти: редът с тази променлива изобщо не съществуваше в yml-а.
# Този списък са ръчките, които ТРЯБВА да стигат до процеса. Проверката в
# selftest чете самия predict.yml — както прави и сверката на кроновете.
KLYUCHOVE_ZA_YML = (
    "MAX_PICKS", "PREDICT_POOL", "PREDICT_HTTP_BUDGET", "PREDICT_MAX_DAY",
    "PREDICT_IZKL", "PREDICT_AMFUTBOL_MAX",
    "PREDICT_QUIET_TO", "PREDICT_QUIET_FROM", "PREDICT_SMELOST_MAX",
    "PREDICT_TTLOKAL", "PREDICT_TTLOKAL_MAX", "PREDICT_TTLOKAL_SCALE",
    "PREDICT_ITF_MAX", "PREDICT_HORIZON_AMF", "PREDICT_HORIZON_HOK",
    "PREDICT_HORIZON_MMA", "PREDICT_MAX_URGENT", "PREDICT_URGENT_LEAD_H",
    # 📈 тефтерът на цените — вписан 02.09.2026. Без него ключът работи,
    # но не е ПАЗЕН: махне ли се редът от predict.yml, ръчката умира
    # мълчаливо и никоя проверка не гърми.
    "PREDICT_DVIZHENIE",
    "PREDICT_SAMO_S_KOEF",
    # ── ПЪТИЩАТА НАЗАД (02.09.2026). Одит намери 127 мъртви ръчки; тези пет
    # са думите, с които собственикът спира нещо. Три от тях бяха мъртви по
    # МОЯ вина: обявих ги за път назад в доклада, без yml да ги подава.
    # Четат се от zabraneni.py, zalozhimo.py и volley_evro.py, но се подават
    # на СЪЩАТА стъпка, значи мястото им е тук.
    "GREENPICKS_ZABRANI_KOEF", "GREENPICKS_PAZACH",
    "PREDICT_ZALOZHIMO", "PREDICT_ZALOZHIMO_SPORTOVE", "VOL_PRAG",
)


def klyuchove_diag():
    """С какви настройки е работило ТОВА пускане — и коя откъде идва.

    🔴 Защо съществува (01.09.2026): собственикът сложи променливите, рънът
    мина зелен, а амер. футбол пак го нямаше в черната кутия — и отвън НЯМАШЕ
    как да се разбере дали променливата изобщо е стигнала до процеса. Кутията
    отговаряше на «колко срещи видях», но не и на «с какви настройки».
    Пише се СТОЙНОСТТА и ИЗТОЧНИКЪТ. Никакви токени и тайни: списъкът е
    затворен и се пази от проверка.
    """
    d = {}
    for klyuch in KLYUCHOVE_ZA_YML:
        sur = (os.environ.get(klyuch) or "").strip()
        d[klyuch] = {"ot": ("ключ" if sur else "по подразбиране")}
    g = globals()
    for klyuch, ime in (("MAX_PICKS", "MAX_PICKS"),
                        ("PREDICT_POOL", "POOL"),
                        ("PREDICT_HTTP_BUDGET", "HTTP_BUDGET"),
                        ("PREDICT_MAX_DAY", "MAX_DAY"),
                        ("PREDICT_AMFUTBOL_MAX", "AMFUTBOL_MAX"),
                        ("PREDICT_QUIET_TO", "QUIET_TO"),
                        ("PREDICT_QUIET_FROM", "QUIET_FROM"),
                        ("PREDICT_SMELOST_MAX", "SMELOST_MAX"),
                        ("PREDICT_TTLOKAL_MAX", "TTLOKAL_MAX"),
                        ("PREDICT_TTLOKAL_SCALE", "TTLOKAL_SCALE")):
        if klyuch in d and ime in g:
            d[klyuch]["stoynost"] = g[ime]
    d["PREDICT_IZKL"]["stoynost"] = sorted(g.get("IZKLYUCHENI") or [])
    d["ACTIVE_SPORTS"] = {"ot": "пресметнато",
                          "stoynost": list(g.get("ACTIVE_SPORTS") or [])}
    d["RUN_HOURS"] = {"ot": "пресметнато",
                      "stoynost": list(g.get("RUN_HOURS") or [])}
    return d


# 6, не 4. Откакто списъците със срещи спряха (собственикът: „искам всичко
# прогнози, а не какво предстои като някакви списъци"), спортните стаи живеят
# САМО от прогнози. При четири карти на пускане и девет спорта една стая
# оставаше по цял ден без нищо.
# 🔴 9, НЕ 6 (19.08.2026) — ИЗМЕРЕНО СЪС СУХО ПУСКАНЕ, не преценено.
#
# Въпросът беше прост: колко кандидата НАД ПРАГА се изхвърлят днес заради
# тавана. Три сухи пускания същия ден, един и същ час (16:15), един и същ
# набор от 76 събрани срещи:
#
#   PER_SPORT  MAX_PICKS   под лупата   над прага   ИЗЛЕЗЛИ   изхвърлени от тавана
#       5          6           17           9          9              0
#       8          6           26          17         13              4
#       8         10           26          17         17              0
#
# Тоест при старата ширина таванът НЕ режеше нищо — режеше ЛУПАТА (PER_SPORT).
# Щом лупата се отвори, таванът започва да реже по четири карти на пускане.
#
# И обратната посока, защото повече карти могат да значат по-слаби карти:
#   средна увереност на 9-те стари карти            60.6%
#   средна увереност на 17-те нови карти            58.3%
#   средна увереност на ЧЕТИРИТЕ, които таванът хвърляше: 55.0%
# Всички те са НАД публикувания праг (53% при два изхода) — тоест губехме
# карти, които сами сме обявили за годни. Цената е 2.3 пункта средна увереност
# за 89% повече карти.
#
# Горната граница се вдига на 16, за да може собственикът да опита и повече
# без пипане на код (MAX_PICKS=12).
MAX_PICKS = env_int("MAX_PICKS", 9, 1, 16)
# 32, не 24 (вдигнат 11.08.2026 заедно с броя фишове).
