    # 🥊 ММА 72 ч (01.09.2026). ИЗМЕРЕНО — И ПО ДРУГА ПРИЧИНА ОТ АМЕР. ФУТБОЛА.
    #
    # Сухото пускане показа „5 срещи (14 ДАЛЕЧЕ — чакат)“ и това ЛИЧИ като
    # същия дефект. НЕ Е. Оборих сам себе си, преди да пипна числото:
    #
    #   ММА се СЪБИРА вече с диапазон — mma_fixtures пита ESPN за
    #   MMA_DAYS_AHEAD+1 дни. Подслушах адресите: и при стария, и при новия
