    #   /mma/<лига>/scoreboard?dates=20260901-20260907. Тоест ВТОРАТА
    #   запушалка на амер. футбола — въпросът да не стига до деня на
    #   мачовете — тук изобщо я няма.
    #
    # Симулация върху истинския календар (63 боя в 9 гали за 30 дни; и
    # втори път 96 боя за 60 дни), 15 пускания на ден по predict.yml:
    #   хоризонт | боеве, които НИКОГА не влизат в прозореца
    #      30 ч  |  0        72 ч  |  0        120 ч  |  0
    # Тоест 30-часовият хоризонт НЕ ГУБИ нито един бой — той го ЗАБАВЯ.
    # Числото „14 далече“ е измамно: тези 14 влизат сами след три дни.
    #
    # ТОГАВА ЗАЩО СЕ ВДИГА: заради ГЛАДНАТА СТАЯ, не заради загубени боеве.
    # Същата симулация, колонка „дни с поне един допустим бой“:
    #      30 ч   17 от 30 дни  ·  29 от 60 дни
    #      48 ч   20 от 30      ·  33 от 60
    #      72 ч   28 от 30      ·  47 от 60   ← КОЛЯНОТО
    #     120 ч   29 от 30      ·  55 от 60
    # Живият дневник го потвърждава: ММА е дал 16 карти за 28 дни, и то
    # само в 5 от тези 28 дни. Стаята мълчи 23 дни от 28.
    # 72 взима стръмната част (+11 дни от 30, +18 от 60); следващите 48
    # часа хоризонт добавят 1 от 30 и 8 от 60 — четири пъти по-малко на час.
    #
    # ЦЕНАТА, ИЗМЕРЕНА, НЕ ПРЕДПОЛОЖЕНА:
    #   заявки за СЪБИРАНЕ: 0 повече (виж подслушаните адреси по-горе).
    #   заявки за АНАЛИЗ: 3 за 6 боя = 0.5 на бой → 14 далечни ≈ 7 заявки.
    #   ЦЕНА при далечните: 11 от 14 боя на 104.5 часа имат цена СЕГА
    #     (78.6%) срещу 4 от 5 близки (80%) — цената НЕ остарява при ММА.
    #   СБЪДВАЕМОСТ: дневникът НЕ ОТГОВАРЯ. 1042 отсъдени записа и НИТО
    #     ЕДИН над 30 часа — хоризонтът беше 30, значи такава карта никога
    #     не е издавана. Вътре в 0-30 ч разликата е −2.1 точки, 95%
    #     [−11.1 .. +6.9] (n=334 под 12 ч срещу 178 в 12-30 ч): нулата е
    #     вътре. По ДНИ напред (по-грубо): −5.7 т, 95% [−11.7 .. +0.2], и
    #     знакът е един и същ в 5 от 6 спорта. НЕ Е ДОКАЗАНО, че вреди, но
    #     посоката е предупреждение — и точно затова 72, а не 120.
    # Изход: PREDICT_HORIZON_MMA=30 връща стария вид. PREDICT_HORIZON_MMA=120
