# ОСТАНАЛИТЕ ОСТАВАТ НА 30 — И ТОВА Е ИЗМЕРЕНО, НЕ ПРОПУСНАТО (01.09.2026).
# Хистограма „след колко часа е мачът“, БЕЗ филтъра за хоризонт, върху
# едно живо събиране: далечни (над 30 ч) имаха само еспортът (6 от 35) и
# боксът (1 от 4) — и двамата СПЯТ (BOKS_MAX=0, ESPORT_MAX=0), тоест
# промяна там не мести нито една карта днес. Тенис 0 от 90, футбол 0 от
# 38, бейзбол 0 от 36, волейбол 0 от 5.
# ЧЕСТНО КАКВО НЕ ДОКАЗВА ТАЗИ НУЛА: тези спортове се питат за ЕДИН ДЕН,
# значи източникът НЕ МОЖЕ да върне мач след 30 часа — нулата е свойство
# на ВЪПРОСА. Питах същите адреси с диапазон: eng.1 дава 8 мача в 30-120 ч,
# МЛБ дава 55. Но те не се ГУБЯТ: МЛБ играе 7 дни от 7, а европейският
# футбол се пита наново всеки ден — мачът влиза в прозореца сам.
# Хокеят: НХЛ играе почти всеки ден (291 мача за 60 дни, и седемте дни от
# седмицата) — при него дългият хоризонт добавя 4 дни глас от 60. Освен
# това hockey_fixtures се вика с ymd_dash, а НЕ с ymd_za, тоест въпросът му
# остава ЕДИН ДЕН и записът „hockey“ тук е почти без ефект. Не се пипа:
# спортът е извън сезон (следващ мач 15.09) и днес няма какво да се мери.


def horizont_za(bucket):
    """Колко часа напред гледаме за ТОЗИ спорт. Непознат спорт -> общият."""
    return HORIZONT_PO_SPORT.get(str(bucket or ""), HORIZON_H)
# Таван за ЦЕЛИЯ ден. Осем пускания по MAX_PICKS биха дали 32 карти — стаята
# не е лента с новини. Тавана го брои тефтерът, не отделното пускане.
# 24, не 10. Същата причина: стаите на деветте спорта се пълнят единствено от
# прогнози. Десет карти на ден означаваше, че пет от стаите мълчат.
# Двадесет и четири при осем пускания са по три на пускане — четимо, не порой.
# Вдигнат от 24 на 40 (05.08.2026). Причината е новото правило „всичко до 22:00":
# вечерното пускане в 20:00 вече поема ЦЯЛАТА нощ — всички мачове до 08:00 на
# другия ден. При таван 24 то щеше да опира в него точно тогава, когато носи
# най-много спешни карти, и нощните мачове щяха да останат без прогноза.
# 🔴 40 → 60 (19.08.2026). Вдигнатият MAX_PICKS без вдигнат дневен таван е
# капан: същият брой карти, само изхарчени по-рано, и стаята мълчи вечерта —
# точно дефектът, заради който съществува СТЪЛБАТА по-долу.
# Сметката за триенето е сверена: PICKLOG_KEEP (5000) трябва да е над
# MAX_DAY × ARHIV_DNI = 60 × 60 = 3600. Стои, и самопроверката го пази.
# 🔴 ТАВАНЪТ НА СРЕДАТА: 80 → 200 (02.09.2026). Подразбирането ОСТАВА 60.
# Измерено на живия дневник (1424 карти, 32 дни): средно 44.5/ден, но
# 02.09 даде 83, 03.09 даде 89, 04.09 даде 76 — тоест таванът вече е тапа
# в добрите дни, а собственикът иска повече мачове.
# Вдигането е безопасно, защото сметката под него вече е АВТОМАТИЧНА:
# виж PICKLOG_KEEP по-долу. Дотук тя се пазеше само от проверка, която
# казва «не го прави»; сега кодът я спазва сам.
MAX_DAY = env_int("PREDICT_MAX_DAY", 60, 1, 200)
# Тефтерът пази толкова дни назад. Трябва да е ПО-ГОЛЯМО от най-далечния
