# ---------------------------------------------------------------- ДРЕБНИ ИНСТРУМЕНТИ
def esc(x):
    # quote=False нарочно: Telegram иска само &amp; &lt; &gt;. С quote=True
    # апострофът става &#x27; и се вижда като боклук в „Men's Singles".
    return html.escape(str(x if x is not None else ""), quote=False)


def clip(text, limit=3900):
    if len(text) <= limit:
        return text
    return text[:limit] + NL + "…(отрязано)"


def pct(p):
    return str(int(round(float(p) * 100.0))) + "%"


def to_num(x):
    try:
        if x is None or str(x).strip() == "":
            return None
        return int(float(x))
    except (TypeError, ValueError):
        return None


def to_f(x, default=None):
    try:
        if x is None or str(x).strip() == "":
            return default
        return float(x)
    except (TypeError, ValueError):
        return default


def mean(xs):
    xs = list(xs)
    return sum(xs) / float(len(xs)) if xs else 0.0


def mn(n, edn, mno):
    """Думата СЛЕД числото: единствено при точно 1, множествено иначе.

    ЕДНО МЯСТО ЗА ЦЕЛИЯ ФАЙЛ (26.08.2026). Дотук всяко съобщение си пишеше
    собствен клон „if x == 1“ — и точно затова половината ги нямаха.
    Финишът печаташе „От 1 пуснати днес 1 имат резултат.“, а редът точно
    под него („⏳ 1 чака мача си“) беше верен. Двата реда са писани от един
    и същи човек в един и същи ден; разликата е само дали се е сетил.

    НУЛАТА Е МНОЖЕСТВЕНО на български: „0 карти“, не „0 карта“. Затова
    сравнението е с 1, а не „по-голямо от 1“.

    Не-число НЕ гърми — държи се като множествено. Крива дума е по-евтина
    от паднало съобщение: това се вика в градежа на текст, който тръгва към
    Telegram, и изключение тук би изяло ЦЯЛАТА равносметка.
    """
    try:
        edno = (int(n) == 1)
    except (TypeError, ValueError):
        edno = False
    return edn if edno else mno


def n_match(n):
    return str(n) + mn(n, " среща", " срещи")


def date_bg(now):
    return WEEKDAYS[now.weekday()] + ", " + str(now.day) + "." + ("%02d" % now.month)


# Схемите на турнирите носят празни слотове, докато предният кръг свърши.
# „TBD срещу Тейлър Фриц" не е среща и не бива да стига до карта.
PLACEHOLDERS = ["tbd", "bye", "qualifier", "winner of", "loser of", "to be confirmed", "n/a"]


def is_placeholder(name):
    t = str(name or "").strip().lower()
    if not t:
        return True
    return any(t == p or t.startswith(p) for p in PLACEHOLDERS)


def norm_key(s):
    out = []
    for ch in str(s if s is not None else "").lower():
        if ch.isalnum():
            out.append(ch)
    return "".join(out)


def parse_iso(s):
    """ESPN дава „2026-05-24T15:00Z" (без секунди), FIVB дава без Z изобщо."""
    t = str(s or "").strip()
    if not t:
        return None
    if t.endswith("Z"):
        t = t[:-1] + "+00:00"
    try:
        d = datetime.fromisoformat(t)
    except ValueError:
        for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%dT%H:%M", "%Y-%m-%d"):
            try:
                d = datetime.strptime(t[:len(fmt) + 2], fmt)
                break
            except ValueError:
                d = None
        if d is None:
            return None
    if d.tzinfo is None:
        d = d.replace(tzinfo=timezone.utc)
    return d


def days_between(iso_date, now):
    d = parse_iso(iso_date)
    if d is None:
        return None
    return (now - d).total_seconds() / 86400.0


def when_label(dt_utc, now):
    """Час по българско, а ако мачът е за друг ден — и денят."""
    if dt_utc is None:
        return ""
    loc = dt_utc.astimezone(SOFIA)
    hm = loc.strftime("%H:%M")
    delta = (loc.date() - now.date()).days
    if delta == 0:
        return hm
    if delta == 1:
        return "утре " + hm
    if delta == -1:
        return "вчера " + hm
    return WEEKDAYS[loc.weekday()] + ", " + str(loc.day) + "." + ("%02d" % loc.month) + " " + hm


def fx_start(fx, now):
    """Кога започва срещата — час със зона, или None ако източникът не е казал.

    Повечето източници дават пълна дата в полето „when". Последната резерва
    (TheSportsDB) дава само „21:30" вече по българско и без ден. Един капан:
    мач в 23:40 UTC днес е 02:40 БЪЛГАРСКО за УТРЕ, а низът пази само часа.
    Затова час преди 05:00, погледнат след обяд, се чете като утрешен."""
    w = fx.get("when")
    if isinstance(w, datetime):
        return w if w.tzinfo is not None else w.replace(tzinfo=timezone.utc)
    t = str(fx.get("time") or "").strip()[:5]
    if len(t) == 5 and t[2] == ":" and t[:2].isdigit() and t[3:].isdigit():
        hh, mm = int(t[:2]), int(t[3:])
        if hh > 23 or mm > 59:
            return None
        loc = now.replace(hour=hh, minute=mm, second=0, microsecond=0)
        if hh < 5 and now.hour >= 12:
            loc = loc + timedelta(days=1)
        return loc
    return None


def started(fx, now):
    """True = мачът вече тече, свършил е, или започва прекалено скоро.
    Не гадаем: няма ли източникът час, срещата минава напред."""
    s = fx_start(fx, now)
    if s is None:
        return False
    return s <= now + timedelta(minutes=LEAD_MIN)


def ymd_za(now, bucket):
    """Кой ДЕН (или диапазон дни) да поискаме от ESPN за този спорт.

    Спорт с общия хоризонт -> един ден, както винаги. Спорт със свой,
    по-дълъг хоризонт -> диапазон „от-до", защото не играе всеки ден.
    Модулна е нарочно, а не скрита в collect_all: скрита функция не може
    да бъде проверена, а точно тук се роди дефектът.
    """
    dnes = now.strftime("%Y%m%d")
    h = horizont_za(bucket)
    if h <= HORIZON_H:
        return dnes
    return dnes + "-" + (now + timedelta(hours=h)).strftime("%Y%m%d")


def too_far(fx, now, bucket=None):
    """True = срещата е още далече. Не я пропускаме — изчакваме я.
    Следващото пускане е след три часа и тя ще влезе в прозореца сама.

    🔴 ХОРИЗОНТЪТ Е ПО СПОРТ (01.09.2026). Общите 30 часа правеха амер.
    футбола недостижим: колежанският играе в събота, а ботът гледаше
    ден и половина напред. Виж бележката при HORIZONT_PO_SPORT.
    Без подаден bucket се пада на общия — старото поведение.
    """
    s = fx_start(fx, now)
    if s is None:
        return False
    return s > now + timedelta(hours=horizont_za(bucket))


def bg_name(s):
    """Малка карта на имената. Каквото не е в нея, остава както го дава източникът."""
    t = str(s or "").strip()
    return BG_NAME.get(t, t)


