# ---------------------------------------------------------------- МРЕЖА
UA = ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
      "(KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36")

_http_cache = {}
_http_used = [0]
_http_fail = [0]
# Кой адрес не отговори и защо. Броячът горе казва „три провала" — а въпросът
# винаги е КОИ три. Тефтерът носи този списък навън, където се чете без права.
_http_why = []
HTTP_WHY_MAX = 40


def _brotli(raw):
    try:
        import brotli as _br
        return _br.decompress(raw)
    except ImportError:
        pass
    try:
        import brotlicffi as _br2
        return _br2.decompress(raw)
    except ImportError:
        pass
    raise RuntimeError("нужен е модул brotli (pip install brotli)")


# 🔴 ЗАЩО ESPN НЕ ПОЛУЧАВА ПОДПИС (измерено на живо на 11.08.2026)
#
# Пет спорта — футбол, тенис, баскетбол, хокей, ММА и американски футбол —
# мълчаха с ДНИ. Черната кутия показа 403 Forbidden на всеки адрес на ESPN.
# Първата мисъл е „блокират сървъра на GitHub". Грешна. Същият 403 идваше и на
# домашната машина. Тестът беше един адрес, една минута, сменя се само подписът:
#
#     с фалшивия Chrome подпис горе  ->  403 Forbidden
#     без никакъв подпис             ->  200 и 10 срещи
#     с подписа на самия Python      ->  200 и 10 срещи
#     с измислен подпис „GreenPicks" ->  403 Forbidden
#
# Тоест ESPN не пази данните — пази се от преправени клиенти. Маскировката
# БЕШЕ причината. Затова тук подписът се маха точно за ESPN, а за WTT и FIVB,
# които го искат, остава.
NO_UA_HOSTS = ("espn.com",)


def glavi_za(url, headers=None):
    """Кои глави заминават с една заявка. Отделено, за да се проверява само."""
    hd = ({"Accept": "application/json"}
          if any(h in url for h in NO_UA_HOSTS)
          else {"User-Agent": UA, "Accept": "*/*"})
    if headers:
        hd.update(headers)
    return hd


def http_bytes(url, headers=None, timeout=30):
    """Една заявка навън, с таван, пауза и разсгъстяване. Хвърля при провал."""
    if _http_used[0] >= HTTP_BUDGET:
        raise RuntimeError("изчерпан лимит заявки (" + str(HTTP_BUDGET) + ")")
    hd = glavi_za(url, headers)
    time.sleep(HTTP_GAP)
    _http_used[0] += 1
    req = urllib.request.Request(url, headers=hd)
    with urllib.request.urlopen(req, timeout=timeout) as r:
        raw = r.read()
        enc = (r.headers.get("Content-Encoding") or "").lower()
    if "br" in enc:
        raw = _brotli(raw)
    elif "gzip" in enc:
        raw = gzip.decompress(raw)
    elif "deflate" in enc:
        raw = zlib.decompress(raw)
    return raw


def http_text(url, headers=None, timeout=30):
    key = ("t", url)
    if key in _http_cache:
        return _http_cache[key]
    txt = http_bytes(url, headers, timeout).decode("utf-8-sig", "replace")
    _http_cache[key] = txt
    return txt


def http_json(url, headers=None, timeout=30, quiet=False):
    """Връща None при всякакъв провал — нито един спорт не бива да събори рън."""
    key = ("j", url)
    if key in _http_cache:
        return _http_cache[key]
    try:
        data = json.loads(http_text(url, headers, timeout) or "null")
    except Exception as e:                      # noqa: BLE001
        _http_fail[0] += 1
        if len(_http_why) < HTTP_WHY_MAX:
            _http_why.append(url.replace(ESPN_SITE, "espn")[:70]
                             + " -> " + str(e)[:40])
        if not quiet:
            print("   ⚠ " + url[:78] + " -> " + str(e)[:70])
        data = None
    _http_cache[key] = data
    return data


# ---------------------------------------------------------------- ТЕФТЕРЪТ
def _empty_state():
    return {"v": 1, "posted": {}}


def load_state():
    """Самолекуващ се: счупен или чужд JSON = започваме начисто, без да падаме."""
    # Тефтерът на цените се нулира ПЪРВО: чужд или липсващ файл трябва да
    # остави празна редица, а не остатъци от предишно четене.
    ceni_zaredi(None)
    try:
        with open(STATE_FILE, encoding="utf-8-sig") as f:
            d = json.load(f)
        if isinstance(d, dict) and isinstance(d.get("posted"), dict):
            # 🔴 ТЕФТЕРЪТ НА ЦЕНИТЕ СЕ ВРЪЩА ЖИВ. Дотук load_state изхвърляше
            # всичко освен „posted" — ново поле щеше да живее едно пускане и
            # да умира при следващото, тихо. Редицата обаче Е стойността тук:
            # без вчерашната първа цена днешното движение е нула по строеж.
            ceni_zaredi(d.get("ceni"))
            return {"v": 1, "posted": dict(d["posted"])}
        if isinstance(d, list):     # мост от най-стар формат: само списък ключове
            return {"v": 1, "posted": {str(k): "" for k in d if isinstance(k, str)}}
        print("тефтерът " + STATE_FILE + " е с непознат вид — започвам начисто.")
    except FileNotFoundError:
        pass
    except Exception as e:          # noqa: BLE001
        print("тефтерът " + STATE_FILE + " е повреден (" + str(e)[:60] + ") — започвам начисто.")
    return _empty_state()


# ═══════════════════════════ 🔴 БРОЯЧ НА ИЗЛЕЗЛИТЕ КАРТИ (25.08.2026, задача 3)
# ЗАЩО. Зелен рън + нула изпратени карти изглеждаше ТОЧНО като зелен рън с
# карти. Отказът се изричаше само с print в дневника на Actions, който отвън е
# недостъпен — виж „черната кутия" по-долу. Видяно в самата самопроверка:
# „ОТКАЗ: в текста се промъкна забранена дума — не пращам." Такава карта се
# губеше МЪЛЧАЛИВО и рънът оставаше зелен.
#
# Тук се само ЗАПИСВА. Тревогата я вдига друг файл — това не е негова работа.
# Ключовете са на латиница нарочно: тефтерът се чете и от чужди инструменти.
OTCHET = {"prateni": 0, "suho": 0, "otkazani": {}}


def otkaz(prichina):
    """Един отказ, по причина. Връща False, за да се пише на един ред."""
    k = str(prichina)
    OTCHET["otkazani"][k] = int(OTCHET["otkazani"].get(k) or 0) + 1
    return False


def otchet_sbor():
    """Колко са отказите общо. Отделно от речника, за да не се брои на ръка."""
    return sum(int(v or 0) for v in OTCHET["otkazani"].values())


# ═══════════════════════════ 📈 ТЕФТЕРЪТ НА ЦЕНИТЕ И ДВИЖЕНИЕТО (02.09.2026)
#
# ЗАЩО СЪЩЕСТВУВА. Ботът вижда цена на ВСЯКО пускане (24 крона на ден, тоест
# на час), а пазеше САМО последната точка. Редицата — единственото, от което
# може да се извади ДВИЖЕНИЕ — се хвърляше.
# ПРОВЕРЕНО В ТАЗИ СЕСИЯ: търсене в целия този файл преди промяната даде
# «otvaryashta» 0 · «opening» 0 · «dvizhenie» 0 срещания.
# 🔴 ЧЕСТНО ЗА ЕДНО ЧИСЛО: «591 от 1179 карти с pazar_cena» идва от ЖИВИЯ
# дневник в хранилището и НЕ Е сверено тук — местното копие на
# predict_log.json е старо (261 записа до 11.08, нула с pazar_cena).
#
# ИЗМЕРЕНО ТУК, НЕ ЗАЕТО (02.09.2026, 22 333 мача от ctxmodel_rows.pkl,
# полета oo/cc/res, bootstrap 2000 повторения, собствена сметка):
# Залог на страната, КЪМ която мърда линията, по ОТВАРЯЩА цена:
#     движение ≥2%  ->  ROI +8.6%  [+5.9..+11.7]  n=9638
#     движение ≥3%  ->  ROI +12.0% [+8.1..+16.1]  n=5322
#     движение ≥5%  ->  ROI +15.7% [+8.5..+22.9]  n=1460
# Контролата е ОГЛЕДАЛНА — залог СРЕЩУ движението дава −12.5% [−15.1..−9.8]
# при 2%, а при силно бягство (5%) −20.5% [−25.8..−15.3]. Огледалото е подпис
# на истински сигнал, не на намерена в шума разлика.
# 🔴 ПО ЗАТВАРЯЩА ЦЕНА РЪБЪТ ИЗЧЕЗВА: ≥3% дава −0.9% [−4.2..+2.2]. Целият ръб
# е в това да си РАНО — значи трябва ПЪРВАТА видяна цена, не последната.
#
# ИЗМЕРЕНО СУХО ДНЕС (02.09.2026, 16:52, басейн от 36 срещи, крон на час):
#     30 от 36 срещи (83%) се виждат в поне ДВЕ пускания
#     средно 6.2 пускания на среща · най-дългата редица 19 пускания
# Без това число цялата работа щеше да е украса: няма редица — няма движение.
#
# 🔴 НУЛА НОВИ ЗАЯВКИ. Тук не се пита нищо. Записва се цената, която
# dobavi_pazar и без това е взела за тази среща в това пускане. Ако това
# значи, че първата цена идва от първото пускане, в което срещата влиза в
# хоризонта — това е точно каквото трябва.
#
# 🔴 ТУК НЯМА ПОРТИЕР И НЯМА ДА ИМА ДНЕС. Историческото измерване е по
# ОТВАРЯЩА цена на ЧУЖД пазар; на НАШИТЕ данни нямаме нито един ден
# наблюдение. Първо две седмици събиране, после решение. Дотогава числото
# само се ЗАПИСВА (карта + дневник) и се ПОКАЗВА (изходът на пускането и
# черната кутия).
#
# ПОСОКАТА, за да не се чете наопаки: ПОЛОЖИТЕЛНО движение значи, че
# имплицитната вероятност на НАШИЯ изход е ПОРАСНАЛА, тоест цената му е
# паднала и пазарът е дошъл при нас. Отрицателно значи, че бяга от нас.
DVIZHENIE_VKL = env_int("PREDICT_DVIZHENIE", 1, 0, 1) == 1
# 🔴 ЗАЩО ТОЗИ КЛЮЧ НЕ Е В KLYUCHOVE_ZA_YML (02.09.2026). Проверката
# «predict.yml подава всяка ръчка» чете САМИЯ predict.yml и пада, ако име от
# списъка го няма там. Нямам право да пипам yml-а, значи добавянето сега щеше
# да счупи самопроверката. Редът за yml-а е написан в доклада; щом влезе там,
# името се добавя и в списъка — не преди това. Дотогава ръчката работи, но се
# върти само отвън през средата.

# Тефтерът: ключ на срещата -> {t0, p0, c0, t1, p1, c1, n}. Живее в
# predict_state.json до „posted" и се чисти по същия прозорец.
CENI = {}
# Часът на ТОВА пускане. Заковава се при ПЪРВОТО записване и не се мени до
# края на процеса (един крон = едно пускане = един процес). Нужен е, защото
# dobavi_pazar се вика ДВА пъти за една карта в едно пускане (веднъж от
# портиера, веднъж при пращането) и без общ печат редицата би броила
# виканията вместо пусканията.
PUSKANE = None


def _puskane_chas(sega=None):
    """Часът на това пускане. Подаденият час винаги бие закования.

    🔴 ЗАЩО НЕ Е РЕД В run() (02.09.2026). Първо го написах там. Мутационният
    тест го махна и НУЛА проверки паднаха: run() иска мрежа и цял ден, тоест
    редът беше недостижим за самопроверката — точно определението за украса.
    Тук същото нещо е ПОВЕДЕНИЕ, което може да бъде питано.
    """
    global PUSKANE
    if sega is not None:
        return sega
    if PUSKANE is None:
        PUSKANE = datetime.now(SOFIA)
    return PUSKANE


def _izhod_ot_pick(pick):
    """«1 · Левски» -> «1». Латинското X и кирилското Х са ЕДИН изход."""
    s = str(pick or "").strip()[:1]
    return "Х" if s in ("X", "Х") else s


def bez_marzh_del(ceni):
    """Имплицитни вероятности с ПРОПОРЦИОНАЛНО махнат марж.

    p_i = (1/k_i) / Σ(1/k_j) — точно формулата, с която е мерен ръбът върху
    22 333 мача. Своя е нарочно, а не заемка от pazar.bez_marzh: там наборът
    изходи се съди по чужда таблица (IZHODI) и по НАШЕТО име на спорта, а тук
    наборът трябва да е един и същ в ДВАТА края на редицата — инак сравняваме
    тройка с двойка и произвеждаме «движение» от нищото.

    Празен речник значи «не може да се отговори». Три причини за мълчание:
      • по-малко от ДВА изхода — от една цена марж не се маха;
      • сбор под 0.95 — липсва изход (футбол без равенството дава ~0.74 и
        нормировката по два изхода от три би била лъжа);
      • сбор над 1.6 — това не е пазар, а боклук.
    Сбор РОВНО 1.00 се ПРИЕМА: борсата (местният тенис на маса) работи с
    марж 0.3%, а изкуствено равните цени в проверките дават точно 1.
    """
    ob = {}
    for k, c in (ceni or {}).items():
        try:
            v = float(c)
        except (TypeError, ValueError):
            continue
        if 1.0 < v < 1000.0:
            ob[str(k)] = 1.0 / v
    s = sum(ob.values())
    if len(ob) < 2 or not (0.95 < s <= 1.6):
        return {}
    return dict((k, round(v / s, 6)) for k, v in ob.items())


def ceni_klyuch(an):
    """Ключът на срещата в тефтера. СЪЩИЯТ като на `posted` — нарочно:
    два ключа за едно нещо се разминават мълчаливо и после никой не разбира
    защо редицата е празна."""
    if not isinstance(an, dict):
        return ""
    return str((an.get("fx") or {}).get("_key") or "")


def ceni_zaredi(d):
    """Пълни тефтера от прочетения JSON. Чужд вид = празен тефтер, не гърмеж."""
    CENI.clear()
    if not isinstance(d, dict):
        return 0
    for k, v in d.items():
        if isinstance(v, dict) and isinstance(v.get("p0"), dict):
            CENI[str(k)] = v
    return len(CENI)


def ceni_zapishi(klyuch, ceni, sega=None):
    """Слага ЕДНА точка от редицата. ПЪРВАТА никога не се презаписва.

    Връща записа или None (угасен ключ, липсващ ключ на срещата, или цени,
    от които марж не може да се махне).
    """
    if not DVIZHENIE_VKL or not klyuch:
        return None
    p = bez_marzh_del(ceni)
    if not p:
        return None
    sega = _puskane_chas(sega)
    kt = sega.strftime("%Y-%m-%d %H:%M")
    sur = {}
    for k in p:
        try:
            sur[k] = round(float((ceni or {}).get(k)), 4)
        except (TypeError, ValueError):
            pass
    z = CENI.get(klyuch)
    if not isinstance(z, dict) or not isinstance(z.get("p0"), dict):
        # ПЪРВОТО виждане. Оттук нататък p0/c0/t0 не се пипат от никого.
        z = {"t0": kt, "p0": p, "c0": sur, "n": 0}
        CENI[klyuch] = z
    if z.get("t1") == kt and int(z.get("n") or 0) >= 1:
        # Същото пускане, второ викане: обновяваме последната точка, но НЕ
        # броим втора. Инак `n` щеше да мери колко пъти е викана функцията.
        z["p1"], z["c1"] = p, sur
        return z
    z["t1"], z["p1"], z["c1"] = kt, p, sur
    z["n"] = int(z.get("n") or 0) + 1
    return z


def dvizhenie(fx, pick=None):
    """Колко се е преместила имплицитната вероятност на НАШИЯ изход.

    Приема или самата среща (речник с «_key»), или целия анализ (речник с
    «fx» и «pick») — второто, за да може да се вика с една дума.

    Положително = пазарът е ДОШЪЛ при нас. Отрицателно = бяга от нас.
    None означава мълчание, а не нула: непозната среща, липсващ изход или
    СМЕНЕН набор изходи между двата края (тройка срещу двойка е различна
    нормировка и разликата им би била измислена).
    Една-единствена точка в редицата дава точно 0.0 — това е ИЗМЕРЕНА нула.
    """
    fx = fx if isinstance(fx, dict) else {}
    if pick is None and isinstance(fx.get("fx"), dict):
        pick, fx = fx.get("pick"), fx.get("fx")
    z = CENI.get(str(fx.get("_key") or ""))
    if not isinstance(z, dict):
        return None
    p0, p1 = z.get("p0") or {}, z.get("p1") or {}
    if not p0 or sorted(p0) != sorted(p1):
        return None
    s = _izhod_ot_pick(pick)
    if s not in p0:
        return None
    try:
        return round(float(p1[s]) - float(p0[s]), 4)
    except (TypeError, ValueError):
        return None


def ceni_pochisti(sega, keep=None):
    """Маха записите, невиждани от STATE_KEEP_DAYS дни — СЪЩИЯТ прозорец и
    същият принцип като „posted" в save_state. Без това файлът расте вечно."""
    if keep is None:
        keep = set()
        for i in range(0, STATE_KEEP_DAYS):
            keep.add((sega - timedelta(days=i)).strftime("%Y-%m-%d"))
    for k in [k for k, v in list(CENI.items())
              if str((v or {}).get("t1") or (v or {}).get("t0") or "")[:10]
              not in keep]:
        CENI.pop(k, None)
    return len(CENI)


def zapishi_cena(an, sega=None):
    """Една точка в редицата + движението В КАРТАТА. Нула нови заявки.

    Цените се етикетират по ИЗХОД («1»/«2»/«Х»), а не по «наша/друга»:
    изборът може да се обърне между две пускания (виж `obarnata`) и тогава
    «нашата цена» сочи друга страна — редица, събрана по този етикет, би
    сравнявала домакин с гост.
    """
    if not DVIZHENIE_VKL or not isinstance(an, dict):
        return an
    k = ceni_klyuch(an)
    if not k:
        return an
    sur = an.get("_ceni_sur")
    if not isinstance(sur, dict):
        # Резервен път: двете страни, които картата и без това носи. Работи
        # за «1» и «2»; чисто равенство без другите два изхода остава ням —
        # и това е вярно, защото от една цена марж не се маха.
        _p = _izhod_ot_pick(an.get("pick"))
        _n, _d = an.get("pazar_cena"), an.get("pazar_cena_drug")
        sur = ({"1": _n, "2": _d} if _p == "1"
               else ({"2": _n, "1": _d} if _p == "2" else {}))
    sur = dict((kk, vv) for kk, vv in sur.items() if vv)
    if not ceni_zapishi(k, sur, sega):
        return an
    d = dvizhenie(an.get("fx"), an.get("pick"))
    if d is None:
        return an
    z = CENI.get(k) or {}
    an["dvizhenie"] = d
    an["dvizhenie_n"] = int(z.get("n") or 0)
    an["dvizhenie_koga"] = z.get("t0")
    an["dvizhenie_ot"] = (z.get("c0") or {}).get(_izhod_ot_pick(an.get("pick")))
    return an


def save_state(state, now):
    """Пазим само последните дни — файлът не бива да расте вечно.
    Прозорецът е по-широк от хоризонта на събирането нарочно (виж
    STATE_KEEP_DAYS): забравен запис = повторена карта."""
    keep = set()
    for i in range(0, STATE_KEEP_DAYS):
        keep.add((now - timedelta(days=i)).strftime("%Y-%m-%d"))
    posted = {k: v for k, v in (state.get("posted") or {}).items() if str(v)[:10] in keep}
    # Същият прозорец и за цените: запис, невиждан STATE_KEEP_DAYS дни, е мач,
    # който отдавна е изигран.
    ceni_pochisti(now, keep)
    try:
        tmp = STATE_FILE + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            # „diag" е черната кутия: колко срещи е видял ботът по спорт в
            # ПОСЛЕДНОТО пускане. Записва се тук, защото този файл се връща в
            # хранилището и се чете отвън — за разлика от дневника на GitHub.
            # 🔴 „karti" (25.08.2026, задача 3): колко карти са ИЗЛЕЗЛИ наистина
            # и колко са ОТКАЗАНИ, по причина. Стои до „diag", защото има същата
            # съдба — този файл се връща в хранилището и се чете отвън.
            json.dump({"v": 1, "posted": posted,
                       # 📈 Редицата от цени: ПЪРВАТА видяна цена за всяка
                       # среща, часът ѝ и последната. Виж тефтера на цените.
                       "ceni": dict(CENI),
                       "diag": {"koga": now.strftime("%Y-%m-%d %H:%M"),
                                "sportove": DIAG,
                                # с какви настройки е работило пускането — за
                                # да не се гадае отвън дали променливата
                                # изобщо е стигнала до процеса
                                "klyuchove": klyuchove_diag()},
                       "karti": {"koga": now.strftime("%Y-%m-%d %H:%M"),
                                 "prateni": OTCHET["prateni"],
                                 "suho": OTCHET["suho"],
                                 "otkazani_sbor": otchet_sbor(),
                                 "otkazani": dict(OTCHET["otkazani"])}},
                      f, ensure_ascii=False)
        os.replace(tmp, STATE_FILE)     # атомарно: убит рън не оставя счупен JSON
        return True
    except Exception as e:              # noqa: BLE001
        print("тефтерът не се записа (" + str(e)[:70] + ") — следващият рън може да повтори.")
        return False


def match_key(fx, now):
    """Ключ на срещата. Стабилен през източниците и през пусканията.

    Датата в ключа е ДЕНЯТ НА МАЧА, не денят на пускането. Така една гала на
    ММА, която се вижда пет дни предварително, получава един и същ ключ на
    всяко пускане и излиза точно веднъж. (Няма ли час, падаме на днешния ден.)
    „vb" отделя мъжете от жените и от юношите: България - Италия при мъжете и
    България - Италия при жените са ДВЕ различни срещи в един и същи ден и без
    тази добавка втората карта мълчаливо се брои за повторение."""
    tag = norm_key((fx.get("extra") or {}).get("vb") or "")
    s = fx_start(fx, now)
    day = (s.astimezone(SOFIA) if s is not None else now).strftime("%Y-%m-%d")
    return (day + "|" + str(fx.get("bucket"))
            + (("|" + tag) if tag else "")
            + "|" + norm_key(fx.get("home"))[:24] + "|" + norm_key(fx.get("away"))[:24])


def already_posted(state, key):
    return key in (state.get("posted") or {})


def mark_posted(state, key, now):
    state.setdefault("posted", {})[key] = now.strftime("%Y-%m-%d %H:%M")


# 🔴 РАЗШИРЕН 18.08.2026 — ИЗМЕРЕНО В ЖИВИЯ ТЕФТЕР.
# Тук стояха само три служебни ключа. Но фишовете също пишат в тефтера:
# „ден|combos" отдавна, а от 12.08 и „ден|combo1/2/3" (собствен ключ на всеки
# фиш, за да може убит рън да се възобнови). Нито един от тях не беше обявен
# за служебен — значи cards_today ги броеше за ПРОГНОЗИ и те ядяха от дневния
# таван. Проверено на живо: за 16.08 тефтерът дава combo1, combo2, combo3 и
# combos — четири „карти", които никога не са били карти.
# И вторият ефект: karti_dnes_po_sport ги виждаше като СПОРТОВЕ.
SERVICE_KEYS = ("|header", "|footer", "|nothing", "|combos",
                "|combo1", "|combo2", "|combo3", "|combo4", "|combo5")


def posted_today(state, now):
    """Пуснато ли е ВЕЧЕ нещо днес? (осем пускания на ден — трябва да знаем)"""
    d = now.strftime("%Y-%m-%d")
    return any(str(v)[:10] == d for v in (state.get("posted") or {}).values())


def cards_today(state, now):
    """Колко ПРОГНОЗИ са излезли днес. Заглавието и подписът не се броят —
    те не са прогнози и не бива да ядат от дневния таван."""
    d = now.strftime("%Y-%m-%d")
    n = 0
    for k, v in (state.get("posted") or {}).items():
        if str(v)[:10] != d or str(k).endswith(SERVICE_KEYS):
            continue
        n += 1
    return n


def nepoznati_klyuchove(state):
    """Кои видове ключове в тефтера НЕ са нито спорт, нито обявени за служебни.

    🔴 18.08.2026. Точно това ни ухапа: „|combos" и „|combo1..3" не бяха в
    служебния списък, значи се брояха за прогнози и ядяха от дневния таван —
    четири места на ден при утринен таван шестнайсет. Никой тест не гръмна,
    защото никой не сравняваше ВИДОВЕТЕ ключове с двата известни списъка.
    Сега се сравняват. Нов вид ключ утре ще се обади сам.
    """
    vidove = set()
    for k in (state.get("posted") or {}):
        chasti = str(k).split("|")
        if len(chasti) > 1:
            vidove.add(chasti[1])
    izvestni = set(SPORTS) | {s.lstrip("|") for s in SERVICE_KEYS}
    return sorted(vidove - izvestni)


def karti_dnes_po_sport(state, now):
    """Колко прогнози са излезли ДНЕС, разбито по спорт.

    Ключът е „ден|спорт|…", затова спортът се вади от втората част. Служебните
    ключове (заглавие, подпис, фишове) не се броят — те не са прогнози.
    """
    d = now.strftime("%Y-%m-%d")
    broy = {}
    for k, v in (state.get("posted") or {}).items():
        if str(v)[:10] != d or str(k).endswith(SERVICE_KEYS):
            continue
        chasti = str(k).split("|")
        if len(chasti) < 2:
            continue
        b = chasti[1]
        broy[b] = broy.get(b, 0) + 1
    return broy


def persist(state, now):
    """Записва тефтера, но НИКОГА при сухо пускане: иначе пробното пускане
    отбелязва мачовете като пуснати и истинското после мълчи."""
    if DRY_RUN:
        return False
    return save_state(state, now)


# ------------------------------------------------- ДНЕВНИКЪТ НА ПРОГНОЗИТЕ
# ЗАЩО СЪЩЕСТВУВА
# Тефтерът predict_state.json помни САМО че една среща е пусната — ключ и час.
# Не помни КАКВО сме предсказали. Затова стая 9 „Резултати" и стая 10
# „Печеливши" нямаше как да покажат дали ботът е познал: данните просто ги
# нямаше никъде. Тук записваме самото твърдение — кой, срещу кого, кого сме
# посочили, с каква вероятност и колко звезди — за да може scorer.py после да
# го сравни с истинския резултат.
#
# Файлът е списък, не речник: един ред = едно твърдение, в реда на пускане.
# Не се трие нищо. Сгрешените прогнози остават — това е продуктът.
PICKLOG_FILE = (os.environ.get("PREDICT_LOG_FILE") or "predict_log.json").strip()
# 🔴 400 → 5000 НА 18.08.2026. ДНЕВНИКЪТ СЕ ТРИЕШЕ, НЕ СЕ ПАЗЕШЕ.
#
# Този таван реже най-старите записи при ВСЯКО дописване. При 40 карти на ден
# 400 значи ДЕСЕТ ДНИ история — после всеки нов запис изяжда по един стар.
# Живият дневник стоеше на ТОЧНО 400: таванът беше запушен, не с резерва.
# Измерено: 95 записа от 29.07-05.08 вече ги няма, от тях 50 отсъдени.
#
# И най-лошото — публичното число лъжеше заради това: футболът показваше
# 61% (19 от 31), а по цялата история е 50% (21 от 42). Единайсет пункта
# грешка на стената, произведена само от триенето.
#
# Архивът, писан вчера, беше МЪРТЪВ ПО РОЖДЕНИЕ: оценителят архивира на
# 120-ия ден, а предсказателят триеше на 10-ия. Нищо не стигаше до архива.
#
# Правилото: таванът ТРЯБВА да е над MAX_DAY × ARHIV_DNI, иначе триенето
# изпреварва архивирането. 40 × 60 = 2400; 5000 дава двойна резерва и след
# есенното удвояване на обема.
def _arhiv_dni_ot_scorer(chetec=None):
    """ARHIV_DNI от scorer.py. 0, ако не се прочете — тогава не се смята.

    🔴 Чете се от ЕДНО място и се ползва на ДВЕ (тук и в самопроверката).
    Дотук проверката си го четеше сама, а кодът работеше с гола константа —
    значи двете можеха да се разминат и никой нямаше да усети.
    """
    try:
        if chetec is None:
            put = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                               "scorer.py")
            with open(put, encoding="utf-8-sig") as _f:
                s = _f.read()
        else:
            s = chetec()
    except (OSError, UnicodeDecodeError):
        return 0
    i = s.find("ARHIV_DNI = max(")
    if i < 0:
        return 0
    hv = s[i:s.find(")))", i)]
    c = [x for x in hv.split('"') if x.strip().isdigit()]
    try:
        return int(c[-1]) if c else 0
    except ValueError:
        return 0


ARHIV_DNI_SVEREN = _arhiv_dni_ot_scorer()

# 🔴 СМЕТКАТА Е АВТОМАТИЧНА (02.09.2026). Дотук това беше гола константа и
# връзката с MAX_DAY се пазеше САМО от проверка, която казва «не го прави».
# Тоест вдигнеш ли дневния таван от GitHub, дневникът НЕ порасва с него и
# триенето изпреварва архивирането — точно случката от 18.08 (таван 400 при
# нужни 4800, 95 изгубени записа, футболът показваше 61% вместо 50%).
#
# Сега дневникът расте СЪС САМИЯ таван, с 40% запас. Капанът не може да се
# отвори: който вдигне MAX_DAY, вдига и това.
PICKLOG_KEEP = max(
    env_int("PREDICT_LOG_KEEP", 5000, 20, 40000),
    int(MAX_DAY * ARHIV_DNI_SVEREN * 1.4) if ARHIV_DNI_SVEREN else 0)


def log_pick(an, now, combo=0):
    """Добавя едно твърдение към дневника. Провалът тук НЕ спира картите.

    combo = номер на фиша, ако този избор е крак от комбиниран фиш. Нула значи
    самостоятелна карта. Ако мачът вече е в дневника, само му се дописва
    номерът на фиша — не се вписва втори път.
    """
    if DRY_RUN:
        return False
    fx = an.get("fx") or {}
    when = fx_start(fx, now)
    rec = {
        "key": fx.get("_key"),
        "combo": int(combo or 0),
        "posted": now.strftime("%Y-%m-%d %H:%M"),
        "day": (when.astimezone(SOFIA) if when is not None else now).strftime("%Y-%m-%d"),
        "bucket": an.get("bucket"),
        "home": fx.get("home"), "away": fx.get("away"),
        "home_id": fx.get("home_id"), "away_id": fx.get("away_id"),
        "league": fx.get("league"),
        "slug": (fx.get("extra") or {}).get("slug"),
        # 🔴 БЕЗ ТЕЗИ ДВА РЕДА ITF КАРТАТА ВИСИ ВЕЧНО (19.08.2026).
        # Оценителят праща всичко от кошницата „tennis" към tennis_result(),
        # който чете САМО ESPN atp/wta таблата. ITF мач го няма там — значи
        # sport_result() връща None при всяко пускане, докато записът не
        # изтече по възраст и не се затвори с „hit: None". Тоест карта без път
        # до присъда: тя не се брои нито за познат, нито за сгрешен, а трови
        # процента на целия спорт. `src` казва на оценителя коя врата да
        # отвори, `itf_id` е точният номер на мача в онзи фийд.
        "src": fx.get("src"),
        "itf_id": (fx.get("extra") or {}).get("itf_id"),
        # 🎮 БЕЗ ТОЗИ КЛЮЧ ТРИТЕ ИГРИ СА ЕДИН СПОРТ (25.08.2026).
        # Кошът е един („esports"), защото стаята е една. Но CS2, League
        # of Legends и Valorant са три РАЗЛИЧНИ дисциплини и сборът им е
        # средно на три различни неща. Редът „📈 ... досега: 4 познати от
        # 12" щеше да е точно такъв сбор. Ключът се пише ТУК, защото
        # разделянето може да се направи само върху записи, които го имат
        # — старите остават слети и това си е загуба, но еднократна.
        "igra": (fx.get("extra") or {}).get("igra"),
        "pick": an.get("pick"),
        # 🔴 13.08.2026. Пазарната цена и вероятността, която тя значи. Пазят
        # се, за да може после да се отговори на въпроса, който наистина мери
        # качество: бием ли пазара, или само познаваме фаворити.
        "pazar_cena": an.get("pazar_cena"),
        # Цената на ДРУГАТА страна — за да се вижда колко неравен е
        # мачът и да може грешката да се мери в двете посоки.
        "pazar_cena_drug": an.get("pazar_cena_drug"),
        "pazar_p": an.get("pazar_p"),
        # 📈 ДВИЖЕНИЕТО НА ЛИНИЯТА (02.09.2026). Разликата в имплицитната
        # вероятност на НАШИЯ изход между ПЪРВАТА видяна цена и цената в мига
        # на картата. Портиер няма — това е събиране на данни, за да може
        # ръбът, мерен на 22 333 ЧУЖДИ мача, да бъде премерен на НАШИТЕ.
        # Без «ot» и «koga» числото е непроверимо: не се знае от коя цена и
        # отпреди колко часа е тръгнало.
        "dvizhenie": an.get("dvizhenie"),
        "dvizhenie_ot": an.get("dvizhenie_ot"),
        "dvizhenie_n": an.get("dvizhenie_n"),
        "dvizhenie_koga": an.get("dvizhenie_koga"),
        # 🔴 НАШЕТО СОБСТВЕНО ЧИСЛО, ПРЕДИ СМЕСВАНЕТО (25.08.2026).
        #
        # sglasie.TEGLO = 0.00 значи: където ИМА пазар, крайното `p` Е
        # пазарната вероятност. Тоест дотук дневникът пазеше едно и също
        # число два пъти (p и pazar_p) и НИТО ВЕДНЪЖ нашето.
        #
        # Измерено на 25.08.2026 върху 759 записа: p_model присъства в 0.
        # Следствието беше, че въпросът „нашият модел по-добър ли е от
        # пазара НА СЪЩИЯ МАЧ" не може да бъде зададен. Единственото
        # възможно сравнение — „с пазар" срещу „без пазар" — е объркано
        # от спорта: половината с пазар е футбол (92 от 215), другата е
        # тенис на маса и волейбол. Мерено вътре във всеки спорт, и петте
        # интервала минават през нулата.
        #
        # Полето е ДОБАВЪЧНО: нищо не го чете, старите записи си остават
        # без него, и всеки читател трябва да понесе липсата (.get, не []).
        "p_model": an.get("p_model"),
        # 🔴 СИЛАТА — ВТОРИЯТ ЧЛЕН НА КЛЮЧА ЗА ПОДРЕДБА (26.08.2026).
        #
        # Ред 6864 решава КОИ карти излизат:
        #     stars * 1000.0 + strength * 100.0
        # Дотук вторият член НЕ СЕ ЗАПИСВАШЕ никъде — 0 от 759 записа.
        #
        # Цената беше платена същата нощ: мерене на ключа върху дневника
        # дава strength = 0, тоест мери ГОЛИ ЗВЕЗДИ. Така се роди
        # твърдението „силата не мести нищо" — оборено: истинският AUC
        # на ключа е 0.5803, не 0.5481, а самата сила носи +14.2 точки
        # при p < 0.001 в симулация топ-6 на ден.
        # strength_binary(p) = |p-0.5|*2 (ред 1336) — тоест ключът е
        # ЛЕКСИКОГРАФСКИ: звездна лента, после увереност вътре в нея.
        #
        # Полето е ДОБАВЪЧНО. Нищо не го чете — служи, за да може
        # решението на бота да бъде проверено ОТВЪН, без да се
        # възстановява формулата от изходния код.
        "strength": an.get("strength"),
        "pazar_v": an.get("pazar_v"),
        "pit_home": ((an.get("fx") or {}).get("extra") or {}).get("pit_home"),
        "pit_away": ((an.get("fx") or {}).get("extra") or {}).get("pit_away"),
        "pazar_ev": an.get("pazar_ev"),
        "pazar_izt": an.get("pazar_izt"),
        "pazar_sport": an.get("pazar_sport"),
        "pazar_liga": an.get("pazar_liga"),
        # 🔴 25.08.2026. Без този ключ номерът на Pinnacle стига до паметта, но
        # НЕ и до дневника — тоест оценителят пак няма как да вземе цената.
        "pazar_obarnat": an.get("pazar_obarnat"),
        "p": round(float(an.get("p") or 0.0), 4),
        "stars": an.get("stars"),
        "sample": an.get("sample"),
        "scored": False,          # scorer.py го вдига на True
    }
    try:
        rows = []
        if os.path.exists(PICKLOG_FILE):
            with open(PICKLOG_FILE, encoding="utf-8-sig") as f:
                got = json.load(f)
            if isinstance(got, list):
                rows = got
        # Ако мачът вече е вписан (излязъл е като самостоятелна карта), само
        # му дописваме номера на фиша. Иначе оценителят би го броил два пъти.
        stara = None
        for r in rows:
            if r.get("key") and r.get("key") == rec.get("key"):
                stara = r
                break
        if stara is not None:
            if rec["combo"] and not stara.get("combo"):
                stara["combo"] = rec["combo"]
            rows = rows[-PICKLOG_KEEP:]
        else:
            rows.append(rec)
            rows = rows[-PICKLOG_KEEP:]
        tmp = PICKLOG_FILE + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(rows, f, ensure_ascii=False, indent=1)
        os.replace(tmp, PICKLOG_FILE)     # атомарно
        return True
    except Exception as e:                # noqa: BLE001
        print("дневникът на прогнозите не се записа (" + str(e)[:70] + ").")
        return False


# ---------------------------------------------------------------- ЕДИНСТВЕНИЯТ ИЗХОД
try:
    import zabraneni as ZB
except Exception:                                            # noqa: BLE001
    ZB = None


def banned_word(text):
    """Първата забранена дума в текста или None. Пазач срещу хазартна реклама.

    🔴 ПРЕМИНА КЪМ ОБЩИЯ ПАЗАЧ (01.09.2026). Дотук тук стоеше ГОЛ ПОДНИЗ върху
    `.lower()`, а в scorer.py — СЕДЕМ думи без нито едно име. Оборващ агент
    измери и двете посоки:

        един интервал по средата разбива 52 от 54 думи
        една точка по средата           54 от 54
        нулев интервал U+200B           54 от 54
        кирилско „е“ вместо латинско    25 от 25
        → „Palms Bet“, официалният изпис на български оператор, МИНАВАШЕ

    И обратното: „Pinnacle Cup V“ (истински турнир по CS2) и „M15 Coral
    Gables“ (град в имената на ITF) падаха мълчаливо с цялата карта.

    zabraneni.py прави и двете: нормализира текста И списъка по един и същ
    начин, сравнява и смачкано, и махa изключенията преди съденето.
    Резервата долу остава, за да не олекне пазачът мълчаливо при внос-провал.
    """
    if ZB is not None:
        return ZB.banned_word(text)
    low = str(text or "").lower()
    for w in BANNED_TOKENS:
        if w in low:
            return w
    return None


def tg_send(text, thread_id):
    """Праща с уважение към 429: чете retry_after и чака, вместо да блъска."""
    payload = {"chat_id": str(CHAT_ID), "text": text, "parse_mode": "HTML",
               "disable_web_page_preview": "true"}
    tid = str(thread_id or "").strip()
    if tid.isdigit() and int(tid) > 1:
        payload["message_thread_id"] = tid
    url = "https://api.telegram.org/bot" + BOT_TOKEN + "/sendMessage"
    for attempt in range(4):
        data = urllib.parse.urlencode(payload).encode()
        try:
            req = urllib.request.Request(url, data=data)
            with urllib.request.urlopen(req, timeout=25) as r:
                return bool(json.loads(r.read().decode("utf-8", "replace")).get("ok"))
        except urllib.error.HTTPError as e:
            raw = e.read().decode("utf-8", "replace")
            wait = 0
            try:
                wait = int(((json.loads(raw) or {}).get("parameters") or {}).get("retry_after") or 0)
            except Exception:       # noqa: BLE001
                wait = 0
            if e.code == 429 and attempt < 3:
                wait = wait if wait > 0 else 5
                print("429 — чакам " + str(wait + 1) + " сек и пробвам пак")
                time.sleep(wait + 1)
                continue
            print("sendMessage HTTP " + str(e.code) + " " + raw[:180])
            return False
        except Exception as ex:     # noqa: BLE001
            print("sendMessage FAIL: " + str(ex)[:140])
            if attempt < 3:
                time.sleep(3)
                continue
            return False
    return False


def post_predict(text, thread_id=None):
    """ЕДИНСТВЕНИЯТ изход на Предсказателя. Пазачите са ТУК, не по-нагоре.

    Разрешените стаи са изброени поименно в ALLOWED_THREADS: 27 (витрината),
    стаята на съответния спорт, и 4 за комбинираните фишове. Стая 26 остава
    забранена — новините са чужда работа. Канал няма: този файл няма функция,
    която да праща в канал.
    """
    tid = str(thread_id if thread_id is not None else PREDICT_THREAD).strip()
    # 🔴 ВСЕКИ ИЗХОД ОТСЮДА СЕ БРОИ (25.08.2026, задача 3). Дотук всеки от
    # петте отказа само се изричаше с print — тоест изчезваше заедно с дневника
    # на Actions. Броенето е ТУК, защото това е единствената врата навън: сложен
    # по-нагоре, броячът би пропуснал фишовете, тоталите и подписа.
    if tid in FORBIDDEN_THREADS:
        print("ОТКАЗ: стая " + tid + " е чужда (новини).")
        return otkaz("chuzhda_staya")
    if tid not in ALLOWED_THREADS:
        print("ОТКАЗ: стая " + tid + " не е в разрешените ("
              + ", ".join(sorted(ALLOWED_THREADS)) + ").")
        return otkaz("nerazreshena_staya")
    if not tid.isdigit() or int(tid) <= 1:
        print("WARN: невалиден thread id " + tid + " — не пращам.")
        return otkaz("nevaliden_id")
    bad = banned_word(text)
    if bad:
        print("ОТКАЗ: в текста се промъкна забранена дума (" + bad + ") — не пращам.")
        return otkaz("zabranena_duma")
    body = clip(text)
    if DRY_RUN:
        print(RULE)
        print(body)
        print(RULE)
        # Сухото пускане се брои ОТДЕЛНО. Слее ли се с „prateni", тефтерът щеше
        # да твърди, че са излезли карти, при положение че нищо не е пратено.
        OTCHET["suho"] += 1
        return True
    if not CHAT_ID or not BOT_TOKEN:
        print("Няма BOT_TOKEN/CHAT_ID — пропускам.")
        return otkaz("bez_token")
    if tg_send(body, tid):
        OTCHET["prateni"] += 1
        return True
    return otkaz("telegram")


# ═══════════════════ КОПИЕТО В СТАЯТА НА СПОРТА (26.08.2026)
# Всяка прогноза излиза ДВА ПЪТИ: веднъж в 27 (общата витрина) и веднъж,
# ДОСЛОВНО СЪЩАТА, в стаята на своя спорт. Това е нарочно от 29.07.2026 —
# собственикът отхвърли празните спортни стаи с думите „общи разписания, които
# нищо не значат". Причината СТОИ и затова копието не се маха по подразбиране.
#
# ИЗМЕРЕНО (log_sled.json, 759 карти за 21 ден, четено на 26.08.2026):
#   • всичките 759 карти имат стая на спорта → дублирането е по УСТРОЙСТВО
#   • 25.08: 51 прогнози → 36 дословни повторения (волейбол 15, футбол 11,
#     тенис на маса 8, баскетбол 2) = 36 от 87 картови съобщения за деня
#   • картата е 233–278 знака / 8–9 реда; съкратеният ред е 90 знака
#   • бейзбол (10) и тенис (5) от 25.08 НЕ се появиха втори път при абоната,
#     макар кодът да ги праща — стаите им идват от rooms_state.json. ЗАЩО
#     не кацат, оттук не се вижда; записано, не обяснено.
#
# ТРИТЕ ИЗХОДА СА ПРЕЗ СРЕДАТА. Подразбирането НЕ променя днешното поведение:
#   PREDICT_STAYA_REZHIM=pak     (подразбиране) — както днес, цялата карта
#   PREDICT_STAYA_REZHIM=kratko  — ЕДИН ред в стаята; картата остава в 27
#   PREDICT_STAYA_REZHIM=bez     — нищо в стаята (състоянието отпреди 29.07)
# Нито един режим не маха и една ПРОГНОЗА от витрината — това е за ШУМА, не
# за обема. Непозната стойност пада на „pak“: грешка в средата не може да
# смени поведението мълчаливо.


def normalizirai_rezhim(v):
    """Средата → режим. Непознатото пада на „pak“, тоест на днешното."""
    s = str(v or "").strip().lower()
    return s if s in ("pak", "kratko", "bez") else "pak"


STAYA_REZHIM = normalizirai_rezhim(os.environ.get("PREDICT_STAYA_REZHIM"))
_rezhim_surov = (os.environ.get("PREDICT_STAYA_REZHIM") or "").strip().lower()
if _rezhim_surov and _rezhim_surov != STAYA_REZHIM:
    print("WARN: PREDICT_STAYA_REZHIM=" + _rezhim_surov
          + " не е познат — оставам на „pak“ (както досега).")


def staya_tekst(an, cyala, now):
    """Какво отива в стаята на спорта: същото, съкратено, или нищо (None).

    Съкратеното е ЕДИН ред и носи четирите неща, заради които се отваря стая:
    кога, кой срещу кого, какво казваме и с колко. Всичко останало (причината,
    извадката, всеживотната сметка на спорта) остава в 27 — там картата е
    непокътната. ЗАГУБАТА СЕ ЗНАЕ: който чете САМО стаята на своя спорт и
    никога 27, при „kratko“ вече не вижда защо е избрано това.
    """
    if STAYA_REZHIM == "bez":
        return None
    if STAYA_REZHIM != "kratko":
        return cyala
    fx = an.get("fx") or {}
    koga = str(fx.get("time") or when_label(fx.get("when"), now) or "").strip()
    parts = []
    if koga:
        parts.append("<b>" + esc(koga) + "</b>")
    parts.append(esc(str(fx.get("home") or "")) + " " + chr(8212) + " "
                 + esc(str(fx.get("away") or "")))
    izbor = str(an.get("pick") or "").strip()
    if izbor:
        parts.append("🎯 <b>" + esc(izbor) + "</b>")
    try:
        parts.append("<b>" + pct(an.get("p")) + "</b>")
    except (TypeError, ValueError):
        pass
    red = " · ".join(x for x in parts if x)
    em = str(fx.get("emoji") or "").strip()
    return (em + " " + red) if em else red


def prati_v_staya(an, cyala, now):
    """Копието в стаята на своя спорт. Връща КОЛКО съобщения са излезли (0/1).

    Едно място за двата пътя (прогнози и тотали) — дотук логиката беше
    преписана два пъти и режимът трябваше да се вгражда на две места.
    Провал тук НЕ отменя картата: тя вече е в 27.
    """
    staya = SPORT_ROOM.get(an.get("bucket"))
    if not staya or staya == PREDICT_THREAD:
        return 0
    tekst = staya_tekst(an, cyala, now)
    if not tekst:
        return 0
    time.sleep(1.2)
    return 1 if post_predict(tekst, staya) else 0


# ---------------------------------------------------------------- МАТЕМАТИКА (на ръка)
MAXG = 10               # докъде смятаме матрицата от Поасон


def poisson_pmf(k, lam):
    if k < 0:
        return 0.0
    if lam <= 0:
        return 1.0 if k == 0 else 0.0
    return math.exp(-lam) * (lam ** k) / math.factorial(k)


def logistic(x):
    if x < -60:
        return 0.0
    if x > 60:
        return 1.0
    return 1.0 / (1.0 + math.exp(-x))


def logit(p):
    p = min(max(float(p), 1e-6), 1.0 - 1e-6)
    return math.log(p / (1.0 - p))


def clampf(x, lo, hi):
    return max(lo, min(hi, x))


def shrink(sample_mean, prior, n, k):
    """Свиване към средното: при малко мачове вярваме повече на нивото."""
    if n <= 0:
        return float(prior)
    return (float(sample_mean) * n + float(prior) * k) / (n + k)


def strength_binary(p):
    """Колко далеч от чиста монета е числото: 50% -> 0, 100% -> 1."""
    return clampf(abs(float(p) - 0.5) * 2.0, 0.0, 1.0)


def strength_1x2(p, base=1.0 / 3.0):
    """Колко сме над случайното — за ТОЗИ пазар, не изобщо.

    Базата е различна за различните редове: „1" се уцелва на сляпо веднъж на
    три пъти, „1Х" — два пъти на три. Ако мерехме и двете срещу 1/3, двойният
    шанс щеше да излиза с пет звезди при нулево знание.
    При база 1/3 формулата е точно старата: (p - 1/3) * 1.5.
    """
    b = clampf(float(base), 0.0, 0.95)
    return clampf((float(p) - b) / (1.0 - b), 0.0, 1.0)


# --- Поасон с корекция Диксън-Коулс -------------------------------------------
# Чистият Поасон систематично подценява равенствата 0:0 и 1:1. Корекцията тежи
# само четирите ниски резултата и е причината картата да не изглежда глупаво,
# когато мачът наистина мирише на 1:1.
FOOT_RHO = -0.13


def dc_tau(i, j, lh, la, rho=FOOT_RHO):
    if i == 0 and j == 0:
        return 1.0 - lh * la * rho
    if i == 0 and j == 1:
        return 1.0 + lh * rho
    if i == 1 and j == 0:
        return 1.0 + la * rho
    if i == 1 and j == 1:
        return 1.0 - rho
    return 1.0


def score_matrix(lam_h, lam_a, rho=FOOT_RHO, maxg=MAXG):
    """Съвместното разпределение на резултата, нормирано до сума 1."""
    ph = [poisson_pmf(i, lam_h) for i in range(maxg + 1)]
    pa = [poisson_pmf(j, lam_a) for j in range(maxg + 1)]
    m = []
    total = 0.0
    for i in range(maxg + 1):
        row = []
        for j in range(maxg + 1):
            v = ph[i] * pa[j] * max(0.01, dc_tau(i, j, lam_h, lam_a, rho))
            row.append(v)
            total += v
        m.append(row)
    if total <= 0:
        return [[0.0] * (maxg + 1) for _ in range(maxg + 1)]
    return [[v / total for v in row] for row in m]


def matrix_markets(mx, maxg=MAXG):
    """1 / X / 2, над 2.5, и двата бележат, най-вероятен точен резултат."""
    p_home = p_draw = p_away = p_over = p_btts = 0.0
    best_p, best_i, best_j = 0.0, 0, 0
    for i in range(maxg + 1):
        for j in range(maxg + 1):
            p = mx[i][j]
            if i > j:
                p_home += p
            elif i == j:
                p_draw += p
            else:
                p_away += p
            if i + j >= 3:
                p_over += p
            if i >= 1 and j >= 1:
                p_btts += p
            if p > best_p:
                best_p, best_i, best_j = p, i, j
    return {"p_home": p_home, "p_draw": p_draw, "p_away": p_away,
            "p_over": p_over, "p_btts": p_btts, "top": (best_i, best_j, best_p)}


# --- Надпревара до N точки с разлика 2 (волейбол, тенис на маса) ---------------
def race_prob(p, n=25):
    """Вероятността да спечелиш гейм/сет до n точки с преднина 2,
    ако всяко разиграване печелиш с вероятност p. Точна сметка, не симулация."""
    p = clampf(float(p), 1e-6, 1.0 - 1e-6)
    q = 1.0 - p
    total = 0.0
    for k in range(0, n - 1):           # съперникът стига до n-2 точки
        total += math.comb(n - 1 + k, k) * (p ** n) * (q ** k)
    deuce = math.comb(2 * n - 2, n - 1) * ((p * q) ** (n - 1))
    total += deuce * (p * p) / (p * p + q * q)
    return clampf(total, 0.0, 1.0)


def bo_distribution(p_set, to_win=3, p_last=None):
    """Разпределение на резултата в сетове при „пръв до to_win".
    Последният решаващ сет може да е с друга вероятност (по-къс, по-нервен)."""
    ps = clampf(float(p_set), 1e-6, 1.0 - 1e-6)
    q = 1.0 - ps
    pl = ps if p_last is None else clampf(float(p_last), 1e-6, 1.0 - 1e-6)
    out = []
    for lost in range(0, to_win):
        games = to_win - 1 + lost
        ways = math.comb(games, lost)
        if lost == to_win - 1:          # решаващият сет
            pr = ways * (ps ** (to_win - 1)) * (q ** lost) * pl
        else:
            pr = ways * (ps ** to_win) * (q ** lost)
        out.append((to_win, lost, pr))
    return out


def bo_match_prob(p_set, to_win=3, p_last=None):
    return sum(x[2] for x in bo_distribution(p_set, to_win, p_last))


def invert_bo(p_match, to_win=3):
    """Обратната сметка: от вероятност за МАЧ намираме вероятността за СЕТ.
    Нужна е, когато моделът дава само кой печели, а искаме и как (3-0 / 3-1)."""
    lo, hi = 1e-4, 1.0 - 1e-4
    target = clampf(float(p_match), 1e-4, 1.0 - 1e-4)
    for _ in range(50):
        mid = (lo + hi) / 2.0
        if bo_match_prob(mid, to_win) < target:
            lo = mid
        else:
            hi = mid
    return (lo + hi) / 2.0


# --- Elo ----------------------------------------------------------------------
def elo_expect(ra, rb):
    return 1.0 / (1.0 + 10.0 ** ((rb - ra) / 400.0))


# --- Брадли-Тери: сила по разигравания, коригирана за съперника ----------------
def fit_bt(rows, iters=14, step=1.1, lo=-1.6, hi=1.6):
    """rows = списък от (отбор, съперник, спечелени, загубени, тегло).
    Връща рейтинг в логит-мащаб, центриран около нулата. Пет реда математика,
    но точно те правят разликата между „силен отбор" и „играл със слаби"."""
    data = {}
    for a, b, wf, wa, w in rows:
        if not a or not b or (wf + wa) <= 0:
            continue
        data.setdefault(a, []).append((b, float(wf), float(wa), float(w)))
        data.setdefault(b, []).append((a, float(wa), float(wf), float(w)))
    r = {t: 0.0 for t in data}
    if not r:
        return r
    for _ in range(iters):
        for t, lst in data.items():
            obs = exp = wsum = 0.0
            for opp, wf, wa, w in lst:
                n = wf + wa
                p = logistic(r[t] - r.get(opp, 0.0))
                obs += w * wf
                exp += w * n * p
                wsum += w * n
            if wsum <= 0:
                continue
            r[t] = clampf(r[t] + step * (obs - exp) / (wsum * 0.25), lo, hi)
        m = mean(r.values())
        for t in r:
            r[t] -= m
    return r


# --- Тегло по свежест ---------------------------------------------------------
def decay_weight(iso_date, now, half_life_days):
    """Мач отпреди две години не тежи колкото мач отпреди месец. Точка."""
    d = days_between(iso_date, now)
    if d is None or d < 0:
        return 1.0
    return 0.5 ** (d / float(max(1.0, half_life_days)))


def wstats(recs, now, half_life):
    """Претеглени средни за/против + ефективна извадка."""
    wsum = gf = ga = 0.0
    hw = hgf = hga = 0.0
    aw = agf = aga = 0.0
    for r in recs:
        w = decay_weight(r.get("date"), now, half_life)
        wsum += w
        gf += w * r["gf"]
        ga += w * r["ga"]
        if r.get("home"):
            hw += w
            hgf += w * r["gf"]
            hga += w * r["ga"]
        else:
            aw += w
            agf += w * r["gf"]
            aga += w * r["ga"]
    if wsum <= 0:
        return None
    out = {"n": len(recs), "w": wsum, "gf": gf / wsum, "ga": ga / wsum,
           "wh": hw, "wa": aw}
    out["gf_h"] = (hgf / hw) if hw > 0 else out["gf"]
    out["ga_h"] = (hga / hw) if hw > 0 else out["ga"]
    out["gf_a"] = (agf / aw) if aw > 0 else out["gf"]
    out["ga_a"] = (aga / aw) if aw > 0 else out["ga"]
    return out


def sane_record(bucket, gf, ga):
    """Пази срещу боклук в източника (точки, записани като сетове, и подобни)."""
    if gf is None or ga is None or gf < 0 or ga < 0:
        return False
    if bucket in ("football", "hockey"):
        return gf <= 15 and ga <= 15
    if bucket == "basketball":
        return 30 <= gf <= 200 and 30 <= ga <= 200
    if bucket == "baseball":
        return gf <= 40 and ga <= 40
    if bucket == "volleyball":
        return max(gf, ga) <= 3 and (gf + ga) <= 5 and max(gf, ga) >= 2
    if bucket == "tabletennis":
        return max(gf, ga) <= 4 and (gf + ga) <= 7 and max(gf, ga) >= 2
    return True


# ---------------------------------------------------------------- УВЕРЕНОСТ
def grade(bucket, n_eff, strength):
    """Звездите идват от РЕАЛНАТА извадка и от категоричността. Нищо друго."""
    score = 0.55 * min(1.0, float(n_eff) / 30.0) + 0.45 * min(1.0, float(strength) / 0.40)
    stars = 3 if score >= 0.72 else (2 if score >= 0.45 else 1)
    if n_eff < 10:
        stars = 1
    elif n_eff < 20:
        stars = min(stars, 2)
    return max(1, min(stars, STAR_CAP.get(bucket, 3)))


# ================================================================= ИЗТОЧНИЦИ
ESPN_SITE = "https://site.api.espn.com/apis/site/v2/sports"

_hist_cache = {}


def espn_num(s):
    """КАПАН №1 в целия файл. В scoreboard резултатът е низ „2", а в
    teams/{id}/schedule е речник {value: 2}. Един помощник за двете места."""
    if isinstance(s, dict):
        v = s.get("value")
        if v is None:
            v = s.get("displayValue")
        return to_num(v)
    return to_num(s)


# 🔴 ПАЗАЧЪТ ЗА ПРЕДСЕЗОННИ БЕШЕ СЛЯП (намерено и оправено 11.08.2026).
#
# Кодът режеше предсезонните така: `if "Preseason" in ev["seasonType"]["name"]`.
# Измерено на живо срещу ESPN за 13.08.2026 (НФЛ):
#     event.seasonType : {}                      ← ПРАЗНО
#     event.season     : {"year":2026,"type":1,"slug":"preseason"}
# Тоест полето, което проверявахме, ESPN изобщо не го пълни, а истинският
# белег стои другаде. Проверката минаваше винаги и не е спряла нито един мач.
#
# Защо има значение точно сега: НФЛ подхваща на 13.08 — вдругиден. В предсезона
# титулярите играят по четвърт час, а моделът смята по 17 мача от РЕДОВНИЯ
# сезон. Тоест щяхме да пуснем карта с чужди числа под нея.
#
# Сега се гледат ТРИ места, защото различните турнири пълнят различни:
#   • season.slug == "preseason"   (най-надеждното при НФЛ/НБА)
#   • seasonType.name съдържа Preseason (там, където ESPN го пълни)
#   • competition.type.abbreviation == "PRE"
def predsezonen(ev, comp=None):
    """Предсезонен ли е мачът. Гледа трите места, където ESPN го пише."""
    sez = ev.get("season") or {}
    if str(sez.get("slug") or "").lower() == "preseason":
        return True
    if "preseason" in str((ev.get("seasonType") or {}).get("name") or "").lower():
        return True
    tip = ((comp or {}).get("type") or {})
    if str(tip.get("abbreviation") or "").upper() == "PRE":
        return True
    return False


def espn_sides(comp):
    """Домакин и гост от competitors[].homeAway — никога от реда в списъка."""
    h = a = None
    for c in (comp.get("competitors") or []):
        if c.get("homeAway") == "home":
            h = c
        elif c.get("homeAway") == "away":
            a = c
    return h, a


def espn_fixtures(sport, slug, ymd, bucket, weight, league_bg, now, extra=None):
    """Днешните срещи на една лига. Взимаме само още неиграните („pre")."""
    j = http_json(ESPN_SITE + "/" + sport + "/" + slug + "/scoreboard?dates=" + ymd)
    if not isinstance(j, dict):
        return []
    lg = (j.get("leagues") or [{}])
    lname = league_bg or ((lg[0] or {}).get("name") if lg else "") or slug
    out = []
    for ev in (j.get("events") or []):
        comps = ev.get("competitions") or []
        if not comps:
            continue
        comp = comps[0] or {}
        st = ((comp.get("status") or {}).get("type") or {})
        if str(st.get("state") or "").lower() != "pre":
            continue
        if predsezonen(ev, comp):
            continue
        h, a = espn_sides(comp)
        if not h or not a:
            continue
        ht, at = (h.get("team") or {}), (a.get("team") or {})
        ex = dict(extra or {})
        ex["slug"] = slug
        # 🔴 13.08.2026. Идентификаторът на срещата в ESPN. Пазим го, защото
        # ДЪЛБОКИЯТ слой на ESPN (sports.core.api) дава пазарната цена само
        # по него — scoreboard-ът я носи единствено за футбола, а core я има
        # и за бейзбол, и за ВНБА. Един ключ тук отваря цял пазар после.
        ex["ev_id"] = str(ev.get("id") or "")
        ex["sport_path"] = sport
        ex["neutral"] = bool(comp.get("neutralSite"))
        # 🔴 РЕКОРДЪТ СЕ ЗАПАЗВА (11.08.2026). ESPN го дава направо в
        # scoreboard-а: records=[{'type':'total','summary':'20-12'},
        # {'type':'home','summary':'11-6'}, {'type':'road','summary':'9-6'}].
        # Анализаторът (matches_bot) нямаше НИКАКВИ числа за WNBA и волейбола
        # и всеки ден пишеше „нямаме изиграни мачове" — а те са били на един
        # ключ разстояние в същия отговор.
        def _rec(side, vid):
            for r in (side.get("records") or []):
                if str(r.get("type") or "").lower() == vid:
                    return str(r.get("summary") or "")
            return ""
        ex["rec_h"] = _rec(h, "total")
        ex["rec_a"] = _rec(a, "total")
        ex["rec_h_home"] = _rec(h, "home")
        ex["rec_a_road"] = _rec(a, "road")
        ex["form_h"] = h.get("form") or ""
        ex["form_a"] = a.get("form") or ""
        # 🔴 ОРИГИНАЛНОТО ИМЕ (18.08.2026). Показваме „Фенербахче", но чуждите
        # източници знаят „Fenerbahce". Измерено: търсенето по имена НЕ
        # намираше нито един преведен отбор — а превеждаме точно големите.
        ex["home_en"] = str(ht.get("displayName") or "")
        ex["away_en"] = str(at.get("displayName") or "")
        # 🔴 ЕДНО ИМЕ ИМА ТРИ ВРАТИ (26.08.2026). Измерено в тази сесия върху
        # свалената на 25.08 дъска на ESPN и указателя на Pinnacle:
        #     колежански футбол, само по displayName ->   0 от 98
        #     колежански футбол, по трите имена      ->  44
        #     НФЛ, само по displayName / по трите    ->  16 и 16
        # Причината е, че Pinnacle пише колежанските САМО с училището („TCU"),
        # а ESPN пише училище+прякор („TCU Horned Frogs"). Без тези два реда
        # NCAA щеше да е БЕЗ ЦЕНА, значи без карта — мълчаливо.
        # За другите спортове полетата са безвредни: никой не ги чете.
        ex["home_loc"] = str(ht.get("location") or "")
        ex["away_loc"] = str(at.get("location") or "")
        ex["home_short"] = str(ht.get("shortDisplayName") or "")
        ex["away_short"] = str(at.get("shortDisplayName") or "")
        out.append({
            "bucket": bucket, "emoji": SPORTS[bucket]["emoji"], "src": "espn",
            "home": bg_name(ht.get("displayName") or ""), "away": bg_name(at.get("displayName") or ""),
            "home_id": ht.get("id"), "away_id": at.get("id"),
            "league": lname, "weight": weight, "when": parse_iso(ev.get("date")),
            "extra": ex,
        })
    return out


def espn_history(sport, slug, team_id, seasons, bucket):
    """Изиграните мачове на отбор за дадени сезони. ТУК резултатът е речник."""
    ck = ("h", sport, slug, str(team_id), tuple(seasons))
    if ck in _hist_cache:
        return _hist_cache[ck]
    recs = []
    for s in seasons:
        j = http_json(ESPN_SITE + "/" + sport + "/" + slug + "/teams/"
                      + str(team_id) + "/schedule?season=" + str(s), quiet=True)
        if not isinstance(j, dict):
            continue
        for ev in (j.get("events") or []):
            comps = ev.get("competitions") or []
            if not comps:
                continue
            # Същият сляп пазач стоеше и тук — историята се пълнеше с
            # предсезонни резултати, тоест моделът смяташе по мачове, в които
            # титулярите не са играли. Виж обяснението при predsezonen().
            if predsezonen(ev, comps[0]):
                continue
            me = opp = None
            for c in (comps[0].get("competitors") or []):
                if str((c.get("team") or {}).get("id") or "") == str(team_id):
                    me = c
                else:
                    opp = c
            if not me or not opp:
                continue
            gf, ga = espn_num(me.get("score")), espn_num(opp.get("score"))
            if gf is None or ga is None:
                continue
            if not sane_record(bucket, gf, ga):
                continue
            recs.append({"gf": gf, "ga": ga,
                         "home": me.get("homeAway") == "home",
                         "date": str(ev.get("date") or "")[:10],
                         "opp": str((opp.get("team") or {}).get("id") or "")})
    _hist_cache[ck] = recs
    return recs


