# 114 съдени мача от живия дневник: ботът ОБЯВЯВА 58.1%, а СБЪДВА 75.4% —
# 17.3 точки под собствената си дума, при шум ±7.9. Тоест продаваме по-евтино,
# отколкото струваме, и то системно.
#
# Подписът показва, че вината е в ШИРИНАТА, не в модела:
#     една звезда (обявено ~52.6%)  →  сбъднато 54.5%   разлика +1.9 т
#     две+ звезди (обявено ~60.4%)  →  сбъднато 84.0%   разлика +23.6 т
# При 50% умножението по ширина не мести нищо; при 65% мести всичко. Точно
# това се вижда. Ако моделът грешеше, разликата щеше да е равна навсякъде.
#
# Цепките държат: първата половина дни +14.3, втората +20.2, най-голямата
# лига +20.2 — и трите извън шума, независимо една от друга.
#
# Пробвани ширини върху същите 114 мача (обявено / сбъднато / Брайер):
#     0.55  →  58.1% / 75.4%  +17.3 т  0.2053   (сегашното)
#     1.70  →  71.3% / 75.4%   +4.2 т  0.1692
#     2.20  →  74.5% / 75.4%   +0.9 т  0.1646   ← избраното
#     2.80  →  77.1% / 75.4%   -1.7 т  0.1630
#     3.50  →  78.9% / 75.4%   -3.5 т  0.1646
# Брайерът е почти равен между 2.2 и 3.5. Избираме края, който НЕ обещава
# повече, отколкото сбъдва: 2.2 дава +0.9 т, 2.8 вече дава -1.7 т.
#
# Път назад: PREDICT_TT_SCALE=0.55 връща точно старото поведение.
TT_SCALE = env_float("PREDICT_TT_SCALE", 2.2, 0.3, 4.5)
# 🔴 СТЕНИТЕ НЕ СЕ ПИПАТ. Измерено: НУЛА от 114-те мача опират в 0.15/0.85 при
# старата ширина, а разширяването им беше мерено и излезе ПО-ЛОШО. Тесният
# процент не идваше от стените, а от ширината.
TT_P_MIN, TT_P_MAX = 0.15, 0.85

# 🔴 ШИРИНАТА ВАЖИ САМО ТАМ, КЪДЕТО Е ИЗМЕРЕНА (19.08.2026).
#
# Намерено с ЧЕТЕНЕ НА СТАЯТА, не от тест. Излязла карта:
#   „Martin BUCH — 77% · ясен фаворит"
#   „Martin BUCH: 18 победи и 19 загуби" (тоест ОТРИЦАТЕЛЕН баланс)
# Обяснението под числото оборваше самото число пред очите на читателя.
#
# Причината: 2.2 е нагласена върху 114 съдени мача от Europe Smash и WTT
# Champions, където играчите имат по 40-150 мача. Разбито по извадка:
#     по-малката извадка 50+   →  62 мача, +18.8 т подценяване
#     по-малката извадка 20-49 →  51 мача, +16.9 т подценяване
#     по-малката извадка под 20 →  1 мач  (и той загубен)
# Тоест под 20 мача ширината 2.2 НЕ Е ИЗМЕРЕНА НИКОГА. При Feeder турнирите
# играчите имат по 8-11 мача и тя произвежда 77-79% от нищо.
#
# Лекарството е стъпка, не измислена крива: над прага важи измереното, под
# него се връщаме към предпазливото старо. Интерполацията между двете би била
# съчинена математика — а за нея нямаме нито едно число.
TT_PALNA_N = env_int("PREDICT_TT_PALNA_N", 20, 5, 100)
TT_SCALE_MALKO = env_float("PREDICT_TT_SCALE_MALKO", 0.55, 0.2, 2.5)

# 🔴 ШИРИНАТА Е РАЗЛИЧНА ПО СТЕПЕН НА ТУРНИРА (25.08.2026).
#
# 2.2 беше нагласена върху Europe Smash и WTT Champions, а се прилагаше
# върху ВСИЧКО. Измерено на 168 отсъдени карти, разбити по степен:
#     Champions  n=35  обявява 56.8%  сбъдва 71.4%  +14.6 т  (подценяваме)
#     Smash      n=79  обявява 58.7%  сбъдва 77.2%  +18.5 т  ИЗВЪН ШУМА
#     Feeder     n=54  обявява 67.8%  сбъдва 61.1%   −6.7 т  (НАДценяваме)
# Тоест при Feeder същата ширина вече обещава ПОВЕЧЕ, отколкото сбъдва —
# обратният знак на болестта, заради която ширината беше вдигната.
#
# 🔴 ЧЕСТНО ЗА ЧИСЛАТА, ПРЕДИ ДА СЕ ПОЛЗВАТ:
#   • −6.7 т на 54 мача е ВЪТРЕ в шума (±12.5 т). Тоест доказано е
#     РАЗДЕЛЯНЕТО (Smash е извън шума, Feeder е с ОБРАТЕН знак), а НЕ
#     конкретната стойност за Feeder.
#   • Затова долната степен НЕ Е НАГЛАСЕНА върху тези 54 мача. Взима се
#     1.00 — числото, при което ширината изобщо не пипа модела (чистото
#     сравнение на двата рейтинга). То не е избрано ПО ДАННИТЕ, а е
#     единствената стойност със собствен смисъл, и греши в БЕЗОПАСНАТА
#     посока: грубата сметка върху същата извадка дава обявени ~58% срещу
#     сбъднати 61%, тоест обещаваме по-малко, отколкото даваме.
#     (Грубата сметка е груба НАРОЧНО: логистиката не е линейна и средното
#     от преобразуванията не е преобразуване на средното. Тя показва
#     ПОСОКАТА и нищо повече — не заменя преизмерване.)
#   • Contender и всичко останало под Champions НЕ Е МЕРЕНО НИКОГА: тези
#     168 карти са само от трите степени горе. Немереното получава
#     предпазливото, не измереното другаде.
#
# ПРЕИЗМЕРВА СЕ, когато Feeder-ите станат 150+ отсъдени карти.
# ПЪТЯТ НАЗАД: PREDICT_TT_SCALE_NISKA=2.2 връща точно държанието отпреди.
TT_SCALE_NISKA = env_float("PREDICT_TT_SCALE_NISKA", 1.0, 0.3, 4.5)
# Оттук нагоре важи измереното. 85 = WTT Champions; Smash е 90, финалите 92.
TT_STEPEN_PRAG = env_int("PREDICT_TT_STEPEN_PRAG", 85, 10, 95)


def tt_stepen(liga):
    """Ширината, която важи за ТАЗИ степен турнири.

    🔴 БЕЗ ИМЕ НА ТУРНИР СЕ ВРЪЩА ПРЕДПАЗЛИВАТА. „Не знам коя степен" НЕ е
    „най-горната степен" — това е същата разлика като „няма" срещу „не
    можах да питам", само че цената ѝ вече е измерена: 77% върху играч с
    отрицателен баланс (18 победи и 19 загуби, видяно в стаята 19.08).
    """
    if not str(liga or "").strip():
        return TT_SCALE_NISKA
    return TT_SCALE if _tt_rang(liga) >= TT_STEPEN_PRAG else TT_SCALE_NISKA


def tt_shirina(n_malka, liga=None):
    """Коя ширина важи за тази карта. Пълната — само където е измерена.

    ДВЕ сита, и важи ПО-ТЯСНОТО от двете:
      • ИЗВАДКАТА — под TT_PALNA_N мача 2.2 не е мерена никога
      • СТЕПЕНТА  — над Champions е мерена, под нея е мерена като ВРЕДНА
    """
    try:
        n = int(n_malka)
    except (TypeError, ValueError):
        return TT_SCALE_MALKO
    po_izvadka = TT_SCALE if n >= TT_PALNA_N else TT_SCALE_MALKO
    return min(po_izvadka, tt_stepen(liga))
_tt_stats = {}


def dget(d, *names):
    """Полетата на WTT идват ту с долни черти, ту с главни букви."""
    if not isinstance(d, dict):
        return None
    low = {str(k).lower().replace("_", ""): v for k, v in d.items()}
    for n in names:
        k = str(n).lower().replace("_", "")
        if k in low:
            return low[k]
    return None


def _unwrap(x):
    while isinstance(x, list) and x:
        x = x[0]
    return x if isinstance(x, dict) else {}


# 🔴 КОЙ ТУРНИР СЕ ГЛЕДА, КОГАТО ТЕКАТ ПОВЕЧЕ ОТ ТАВАНА (18.08.2026)
#
# Досега кодът взимаше ПЪРВИТЕ ДВА в реда на файла — тоест по случайност.
# Измерено върху живия календар на WTT (172 турнира за 2026): на 9 от
# следващите 45 дни текат по 4-5 турнира едновременно, значи 2-3 се изхвърлят
# невидимо. На 26-28.08 се пропускат по три наведнъж.
#
# Редът вече е по ТЕЖЕСТ. Юношеските падат най-долу нарочно: там няма
# 18-месечна история на играча, а тя е целият ни източник за този спорт —
# без нея процентът е познайница с десетична запетая.
def _tt_dumi(ime):
    """Името, разцепено на цели думи. „U11&U13" дава {u11, u13}."""
    d, cur = set(), []
    for ch in str(ime or "").lower():
        if ch.isalnum():
            cur.append(ch)
        elif cur:
            d.add("".join(cur))
            cur = []
    if cur:
        d.add("".join(cur))
    return d


def _tt_rang(ime):
    """Колко тежи турнир. По-голямото се гледа първо, щом таванът реже.

    🔴 ПО ЦЕЛИ ДУМИ, НЕ ПО ПОДНИЗ (поправено 18.08.2026).
    Първата ми версия търсеше „champions" като подниз — а „championSHIPS" го
    съдържа. Върху ИСТИНСКИЯ календар това значеше: „ITTF-Americas U11&U13
    Championships Houston" и „Central American Masters Championships" вземаха
    85, тоест нивото на WTT Champions, и изхвърляха от тавана българския WTT
    Contender Panagyurishte и един Feeder. Детски и ветерански турнири
    изяждаха възрастни професионални.

    Стълбицата е сверена срещу ВСИЧКИТЕ 170 имена в календара за 2026.
    Юношеските и ветеранските падат най-долу нарочно: там няма 18-месечна
    история на играча, а тя е целият ни източник за този спорт.
    """
    d = _tt_dumi(ime)
    if d & {"youth", "junior", "juniors", "cadet", "cadets",
            "u11", "u13", "u15", "u17", "u19", "u21"}:
        return 10
    if "masters" in d:                      # ветерански, не елитни
        return 12
    if "finals" in d and "wtt" in d:
        return 92
    if "smash" in d:
        return 90
    if "cup" in d and "world" in d:
        return 88
    if "championships" in d and "world" in d:
        return 86
    if "champions" in d:                    # ЦЯЛА дума, не подниз
        return 85
    if "contender" in d:
        return 78 if "star" in d else 70
    if "feeder" in d:
        return 60
    if "cup" in d:
        return 55
    if "regional" in d:
        return 38
    if d & {"championships", "championship"}:
        return 48
    if "games" in d:
        return 45
    return 40


# Таван на едновременно гледаните турнири. Всеки струва едно разписание плюс
# статистиката на играчите в него — затова не е безкраен.
TT_MAX_TURNIRI = env_int("PREDICT_TT_TURNIRI", 3, 1, 8)


def tt_turnir_sled(now, napred_dni=21):
    """След колко дни почва следващият турнир по тенис на маса. None = не знам.

    🔴 ЗАЩО НЕ СТИГА ДА СЕ ПИТА ЗА МАЧОВЕ (18.08.2026). WTT публикува
    разписанието на един турнир чак ден-два преди началото му. Измерено на
    живо: на 18.08 календарът ясно казва „WTT Feeder Berlin, 19-23.08", а
    разписанието за 19.08 връща НУЛА мача. Тоест здравният преглед питаше
    „има ли мач утре?", получаваше „не" и вдигаше ЧЕРВЕН флаг за спорт, който
    просто е между два турнира.

    Календарът знае истината. Него питаме.
    """
    try:
        cal = http_json(WTT_CDN + "/websitestaticapifiles/general/"
                        + str(now.year) + "_eventcalendar.json", quiet=True)
    except Exception:                                        # noqa: BLE001
        return None
    rows = []
    for blk in (cal if isinstance(cal, list) else [cal or {}]):
        rows += ((blk or {}).get("rows") or [])
    if not rows:
        return None
    dnes = now.strftime("%Y-%m-%d")
    nay = None
    for r in rows:
        st = str(dget(r, "StartDateTime") or "")[:10]
        en = str(dget(r, "EndDateTime") or "")[:10]
        if not st or not en or en < dnes:
            continue
        # Турнир, който ТЕЧЕ днес, значи нула дни чакане.
        try:
            dni = (datetime.strptime(st, "%Y-%m-%d").date() - now.date()).days
        except ValueError:
            continue
        dni = max(0, dni)
        if dni <= int(napred_dni) and (nay is None or dni < nay):
            nay = dni
    return nay


def tt_fixtures(now, ymd_dash):
    try:
        cal = http_json(WTT_CDN + "/websitestaticapifiles/general/"
                        + str(now.year) + "_eventcalendar.json")
    except Exception as e:      # noqa: BLE001
        print("   ⚠ тенис на маса: " + str(e)[:80])
        return []
    rows = []
    for blk in (cal if isinstance(cal, list) else [cal or {}]):
        rows += ((blk or {}).get("rows") or [])
    # 🔴 ПРАЗЕН КАЛЕНДАР НЕ Е „НЯМА ТУРНИРИ" (19.08.2026). `http_json` връща
    # None при провал БЕЗ да гърми — тоест задавен CDN изглеждаше точно като
    # спокоен ден без турнири, и здравният преглед казваше „източникът върна
    # нула срещи". Хванато на живо: два успоредни рънa задавиха WTT и тенисът
    # на маса тихо стана нула, при 120 налични мача.
    if not rows:
        print("   ⚠ тенис на маса: календарът се върна ПРАЗЕН — това е провал "
              "на източника, не липса на турнири.")
        return []
    live = []
    for r in rows:
        s = str(dget(r, "StartDateTime") or "")[:10]
        e = str(dget(r, "EndDateTime") or "")[:10]
        eid = to_num(dget(r, "EventId"))
        if eid and s and e and s <= ymd_dash <= e:
            live.append((eid, str(dget(r, "EventName") or "WTT")))
    # Най-тежкият пръв; при равенство — по име, за да е повторимо.
    live.sort(key=lambda x: (-_tt_rang(x[1]), str(x[1])))
    _imalo_turniri = bool(live)

    # 🔴 ЮНОШЕСКИТЕ ПАДАТ ПРЕДИ ДА СЕ БРОЯТ СЛОТОВЕТЕ (02.09.2026).
    #
    # Дотук се взимаха ТОП TT_MAX_TURNIRI (3) по ранг, а юношеските се
    # режеха ЧАК ДОЛУ, от `zalozhimo`. Измерено на живия календар същия ден:
    #     05.09 текат ПЕТ турнира, от които ЕДИН е за възрастни
    #         #3247 ранг 70  WTT Contender Almaty          ← истински
    #         #3314 ранг 10  WTT Youth Contender Tunis II  ← юноши
    #         #3332 ранг 10  WTT Youth Contender Cuenca    ← юноши
    #         #3350 ранг 10  WTT Youth Contender Puerto Princesa
    #         #3455 ранг 10  ITTF-Oceania Youth Ballarat
    # Тоест ДВА от трите слота отиваха за турнири, които после падат — с
    # похарчена заявка на всеки. Черната кутия на живия рън показва точно
    # една грешка в целия бот и тя е 404 от такъв блоб.
    #
    # Сега слотовете се пазят за истинските. Ако ВСИЧКИ са юношески, се
    # взимат старите — по-добре нищо, отколкото три пропилени заявки, но
    # мълчанието се обявява, а не се прикрива.
    if ZL is not None:
        _vazr = []
        for _e, _n in live:
            try:
                if ZL.zalozhimo(_n, "tabletennis")[0]:
                    _vazr.append((_e, _n))
            except Exception:                                # noqa: BLE001
                _vazr.append((_e, _n))
        if len(_vazr) < len(live):
            print("   🏓 календар: %d турнира, %d за възрастни — слотовете (%d) "
                  "отиват за тях." % (len(live), len(_vazr), TT_MAX_TURNIRI))
        if _vazr:
            live = _vazr
        elif live:
            print("   🏓 ВСИЧКИ %d турнира днес са юношески — няма за кого да "
                  "питам." % len(live))
            live = []
    out = []
    for eid, ename in live[:TT_MAX_TURNIRI]:
        sch = http_json(WTT_CDN + "/websitecacheddata/" + str(eid)
                        + "/schedule/schedule.json", quiet=True)
        units = []
        for blk in (sch if isinstance(sch, list) else [sch or {}]):
            units += (((blk or {}).get("Competition") or {}).get("Unit") or [])
        for u in units:
            sub = str(dget(u, "SubEvent") or "")
            if "Singles" not in sub:
                continue        # двойките искат отделен рейтинг на двойката
            starts = ((dget(u, "StartList") or {}).get("Start") or [])
            people = []
            for st in starts:
                ath = ((((st or {}).get("Competitor") or {}).get("Composition") or {})
                       .get("Athlete") or [])
                a = _unwrap(ath)
                code = str(a.get("Code") or "")
                desc = a.get("Description") or {}
                nm = " ".join(x for x in [desc.get("GivenName"), desc.get("FamilyName")] if x)
                if code and nm.strip():
                    people.append((code, nm.strip()))
            if len(people) < 2:
                continue        # финалите стоят празни, докато полуфиналите свършат
            out.append({
                "bucket": "tabletennis", "emoji": "🏓", "src": "wtt",
                "home": people[0][1], "away": people[1][1],
                "home_id": people[0][0], "away_id": people[1][0],
                "league": ename + " · " + sub, "weight": 8,
                "when": parse_iso(str(dget(u, "StartDate") or "")),
                "extra": {"best_of": to_num(dget(u, "MaxGamesPerIndividualMatch")) or 5},
            })
    # 🔴 БЛИЗНАКЪТ НА ПРАЗНИЯ КАЛЕНДАР (19.08.2026). Календарът може да мине,
    # а РАЗПИСАНИЕТО да се задави — тогава пак излиза чиста нула без нито една
    # дума. Турнир, който тече и дава нула мача, е подозрение, не факт.
    if _imalo_turniri and not out:
        print("   ⚠ тенис на маса: %d турнира текат, а разписанието даде НУЛА "
              "мача — по-вероятно е провал на източника, отколкото празен ден."
              % len(live))
    return out


def tt_player(ittf_id, now):
    """Бърза сводка за 18 месеца: мачове, победи, загуби. Пълната история е
    30-45 секунди на играч и не влиза в един рън — това е съзнателен избор."""
    pid = str(ittf_id)
    if pid in _tt_stats:
        return _tt_stats[pid]
    start = (now - timedelta(days=548)).strftime("%Y-%m-%d")
    j = http_json(WTT_TTU + "Stats/Players/GetStatsByPlayer?StartDate=" + start
                  + "&EndDate=" + now.strftime("%Y-%m-%d") + "&IttfId=" + pid,
                  headers=WTT_HEAD, quiet=True)
    d = _unwrap(j)
    if isinstance(j, dict) and isinstance(j.get("Result"), (list, dict)):
        d = _unwrap(j.get("Result"))
    w = to_num(dget(d, "total_wins", "totalWins"))
    l = to_num(dget(d, "total_losses", "totalLosses"))
    n = to_num(dget(d, "total_matches", "totalMatches"))
    if w is None or l is None:
        out = None
    else:
        out = {"w": w, "l": l, "n": n if n is not None else (w + l),
               "best": to_num(dget(d, "best_rank", "bestRank"))}
    _tt_stats[pid] = out
    return out


def model_tabletennis(fx, now):
    a = tt_player(fx.get("home_id"), now)
    b = tt_player(fx.get("away_id"), now)
    if not a or not b:
        return None
    ra = (a["w"] + 3.0) / (a["w"] + a["l"] + 6.0)
    rb = (b["w"] + 3.0) / (b["w"] + b["l"] + 6.0)
    # Ширината се избира по ПО-МАЛКАТА от двете извадки: сигурността на
    # сравнението е толкова, колкото е по-слабо познатият играч.
    _n_malka = min(a["w"] + a["l"], b["w"] + b["l"])
    # 🔴 И СТЕПЕНТА НА ТУРНИРА ВЛИЗА (25.08.2026). Името му идва наготово в
    # fx["league"] от tt_fixtures („WTT Feeder Olomouc 2026 · Men's Singles").
    _sh = tt_shirina(_n_malka, fx.get("league"))
    p = clampf(logistic((logit(ra) - logit(rb)) * _sh), TT_P_MIN, TT_P_MAX)
    to_win = 4 if int((fx.get("extra") or {}).get("best_of") or 5) >= 7 else 3
    p_game = invert_bo(p, to_win)
    return {"p_home": p, "p_away": 1.0 - p, "a": a, "b": b, "ra": ra, "rb": rb,
            "to_win": to_win, "dist_h": bo_distribution(p_game, to_win),
            "dist_a": bo_distribution(1.0 - p_game, to_win),
            "n_malka": _n_malka, "shirina": _sh,
            "ok": (a["w"] + a["l"]) >= 5 and (b["w"] + b["l"]) >= 5}


# ----------------------------------------------------------------- ПОСЛЕДНА РЕЗЕРВА
def sdb_fixtures(bucket):
    """TheSportsDB е последна резерва: безплатният ключ дава 1-3 изиграни мача
    и точно затова ботът мълчеше. Държим го само да не остане празна стая."""
    if MB is None:
        return []
    try:
        rows = MB.sportsdb_fixtures(bucket)
    except Exception as e:      # noqa: BLE001
        print("   ⚠ резерва " + bucket + ": " + str(e)[:60])
        return []
    out = []
    for r in rows:
        out.append({
            "bucket": bucket, "emoji": SPORTS[bucket]["emoji"], "src": "sdb",
            "home": bg_name(r.get("home")), "away": bg_name(r.get("away")),
            "home_id": r.get("home_id"), "away_id": r.get("away_id"),
            "league": r.get("league") or "", "weight": max(1, to_num(r.get("weight")) or 1),
            "when": None, "time": r.get("time") or "", "extra": {},
        })
    return out


def sdb_history(fx, side):
    if MB is None:
        return []
    tid = fx.get("home_id") if side == "home" else fx.get("away_id")
    name = fx.get("home") if side == "home" else fx.get("away")
    if not tid:
        return []
    out = []
    try:
        evs = MB.get_last_events(tid)
    except Exception:           # noqa: BLE001
        return []
    for e in evs:
        hs, as_ = to_num(e.get("intHomeScore")), to_num(e.get("intAwayScore"))
        if hs is None or as_ is None:
            continue
        hid, aid = str(e.get("idHomeTeam") or ""), str(e.get("idAwayTeam") or "")
        if hid == str(tid):
            is_home = True
        elif aid == str(tid):
            is_home = False
        elif e.get("strHomeTeam") == name:
            is_home = True
        elif e.get("strAwayTeam") == name:
            is_home = False
        else:
            continue
        gf, ga = (hs, as_) if is_home else (as_, hs)
        if not sane_record(fx["bucket"], gf, ga):
            continue
        out.append({"gf": gf, "ga": ga, "home": is_home,
                    "date": str(e.get("dateEvent") or "")[:10], "opp": ""})
    return out


# ================================================================= АНАЛИЗ
def history_for(fx, side):
    if fx.get("src") == "sdb":
        return sdb_history(fx, side)
    # ⚾ Азия има СВОЯ история и тя НЕ е в statsapi.mlb.com — виж
    # azia_history. Без този ред всяка азиатска карта умира с „няма
    # история (0 и 0 мача)", защото baseball_history пита МЛБ по номер,
    # а азиатските отбори нямат такъв номер.
    if fx.get("src") == "azia":
        return azia_history(fx, side)
    b = fx["bucket"]
    if b == "football":
        return football_history(fx, side)
    if b == "basketball":
        return basketball_history(fx, side)
    if b == "baseball":
        return baseball_history(fx, side)
    if b == "amfootball":
        return amfootball_history(fx, side)
    # 🏉 Ръгбито има СВОЯ история и тя НЕ е по отбори: обичайният път
    # /teams/{id}/schedule за ръгби връща HTTP 500 (12 от 12 проверени).
    # `ragbi.istoriya` чете диапазонно табло — една заявка на лига носи и
    # двата отбора.
    if b == "rugby" and RAG is not None:
        try:
            return RAG.istoriya(fx, side)
        except Exception:                                    # noqa: BLE001
            return []
    return []


# 🏓 ШИРИНАТА ЗА МЕСТНИТЕ ЛИГИ — СОБСТВЕНА, НЕ ЗАЕТА (01.09.2026).
#
# 🔴 TT_SCALE (2.2) Е МЕРЕНА НА WTT Champions/Smash/Feeder И НЕ ВАЖИ ТУК.
# Не го предположих — измерих го с ходене напред върху 7691 отсъдени мача
# от Czech Liga Pro и TT Elite за 18 дни (историята за ден D свършва D−1,
# нула надничане):
#
#     ширина   Брайер     срещу монета (0.2500)
#      0.3     0.2471        −0.0029  по-добър
#      0.45    ~0.248        по-добър
#      1.0     0.2528        +0.0028  ПО-ЛОШ
#      2.2     0.2804        +0.0304  ПО-ЛОШ ОТ МОНЕТА
#
# Тоест заемането на TT_SCALE не е просто неточно — то ВЛОШАВА.
#
# ЧИСЛОТО 0.45 Е ИЗБРАНО ИЗВЪН ИЗВАДКАТА: първите 9 дни избраха ширината,
# вторите 9 я изпитаха. На НЕВИЖДАНИТЕ дни: 72 карти, обявено 67.7%,
# сбъднато 69.4% [58.0 .. 78.9], бутстрап по дни [59.7 .. 80.6] — нулевата
# хипотеза 50% е ОТХВЪРЛЕНА. TT_SCALE на същия изпит: Брайер 0.2832.
#
# ПЪТ НАЗАД: PREDICT_TTLOKAL=0 изключва целия втори източник.
TTLOKAL_SCALE = env_float("PREDICT_TTLOKAL_SCALE", 0.45, 0.05, 3.0)
# Таван на срещите, които ВЛИЗАТ в кошницата. Не е таван на картите — той е
# общият PER_SPORT. Мерено: при 4/8/12/20 на ден моделът е честен и в
# четирите (66-75% сбъднати срещу 61-71% обявени), тоест числото не е
# нагласено на ръба.
TTLOKAL_MAX = env_int("PREDICT_TTLOKAL_MAX", 8, 0, 60)
TTLOKAL_VKL = (os.environ.get("PREDICT_TTLOKAL") or "1").strip() in (
    "1", "true", "yes", "да")


def ttlokal_fixtures(now):
    """Срещите от Czech Liga Pro и TT Elite. Празен списък при всеки провал.

    🔴 ZAPUSHENO НЕ Е ПРАЗЕН СПИСЪК. tt_lokal връща сентинел, който е
    ИСТИНЕН, няма дължина и не се обхожда. Подаден нататък като списък, той
    гърми с TypeError още на събирането. Затова се проверява ИЗРИЧНО.
    Разликата е смислова: празно значи „днес няма мачове“, сентинелът значи
    „питах и не получих отговор“ — второто не бива да се брои за нула.
    """
    if TLK is None or not TTLOKAL_VKL or TTLOKAL_MAX <= 0:
        return []
    try:
        rows = TLK.srechti(now, tavan=TTLOKAL_MAX)
    except Exception as e:                                   # noqa: BLE001
        print("   ⚠ местният тенис на маса: " + str(e)[:70])
        return []
    if rows is getattr(TLK, "ZAPUSHENO", object()):
        print("   ⚠ местният тенис на маса: източникът не отговори "
              "(това е ЗАПУШВАНЕ, не празен ден)")
        return []
    if not isinstance(rows, list):
        return []
    return [x for x in rows if isinstance(x, dict)]


def model_tt_lokal(fx, now):
    """Същата форма като model_tabletennis, но за местните лиги.

    Историята идва ГОТОВА в fx["extra"] (ist_dom / ist_gost), сложена там от
    tt_lokal.srechti — нула нови заявки. Формата на върнатото е нарочно
    еднаква с model_tabletennis, за да не се пипа нищо надолу по веригата.
    """
    ex = fx.get("extra") or {}
    a, b = ex.get("ist_dom"), ex.get("ist_gost")
    if not isinstance(a, dict) or not isinstance(b, dict):
        return None
    try:
        aw, al = float(a.get("w") or 0), float(a.get("l") or 0)
        bw, bl = float(b.get("w") or 0), float(b.get("l") or 0)
    except (TypeError, ValueError):
        return None
    na, nb = aw + al, bw + bl
    if na < 5 or nb < 5:
        return None
    ra = (aw + 3.0) / (na + 6.0)
    rb = (bw + 3.0) / (nb + 6.0)
    p = clampf(logistic((logit(ra) - logit(rb)) * TTLOKAL_SCALE),
               TT_P_MIN, TT_P_MAX)
    to_win = 4 if int(ex.get("best_of") or 5) >= 7 else 3
    p_game = invert_bo(p, to_win)
    return {"p_home": p, "p_away": 1.0 - p,
            "a": {"w": aw, "l": al}, "b": {"w": bw, "l": bl},
            "ra": ra, "rb": rb, "to_win": to_win,
            "dist_h": bo_distribution(p_game, to_win),
            "dist_a": bo_distribution(1.0 - p_game, to_win),
            "n_malka": min(na, nb), "shirina": TTLOKAL_SCALE,
            # 🔴 ПРОЗОРЕЦЪТ ПЪТУВА С МОДЕЛА (02.09.2026). Картата пишеше
            # „за година и половина“ за ВСЕКИ тенис на маса, защото този
            # текст е закован в общия клон и обслужва WTT, където историята
            # НАИСТИНА е 548 дни. Местните лиги гледат 14 дни — тоест на
            # читателя се казваше, че 64 мача са събрани за година и половина,
            # а те са от две седмици. Числата бяха верни; ЛЪЖЕШЕ ВРЕМЕТО.
            "dni": getattr(TLK, "DNI", None) if TLK is not None else None,
            "ok": na >= 5 and nb >= 5}


def samp(a, b):
    """Върху колко мача стъпва картата — на човешки.

    Пишеше „извадка 30+30 мача". Плюсът подвежда: човек го чете като сбор 60,
    а числата са ПООТДЕЛНО за двата отбора. Затова сега е „по 30 и 30 мача" —
    същите числа, но се четат както са замислени.
    """
    x, y = int(a), int(b)
    if x == y:
        return "гледани по " + str(x) + mn(x, " мач", " мача") + " на всеки"
    return ("гледани " + str(x) + mn(x, " мач", " мача") + " на единия и "
            + str(y) + " на другия")


# 🔴 ПРЕРАБОТЕНО 11.08.2026. Звездите казваха „увереност", а НЕ мереха
# увереност. Резултатът се четеше в стаята така:
#     „1 · победа Bodo/Glimt — 50%   ⭐⭐⭐ добра увереност"
# Петдесет процента е монета. Три звезди до нея са обещание, което самото
# число опровергава два сантиметра по-нагоре. И обратното: две карти с по 92%
# получаваха различен брой звезди и никой не разбираше защо.
#
# Причината е, че grade() смесва ДВЕ различни неща в един символ: колко мача
# има зад картата (n_eff) и колко категоричен е превесът (strength). Затова
# сега всяко от двете си казва своето с думи:
#   • звездите остават, но говорят за ДАННИТЕ — колко стъпка има под картата
#   • отделен ред казва колко е категоричен изборът, и той идва ПРАВО от
#     вероятността, така че не може да ѝ противоречи
ZVEZDI_DUMA = {1: "малко данни", 2: "прилична история", 3: "богата история"}

# Границите не са на око. Върху 75 586 мача от бектеста измереното е, че под
# 58% посочената страна печели горе-долу колкото хвърлена монета, между 58 и
# 65 има истински, но лек превес, а над 75 разликата е видима с просто око.
# 🔴 ДОЛНОТО СТЪПАЛО БЕШЕ ЕДНО ЗА ВСИЧКО ПОД 55% (26.08.2026).
# Прочетена жива карта от 25.08, 13:38: „20% · почти равностойни".
# Двадесет процента НЕ са равностойни — те са ясно „не". Причината е, че
# последното стъпало тръгваше от 0.00, тоест думата, писана за монетата,
# покриваше и 20%, и 35%, и 44%. В дневника (759 записа) стъпалото се
# разпъваше от 20.0% до 55.0% — 211 карти под един етикет.
#
# ИЗМЕРЕНО върху 217 отсъдени карти с пазарна цена (числото на картата Е
# пазарното от 25.08, sglasie.TEGLO = 0.00):
#     под 33%    n=  9 · обявява 25.1% · сбъдва 11.1% [ 2.0 .. 43.5]
#     33 – 45%   n= 32 · обявява 40.6% · сбъдва 40.6% [25.5 .. 57.7]
#     45 – 55%   n= 54 · обявява 50.9% · сбъдва 35.2% [23.8 .. 48.5]
# Тоест долната лента наистина е ДРУГО НЕЩО, не „почти равностойни".
# ЧЕСТНО: и трите интервала се застъпват. Тези числа НЕ доказват, че
# границите са на точното място — доказват само, че ЕДНА дума за 20% и за
# 54% е невярна за поне единия край. Разделянето е продуктово, не напасване.
#
# ЧЕСТНО ЗА ГРАНИЦИТЕ: 0.45 е нашата собствена летва за футбола (MIN_SHOW_P),
# а 0.33 е СТРУКТУРНА — при три изхода една трета е точката, под която
# посоченият изход е по-слаб от сляпо теглене между трите. НЕ са напасвани
# по сбъдваемост: извадката под 45% е 41 карти общо и не стига за напасване.
P_DUMI = ((0.80, "🟢 много ясен фаворит"),
          (0.68, "🟢 ясен фаворит"),
          (0.60, "🟡 лек фаворит"),
          (0.55, "🟠 мъничък превес"),
          (0.45, "🔴 почти равностойни"),
          (0.33, "🔴 по-скоро не се сбъдва"),
          (0.00, "🔴 малък шанс"))


def p_duma(p):
    """Присъдата с думи — идва ПРАВО от ПОКАЗАНИЯ процент, не от суровото p.

    🔴 ДОТУК ИДВАШЕ ОТ СУРОВОТО (оправено 26.08.2026). Картата ПОКАЗВА
    pct(p) = закръглено до цяло, а думата се съдеше по непокътнатото p.
    Затова едно и също показано число излизаше с две различни думи:
        p = 0.5452 → „55% · почти равностойни"
        p = 0.5500 → „55% · мъничък превес"
        p = 0.5970 → „60% · мъничък превес"
        p = 0.6027 → „60% · лек фаворит"
    ИЗМЕРЕНО в дневника (759 записа): 44 карти (5.8% [4.3 .. 7.7]) показват
    число, което по стълбицата заслужава ДРУГА дума от написаната — и всичките
    44 в една посока: думата е с едно стъпало ПО-НИСКА от показаното число.
    Разпределение: 24 на „55%", 8 на „60%", 7 на „80%", 5 на „68%".

    Закръглението е СЪЩИЯТ израз като в pct() — буквално, не „същото по
    смисъл": int(round(x * 100.0)) в Python 3 е банково и round(0.545 * 100)
    дава 54, не 55. Две различни закръгления пак биха се разминали.
    """
    try:
        x = float(p)
    except (TypeError, ValueError):
        return ""
    # ЕДНО МЯСТО. Съди се точно числото, което човекът вижда на картата.
    x = int(round(x * 100.0)) / 100.0
    for prag, duma in P_DUMI:
        if x >= prag:
            return duma
    return ""


