def liga_bg(name, cap=44):
    """Български надпис за турнира, ако го познаваме. Иначе — подрязан оригинал."""
    s = str(name or "").strip()
    low = s.lower()
    for klyuch, bg in LIGA_BG:
        if klyuch in low:
            return bg
    if len(s) > cap:
        s = s[:cap - 1].rstrip() + chr(8230)
    return s


def pobedi_zagubi(w, l):
    """„10 победи и 21 загуби" вместо „10-21".

    🔴 ДОБАВЕНО 11.08.2026 след като прочетох живата карта в стая 27. Там
    пишеше „Lily ZHANG: 10-21 за 18 месеца". Тирето между две числа може да е
    победи-загуби, може да е резултат, може да е диапазон. Читателят не е
    длъжен да гадае, а ние не печелим нищо от съкращаването.
    """
    w, l = int(w or 0), int(l or 0)
    return (str(w) + mn(w, " победа", " победи")
            + " и " + str(l) + mn(l, " загуба", " загуби"))


def boeve_index(n):
    """Опашката за ММА: колко боя на този човек сме гледали ние."""
    n = int(n or 0)
    if n == 0:
        return " · него не сме го следили"
    return " · следили сме " + str(n) + mn(n, " негов бой", " негови боя")


def one(x, d=1):
    return ("%." + str(d) + "f") % float(x)


# --- ФИШ-ЕЗИКЪТ ---------------------------------------------------------------
# Прогнозата се изписва като на фиш: 1 / Х / 2, после кой. Никакви гатанки.
OU_MIN = 0.57           # ред „Над/Под 2.5 гола" само когато матрицата е категорична


def pick_1x2(p1, px, p2, home, away):
    """Футболният избор на фиш-език. Връща (текст, вероятност, база).

    ⚠️ ДВОЙНИЯТ ШАНС Е ИЗКЛЮЧЕН (05.08.2026). FOOT_SINGLE_MIN е 0.0, тоест
    всеки път излиза САМ победител — 1, Х или 2. Долният клон е недостижим,
    докато собственикът не го включи изрично. Причината е в неговите думи:
    коефициентът на двойния шанс е твърде нисък, за да си струва.

    ВАЖНОТО, което ОСТАВА в сила: клонът „Х · равен" вече работи наистина.
    Допреди 04.08 той беше практически недостижим, защото домакинството се
    броеше двойно и вдигаше p_home изкуствено. След поправката равенството
    печели най-високата вероятност там, където наистина е най-вероятно —
    видяно на живо: „Х · равен — 40%" при два предпазливи отбора.

    ЗАЩО ИМА ДВОЕН ШАНС — измерено на 04.08.2026, не усетено:
      От единайсет отсъдени футболни прогнози познахме ДВЕ. И единайсетте бяха
      „1" или „2" — нито една „Х". Причината не е лош късмет, а устройство:
      при Поасон равенството почти никога не е най-вероятният ЕДИНИЧЕН изход
      (около 0.28 срещу около 0.40 за домакина), тоест клонът за „Х" стоеше
      в кода, но беше практически недостижим.
      ЧЕТИРИ от деветте загуби бяха именно равенства: 0:0, 1:1, 0:0, 2:2.
      Двоен шанс върху същите единайсет мача дава ШЕСТ познати вместо две.
      Това е сметка върху вече изиграни мачове, не обещание за бъдещето.

    Правилото е едно: твърдим сам победител само когато сме убедени
    (>= FOOT_SINGLE_MIN). Иначе покриваме и равенството. Силните карти
    остават единични — двойният шанс не размива това, което вече знаем.

    Базата се връща, защото „1" се пада на случайност веднъж на три пъти,
    а „1Х" — два пъти на три. Без нея двойният шанс би получавал звезди
    наготово.
    """
    if px >= p1 and px >= p2:
        return "Х · равен", px, 1.0 / 3.0       # равенството наистина води
    vodi_home = p1 >= p2
    p_vodi = p1 if vodi_home else p2
    ime = str(home) if vodi_home else str(away)
    if p_vodi >= FOOT_SINGLE_MIN:
        return (("1 · победа " if vodi_home else "2 · победа ") + ime,
                p_vodi, 1.0 / 3.0)
    if vodi_home:
        return "1Х · " + ime + " или равен", p1 + px, 2.0 / 3.0
    return "Х2 · " + ime + " или равен", p2 + px, 2.0 / 3.0


def pick_win(fav_home, home, away):
    """Отборните спортове без равен: 1 · победа <отбор> или 2 · победа <отбор>."""
    return ("1 · победа " + str(home)) if fav_home else ("2 · победа " + str(away))


def pick_name(fav_home, home, away):
    """Индивидуалните спортове: 1 · <име> или 2 · <име>."""
    return ("1 · " + str(home)) if fav_home else ("2 · " + str(away))


# 🔴 ТУК СИ НАПРАВИХ ДУБЛИКАТ И ГО МАХНАХ (25.08.2026).
# Написах втора DVA_IZHODA с шест спорта, без да видя, че такава ВЕЧЕ
# съществува на ред 326 с ОСЕМ (плюс хокей и амер. футбол). В Python втората
# просто презаписва първата — без грешка, без дума. Последицата беше тиха и
# грозна: dolen_prag() щеше да върне ФУТБОЛНАТА летва 45% за хокея и амер.
# футбол вместо 53%, тоест два спорта щяха да почнат да пускат карти под
# прага. Хвана го съществуваща проверка („всеки спорт има ясна летва") от
# 890-те — точно за това ги има.
# Смисълът е един и същ: спорт с два изхода. Ползва се оригиналът.


def ogledalo(pick, home, away):
    """Същият избор, но за ДРУГАТА страна. Празно, ако не може.

    🔴 ФУТБОЛЪТ ИЗОБЩО НЕ ВЛИЗА ТУК, и това е платено с грешка (25.08.2026).
    Смятах, че „обратното на победа домакин" е „победа гост" — а има и равен.
    С това мълчаливо допускане измерих +27.3% печалба от обръщането, каквато
    не съществува. Мерено наново по истинските резултати: при футбола
    съвпадаме с пазарния фаворит в 46 от 50 мача (92%), тоест там няма какво
    да се обръща — губим от САМИТЕ мачове, не от страната.
    """
    s = str(pick or "")
    if s[:1] not in ("1", "2"):
        return ""                      # равният няма огледало
    dom_e = s.startswith("1")
    # Настройки като „(в мача)" се пренасят — те описват ПАЗАРА, не страната.
    nastavka = ""
    if s.endswith(")") and " (" in s:
        nastavka = s[s.rindex(" ("):]
    nov = (pick_win(not dom_e, home, away) if " · победа " in s
           else pick_name(not dom_e, home, away))
    return nov + nastavka


def over_under_line(p_over):
    """Ред „Над/Под 2.5 гола" от готовата голова матрица (P на общо 3+ гола).

    Излиза само когато едната страна е поне 57% — иначе редът е шум.

    ЧИСЛОТО СЕ СВИВА ПРЕДИ ОБЯВЯВАНЕ. Измерено върху 75 586 изиграни мача:
    суровото обявяваше 64.7% при реални 60.7% (над) и 64.9% при реални 57.4%
    (под). Пълната сметка стои при OU_SHRINK.
    """
    p = svii(p_over, OU_SHRINK)
    if p is None:
        return ""
    if p >= OU_MIN:
        return "Над 2.5 гола: <b>" + pct(p) + "</b>"
    if (1.0 - p) >= OU_MIN:
        return "Под 2.5 гола: <b>" + pct(1.0 - p) + "</b>"
    return ""


# ------------------------------------------------- ТОТАЛИ ЗА ОСТАНАЛИТЕ СПОРТОВЕ
# Футболът отдавна има ред „Над/Под 2.5 гола". Собственикът поиска същото и за
# другите спортове: точки за баскетбола, сетове за волейбола и тениса.
# Всеки ред тук излиза САМО ако едната страна е поне OU_MIN — иначе е шум и се
# премълчава. По-добре три реда сигурни, отколкото пет реда пълнеж.

TOTAL_MIN = OU_MIN          # един и същ праг като при головете


def _norm_cdf(z):
    """Стандартно нормално разпределение. math.erf стига — без numpy."""
    return 0.5 * (1.0 + math.erf(z / math.sqrt(2.0)))


def points_total_line(exp_total, sigma_margin, unit="точки"):
    """Над/Под общо точки, с ЯСНО ИЗПИСАНА линия.

    ЗАЩО ЛИНИЯТА НЕ Е НА ОЧАКВАНИЯ СБОР (първата ми версия беше сгрешена):
    сложиш ли линията точно на средата, отговорът винаги е около 50% и редът
    не казва нищо — просто мълчеше на всеки мач. Затова линията е на половин
    отклонение ПОД средата: тогава твърдението „над X точки" носи смисъл и
    процентът е реален, а не украсен. Линията се пише на глас, за да може
    всеки да я провери сам.

    ЗА ОТКЛОНЕНИЕТО, честно: моделът знае отклонението на РАЗЛИКАТА. Сборът
    се колебае повече — двата отбора вдигат и свалят темпото ЗАЕДНО, а темпото
    движи сбора. Затова тук отклонението е умишлено по-широко (1.25 пъти):
    по-широко значи по-предпазлив процент, а не по-самоуверен.
    """
    if not exp_total or exp_total <= 0:
        return ""
    mean = float(exp_total)
    sd = max(4.0, float(sigma_margin or 11.5) * 1.25)
    line = math.floor(mean - 0.5 * sd) + 0.5
    if line <= 0:
        return ""
    p_over = 1.0 - _norm_cdf((line - mean) / sd)
    # ЧЕСТНО ЗА ТОЗИ ПРОЦЕНТ (добавено 04.08.2026 след измерване):
    # линията стои на половин отклонение под средата, а вероятността се смята
    # със СЪЩОТО отклонение — значи z е закован на −0.5 и процентът излиза
    # 68-70% при ВСЕКИ мач. Измерено: 111 от 111 проби в този тесен обхват,
    # нито една „Под". Твърдението не е невярно — то наистина има тази
    # вероятност — но само по себе си е ПРАЗНО, защото не се променя.
    # Информацията, която липсваше, е самият ОЧАКВАН СБОР: той се мени от мач
    # на мач и точно той казва нещо. Затова се изписва до линията.
    # Закръгляне на линията НЕ е лекарството — измерено е, че тогава редът
    # изчезва в 103 от 111 мача, тоест това е изтриване, а не поправка.
    ochakvan = "~" + str(int(round(mean))) + " " + unit + " общо · "
    if p_over >= TOTAL_MIN:
        return (ochakvan + "Над " + ("%.1f" % line) + ": <b>" + pct(p_over) + "</b>")
    if (1.0 - p_over) >= TOTAL_MIN:
        return (ochakvan + "Под " + ("%.1f" % line) + ": <b>" + pct(1.0 - p_over) + "</b>")
    return ""


# ═══════════ СВИВАНЕ ПРЕДИ ОБЯВЯВАНЕ ═══════════
# ИЗМЕРЕНО ВЪРХУ 75 586 ИЗИГРАНИ МАЧА (2014-2026, 19 лиги), с истинския код на
# бота и без надничане в бъдещето. Проверката за надничане е направена така:
# същият бектест е пуснат три пъти с различен отрез на историята и ЧЕСТНИЯТ
# ред излиза НАЙ-СЛАБ (50.06% срещу 53.43% при изтекъл ден). Тоест числата тук
# са долната, истинската граница.
#
# ГЛАВНИЯТ РЕД (1/Х/2) СЕ ОКАЗА ЧЕСТЕН: обявява 48.4%, сбъдва се 50.1% —
# подценява се в своя вреда. Нито една кофа не надува.
#
# НО ДОПЪЛНИТЕЛНИТЕ РЕДОВЕ НАДУВАТ, и то много:
#     Над 2.5      обявено 64.7%  сбъднато 60.7%   −4.0
#     Под 2.5      обявено 64.9%  сбъднато 57.4%   −7.5
#     Гол-гол ДА   обявено 62.6%  сбъднато 58.4%   −4.2
#     Гол-гол НЕ   обявено 62.0%  сбъднато 55.0%   −6.9
# И колкото по-категоричен е редът, толкова по-голяма е лъжата: при обявени
# над 70% реалното е 66.6% за над/под и 63.9% за гол-гол.
#
# ЛЕКАРСТВОТО: числото се свива към 50%, преди да се обяви. Множителите НЕ са
# нагласени върху същите данни — научени са от 2014-2021 (47 132 мача) и
# изпитани върху 2022-2026 (28 454 мача, невиждани):
#     над/под 2.5   лъжа −5.8 пункта  →  +0.4 пункта
#     гол-гол       лъжа −5.4 пункта  →  +0.5 пункта
# Цената е, че редовете излизат около два пъти по-рядко. Купеното е, че когато
# излязат, числото им е вярно.
#
# ПЪТ НАЗАД: две константи. Връщат се на 1.0 и всичко е както преди.
OU_SHRINK = env_float("PREDICT_OU_SHRINK", 0.58, 0.2, 1.0)
BTTS_SHRINK = env_float("PREDICT_BTTS_SHRINK", 0.56, 0.2, 1.0)


def svii(p, k):
    """Свива вероятността към монетата. k=1.0 значи „не пипай"."""
    try:
        return clampf(0.5 + float(k) * (float(p) - 0.5), 0.0, 1.0)
    except (TypeError, ValueError):
        return None


def btts_line(p_btts):
    """Ред „Гол-гол" (и двата отбора бележат) от готовата голова матрица.

    ТОВА ЧИСЛО СЕ СМЯТАШЕ И СЕ ХВЪРЛЯШЕ. `matrix_markets` вече обхожда всичките
    121 клетки и сумира p_btts (тези с i>=1 и j>=1), но НИТО ЕДИН ред не го
    четеше — стоеше сметнато и неизползвано от самото начало.

    Прагът е същият OU_MIN като при Над/Под 2.5: под 57% и в двете посоки редът
    мълчи, защото „51% да вкарат и двата" не е прогноза, а монета.

    ЗАЩО НЕ ПРЕПИСВА Над/Под 2.5 — измерено върху 169 двойки ламбди: в 12 случая
    излиза „Над 2.5" ЗАЕДНО с „Гол-гол: НЕ" (единият громи — много голове, но
    само от едната страна), а в 13 случая Над/Под мълчи, докато гол-гол говори.
    Тоест 25 от 169 карти печелят ред, който другият не може да даде.

    ЧЕСТНО ЗА ТОЗИ РЕД: измерено е, че се МЕНИ както трябва (227 различни
    стойности от 231 входа през model_football, от 16% до 92%) — тоест не е
    закована константа като реда за точки, който оправихме. НО калибрацията му
    НЕ е проверена срещу изиграни мачове: дали „Гол-гол: ДА 61%" се сбъдва в 61%
    от случаите, ще покаже само дневникът след няколко седмици.
    """
    if p_btts is None:
        return ""
    try:
        surovo = float(p_btts)
    except (TypeError, ValueError):
        return ""
    # Пазачът гледа СУРОВОТО число. Ако го гледаше свитото, изродена матрица с
    # 0 или 1 щеше да мине, защото свиването я издърпва навътре.
    if surovo <= 0.0 or surovo >= 1.0:
        return ""                      # изродена матрица — по-добре мълчание
    # Свиване ПРЕДИ прага: измерено е, че суровото число надува с 4-7 пункта.
    p = svii(surovo, BTTS_SHRINK)
    if p is None:
        return ""
    if p >= OU_MIN:
        return "Гол-гол: ДА <b>" + pct(p) + "</b>"
    if (1.0 - p) >= OU_MIN:
        return "Гол-гол: НЕ <b>" + pct(1.0 - p) + "</b>"
    return ""


# ═════════════════ ВТОРАТА ПРОГНОЗА ОТ СЪЩИЯ МАЧ: ТОТАЛЪТ С ЦЕНА ═════════════
# 🔴 НОВО 19.08.2026. Дотук от един мач излизаше ЕДНА карта (1/Х/2), а редът
# „Над 2.5 гола" висеше в рубриката „И още" БЕЗ ЦЕНА — тоест беше твърдение,
# което човекът няма къде да ползва, и което оценителят не отсъждаше.
#
# ДВАТА КАНТАРА, ИЗМЕРЕНИ СЪЩИЯ ДЕН СРЕЩУ ЖИВИЯ guest слой на Pinnacle:
#   има ли мачове  → в отговора стоят 7 572 футболни тотала за целия мач,
#                    606 бейзболни, 323 баскетболни
#   търгува ли се  → от НАШИТЕ мачове получават линия на половинка:
#                    футбол 943 от 944 · бейзбол 14 от 14 · баскетбол 26 от 29
#
# ЦЕНАТА В ЗАЯВКИ: НУЛА. Това е същият отговор на /markets/straight, който вече
# дърпаме за 1/Х/2 — просто дотук изхвърляхме всичко освен moneyline.
# Измерено: 6 заявки за трите спорта, точно колкото и преди.
#
# ЗАЩО НЕ ЗА ВСИЧКИ СПОРТОВЕ:
#   • тенис — Pinnacle котира ГЕЙМОВЕ (линия 21.5), а ние моделираме сетове.
#     Нямаме модел за геймове, значи нямаме право на твърдение.
#   • волейбол и тенис на маса — Pinnacle НЯМА тези спортове (0 лиги, измерено).
#   • ММА — няма тотал за целия мач в този слой.
#   • хокей и американски футбол — няма номер на спорта при тях изобщо.
# Остават трите, за които и моделът, и пазарът говорят за едно и също число.
PAZAREN_TOTAL = env_int("PREDICT_TOTAL_PAZAR", 1, 0, 1)
# Колко тотал-карти най-много от едно пускане. Тоталът е ДОБАВКА към продукта,
# не заместител: ако едно пускане даде 17 карти 1/Х/2, стаята не бива да получи
# още 17 отгоре в същата минута.
TOTAL_MAX = env_int("PREDICT_TOTAL_MAX", 4, 0, 20)
# 🔴 ПРАГЪТ Е ПРАГЪТ НА ДВОИЧНИТЕ ПАЗАРИ, НЕ ОТДЕЛНО ЧИСЛО.
# Над/под е пазар с ДВА изхода и ние винаги избираме по-вероятната страна —
# точно устройството, заради което съществува MIN_SHOW_P_DVA. Затова тук стои
# същото число, а не собствено. Редът „И още" ползва 57%, но той е бележка под
# картата; това е ЦЯЛА КАРТА и се съди по правилото за карти.
# Измерено днес върху едни и същи 16 карти:
#   праг 0.57 → 1 тотал · праг 0.55 → 2 тотала · праг 0.53 → виж сухото пускане
# Правото на този праг идва от калибрацията: бейзболът греши до 1.3 пункта,
# баскетболът до 1.6, футболът носи измерения си множител. Твърдение на 54%
# от калибриран модел значи нещо; от некалибриран не би значело.
TOTAL_KARTA_MIN = env_float("PREDICT_TOTAL_MIN", MIN_SHOW_P_DVA, 0.50, 0.90)

# Кои спортове имат И модел за сбора, И пазар за него.
TOTAL_SPORTS = ("football", "baseball", "basketball")
# Колко пъти по-широко се люлее СБОРЪТ точки от лиговото отклонение на
# разликата. Измерено — виж бележката при баскетбола в analyse.
BASK_TOTAL_SD = env_float("PREDICT_BASK_TOTAL_SD", 1.90, 1.0, 3.0)
TOTAL_DUMA = {"football": "гола", "baseball": "рънове", "basketball": "точки"}


def _poisson_over(lam, line):
    """P(сборът е НАД линията) при Поасон. Линията е на половинка."""
    need = int(math.floor(float(line))) + 1
    p_pod = sum(poisson_pmf(k, lam) for k in range(0, need))
    return clampf(1.0 - p_pod, 0.0, 1.0)


# 🔴 БЕЙЗБОЛНИТЕ РЪНОВЕ НЕ СА ПОАСОН — ИЗМЕРЕНО, НЕ ПРОЧЕТЕНО (19.08.2026).
#
# Първата ми версия смяташе тотала на бейзбола с Поасон, както футбола.
# Измерих я срещу 1965 изиграни мача от този сезон (историята, която ботът и
# без това дърпа за всеки отбор):
#
#   среден сбор 9.41 · ДИСПЕРСИЯ 22.96 — Поасон изисква двете да са РАВНИ
#
#   линия   реално НАД   Поасон казва   грешка
#    5.5      77.9%         90.7%       +12.8 т
#    6.5      71.3%         82.8%       +11.5 т
#    7.5      60.6%         72.2%       +11.6 т     ← точно тук пусна карта
#    8.5      52.3%         59.7%        +7.4 т
#    9.5      43.4%         46.6%        +3.3 т
#
# Тоест картата „Над 7.5 рънове 64%" щеше да е твърдение с дванайсет пункта
# надуване в СУРОВИЯ вид — и щеше да казва „Над" на всеки мач, защото Поасон
# не вижда колко широко се люлее бейзболът.
#
# Отрицателното биномно приема дисперсията като параметър. С измерената
# (22.96 / 9.41 = 2.44):
#   дисперсия ×1.00 (Поасон)   средна грешка +5.5 т · най-голяма +12.8 т
#   дисперсия ×2.00            средна грешка +1.3 т · най-голяма  +3.6 т
#   дисперсия ×2.44 (мерената) средна грешка −0.1 т · най-голяма  −1.3 т
#   дисперсия ×3.00            средна грешка −1.6 т · най-голяма  −4.3 т
#
# И ВТОРО, ПО-ВАЖНО: върху вече калибрирано число свиването ВРЕДИ.
#   НБ 2.44 без свиване      средна грешка −0.1 т · най-голяма  −1.3 т
#   НБ 2.44 + свиване 0.58   средна грешка −1.4 т · най-голяма −11.4 т
# Затова футболският множител НЕ се прилага тук. Свиване се слага там, където
# е измерено надуване — не по навик.
#
# ЧЕСТНО ЗА 2.44: измерена е върху СМЕСЕНОТО разпределение на всички мачове,
# тоест вътре в нея влиза и разликата между отделните двойки отбори. Нашите
# очаквани сборове за днес се движат между 8.4 и 9.6 — разсейване около 0.15
# срещу 22.96 обща дисперсия, тоест пренебрежимо. Но числото е за МЛБ и за
# този сезон; сменят ли се топките или стадионите, мери отново.
MLB_DISP = env_float("PREDICT_MLB_DISP", 2.44, 1.0, 6.0)


def _nb_over(mu, disp, line):
    """P(сборът е НАД линията) при отрицателно биномно с дисперсия mu*disp.

    disp = 1 е точно Поасон и функцията го връща без сметка — така една и съща
    врата обслужва двата случая и няма как да се разминат.
    """
    mu = float(mu)
    disp = float(disp)
    if mu <= 0:
        return None
    if disp <= 1.0:
        return _poisson_over(mu, line)
    r = mu / (disp - 1.0)               # брой „успехи" в НБ
    q = r / (r + mu)                    # вероятност за успех
    need = int(math.floor(float(line))) + 1
    s_pod, chlen = 0.0, q ** r
    for k in range(0, need):
        if k:
            chlen *= (r + k - 1.0) / k * (1.0 - q)
        s_pod += chlen
    return clampf(1.0 - s_pod, 0.0, 1.0)


def total_p_over(tot, line):
    """Нашата вероятност сборът да е НАД тази линия. None = не можем.

    Три различни сметки, защото трите спорта се броят различно:
      football   — от готовата голова матрица (същата, от която идва 1/Х/2)
      baseball   — Поасон върху очаквания сбор рънове
      basketball — нормално разпределение около очаквания сбор точки
    """
    if not isinstance(tot, dict) or line is None:
        return None
    try:
        line = float(line)
    except (TypeError, ValueError):
        return None
    vid = str(tot.get("vid") or "")
    try:
        if vid == "mx":
            mx = score_matrix(float(tot["lam_h"]), float(tot["lam_a"]))
            return _hock_p_over(mx, line)
        if vid == "poisson":
            lam = float(tot["lam"])
            if lam <= 0:
                return None
            return _nb_over(lam, float(tot.get("disp") or 1.0), line)
        if vid == "normal":
            mean, sd = float(tot["mean"]), float(tot["sd"])
            if mean <= 0 or sd <= 0:
                return None
            return clampf(1.0 - _norm_cdf((line - mean) / sd), 0.0, 1.0)
    except (TypeError, ValueError, KeyError, ZeroDivisionError):
        return None
    return None


def pazaren_total(an):
    """Втора прогноза от същия мач: над/под ЛИНИЯТА НА ПАЗАРА, с неговата цена.

    Връща нов анализ (или None), готов за карта. Ключът му е ключът на мача с
    опашка „|total", за да не се бие с картата 1/Х/2 в тефтера.

    🔴 ЛИНИЯТА Я ИЗБИРА ПАЗАРЪТ (виж pinnacle.total_za). Ако я избирахме ние —
    измежду шестте алтернативни линии, които Pinnacle дава — щяхме да взимаме
    всеки път онази, на която сме най-несъгласни с него, и да я обявяваме за
    най-уверена. Това е надничане, обърнато наопаки: не в бъдещето, а в
    собствения ни модел.

    🔴 ЧЕСТНО ЗА ПРОЦЕНТА. Свиването OU_SHRINK (0.58) е ИЗМЕРЕНО върху 75 586
    футболни мача, но САМО за линията 2.5 гола. Тук се прилага и на другите
    линии, и на другите два спорта — това е ПРЕНОС, не измерване. Приложен е,
    защото посоката на грешката е известна (суровата матрица надува), а
    големината — не; свиване към монетата може само да намали обявеното, тоест
    греши в НАША вреда. Истинската калибрация ще дойде от дневника, щом се
    съберат отсъдени тотали. Дотогава числото е предпазливо, не доказано.
    """
    if not PAZAREN_TOTAL or PIN is None or not isinstance(an, dict):
        return None
    b = str(an.get("bucket") or "")
    if b not in TOTAL_SPORTS:
        return None
    tot = an.get("tot")
    if not isinstance(tot, dict):
        return None
    fx = an.get("fx") or {}
    ex = fx.get("extra") or {}
    dom = str(ex.get("home_en") or fx.get("home") or "")
    gost = str(ex.get("away_en") or fx.get("away") or "")
    if not dom or not gost:
        return None
    try:
        line, c_nad, c_pod = PIN.total_za(b, dom, gost)
    except Exception:                                        # noqa: BLE001
        return None
    if line is None or not (c_nad and c_pod):
        return None
    surovo = total_p_over(tot, line)
    if surovo is None or surovo <= 0.0 or surovo >= 1.0:
        return None
    # 🔴 СВИВАНЕТО Е ПО СПОРТ, НЕ ГЛОБАЛНО. Всеки модел си носи своя
    # множител: футболът 0.58 (измерен върху 75 586 мача за линия 2.5),
    # бейзболът и баскетболът 1.0, защото техните разпределения вече са
    # калибрирани с ИЗМЕРЕНА дисперсия и свиването само би ги развалило.
    p_nad = svii(surovo, float(tot.get("svii") or 1.0))
    if p_nad is None:
        return None
    duma = TOTAL_DUMA.get(b, "")
    lstr = ("%.1f" % float(line))
    if p_nad >= TOTAL_KARTA_MIN:
        pick, p, cena = "Над " + lstr + " " + duma, p_nad, c_nad
    elif (1.0 - p_nad) >= TOTAL_KARTA_MIN:
        pick, p, cena = "Под " + lstr + " " + duma, 1.0 - p_nad, c_pod
    else:
        return None
    # Очакваният сбор е ЕДИНСТВЕНОТО, което мени този ред от мач на мач —
    # затова стои на картата. Без него читателят вижда само процент и линия и
    # няма как да прецени дали твърдението е близко или далечно.
    if str(tot.get("vid")) == "mx":
        ochakvan = float(tot.get("lam_h") or 0.0) + float(tot.get("lam_a") or 0.0)
    elif str(tot.get("vid")) == "poisson":
        ochakvan = float(tot.get("lam") or 0.0)
    else:
        ochakvan = float(tot.get("mean") or 0.0)
    # 🔴 СВОЙ КЛЮЧ, ИНАЧЕ ДНЕВНИКЪТ Я ПОГЛЪЩА (19.08.2026). log_pick пази
    # дневника от двойно вписване, като сравнява `key` — а той е ключът на
    # МАЧА. Тотал-картата е за същия мач, значи щеше да намери 1/Х/2 записа,
    # да реши „вече е вписан" и да не остави НИЩО. Тоест картата излиза в
    # стаята, а оценителят никога не научава за нея: тиха загуба.
    # Опашката „|total" е и ключът в тефтера — така един мач може да даде
    # ДВЕ карти, но всяка най-много веднъж.
    fx2 = dict(fx)
    fx2["_key"] = str(fx.get("_key") or "") + "|total"
    nov = {
        "fx": fx2, "bucket": b, "pick": pick, "p": float(p),
        "second": "", "third": "",
        "why": ["Очакван сбор по нашите числа: " + one(ochakvan) + " " + duma,
                "Линията " + lstr + " е тази, която пазарът котира за този мач"],
        "sample": an.get("sample") or "", "n_eff": float(an.get("n_eff") or 0.0),
        "strength": abs(float(p) - 0.5) * 2.0,
        "stars": int(an.get("stars") or 1),
        "pazar_cena": cena, "pazar_izt": "pinnacle",
        "vid_karta": "total", "total_line": float(line),
    }
    # Пазарната вероятност БЕЗ маржа — само с нея сравнението „ние срещу
    # пазара" значи нещо. Двата изхода на тотала са пълен набор, затова
    # маржът се маха точно както при 1/2.
    try:
        _s = (1.0 / float(c_nad)) + (1.0 / float(c_pod))
        if _s > 0:
            _chist = (1.0 / float(cena)) / _s
            nov["pazar_p"] = round(_chist, 4)
            nov["pazar_v"] = 2
    except (TypeError, ValueError, ZeroDivisionError):
        pass
    return nov


# ------------------------------------------------------- 🏒 ХОКЕЙНИЯТ ТОТАЛ
# Хокеят има готова голова матрица (model_hockey дава lam_h и lam_a), но досега
# от нея излизаше само едно голо число в скоби. Тук тя се ползва докрай.
#
# ЗАЩО rho=0: Диксън-Коулс дърпа четири клетки с множител 1 − lh·la·rho. При
# футболни ламбди (1.5:1.2) това е 1.234 — лека добавка към 0:0. При хокейни
# (3.2:3.0) същата формула дава 2.248, тоест УДВОЯВА 0:0. Корекцията е линейна
# по произведението, а в хокея то е шест пъти по-голямо и калибровката ѝ се
# разпада. Затова тук се вика score_matrix(..., rho=0.0) — както прави и
# самият model_hockey.
#
# ЗАЩО ЛИНИЯТА Е СТЪЛБА ОТ ДВЕ, А НЕ ЕДНА: измерено върху 992 реални двойки от
# живата НХЛ таблица очакваният сбор е между 4.94 и 7.72 гола (медиана 6.24).
# При линия 3.5 отговорът е „над" в 992 от 992 случая — закована истина, тоест
# празен ред. 5.5 е истинската хокейна линия, но при сбор между 5.15 и 6.10 тя
# дава 43-57% и мълчи (376 от 992 мача); тогава се стъпва на 6.5, която точно в
# този диапазон говори ясно. Линиите 4.5 и 7.5 бяха махнати: избират се 0 пъти
# от 19881 проби — тоест са мъртъв код, не предпазител.
HOCK_TOTAL_LINES = (5.5, 6.5)


def _hock_p_over(mx, line):
    """P(общо голове над линията) направо от готовата голова матрица."""
    need = int(math.floor(float(line))) + 1
    s = 0.0
    for i in range(MAXG + 1):
        for j in range(MAXG + 1):
            if i + j >= need:
                s += mx[i][j]
    return s


def hockey_goals_line(lam_h, lam_a):
    """Над/Под общо голове в хокея, с ясно изписана линия.

    Редът НЕ е константа — измерено върху 992-те двойки дава 22 различни
    процента в обхват 57-78%, най-честият покрива само 9% от картите, а изборът
    на линия следва сбора монотонно.
    """
    try:
        lh, la = float(lam_h or 0.0), float(lam_a or 0.0)
    except (TypeError, ValueError):
        return ""
    if lh <= 0 or la <= 0:
        return ""
    mx = score_matrix(lh, la, rho=0.0)
    for line in HOCK_TOTAL_LINES:
        p_over = _hock_p_over(mx, line)
        if p_over >= TOTAL_MIN:
            return "Над " + ("%.1f" % line) + " гола: <b>" + pct(p_over) + "</b>"
        if (1.0 - p_over) >= TOTAL_MIN:
            return "Под " + ("%.1f" % line) + " гола: <b>" + pct(1.0 - p_over) + "</b>"
    return ""


def set_prob_from_match(p_match, best_of=3):
    """Обратната сметка: от вероятността за МАЧА към вероятността за ЕДИН СЕТ.

    Тенис-моделът дава само кой печели мача. Но при мач до 2 спечелени сета
    важи P(мач) = s^2 * (3 - 2s), където s е вероятността да вземеш един сет.
    Функцията е строго растяща, затова я обръщаме с деление наполовина —
    двадесет и пет стъпки стигат за четвърти знак. Никакво допускане, само
    аритметика.
    """
    p = clampf(float(p_match), 0.5, 0.999)     # смятаме за фаворита
    lo, hi = 0.5, 0.999
    for _ in range(25):
        mid = (lo + hi) / 2.0
        if best_of == 3:
            got = mid * mid * (3.0 - 2.0 * mid)
        else:                                  # до 3 спечелени сета
            q = 1.0 - mid
            got = mid ** 3 * (1.0 + 3.0 * q + 6.0 * q * q)
        if got < p:
            lo = mid
        else:
            hi = mid
    return (lo + hi) / 2.0


def tennis_sets_line(p_match, best_of=3):
    """Над/Под сета — с линия, която ПАСВА на формата на мача.

    ТУК ИЗЛИЗАШЕ ФИЗИЧЕСКИ НЕВЪЗМОЖЕН РЕД (намерено и оправено 04.08.2026).
    Функцията беше закована на „мач до два спечелени сета" и печаташе
    „Над/Под 2.5 сета" за ВСЕКИ тенис мач — включително за мачовете до ТРИ
    спечелени сета. А там най-малкият възможен брой сетове е 3, тоест
    „Под 2.5 сета" не е грешна оценка, а твърдение, което НЕ МОЖЕ да се сбъдне.
    Загуба, обявена предварително.

    Форматът вече беше известен на модела (extra.best_of), но не стигаше дотук.

    ЛИНИЯТА Е СТЪЛБА, както при хокея: при мач до три спечелени опитваме първо
    3.5 („ще има ли четвърти сет"), после 4.5 („ще има ли пети"). При мач до два
    спечелени има само едно смислено място — 2.5.
    """
    bo5 = int(best_of or 3) >= 5
    to_win = 3 if bo5 else 2
    s = set_prob_from_match(p_match, 5 if bo5 else 3)
    dist = bo_distribution(s, to_win=to_win)
    # bo_distribution дава разпределението за фаворита; огледалото е за другия.
    ogledalo = [(j, i, p) for (i, j, p) in dist]
    linii = (3.5, 4.5) if bo5 else (2.5,)
    for line in linii:
        p_over = sets_p_over([dist, ogledalo], line)
        if p_over is None:
            continue
        if p_over >= TOTAL_MIN:
            return "Над " + ("%.1f" % line) + " сета: <b>" + pct(p_over) + "</b>"
        if (1.0 - p_over) >= TOTAL_MIN:
            return ("Под " + ("%.1f" % line) + " сета: <b>"
                    + pct(1.0 - p_over) + "</b>")
    return ""


def sets_p_over(dists, line_sets):
    """P(сетовете са повече от линията) от разпределението. None при празно.

    Изнесено от sets_total_line, за да могат два реда да ползват ЕДНА сметка
    вместо да си я преписват — преписаният цикъл е два кода, които утре ще се
    разминат.
    """
    p_over = 0.0
    total = 0.0
    for dist in dists:
        for row in (dist or []):
            try:
                i, j, p = int(row[0]), int(row[1]), float(row[2])
            except Exception:                 # noqa: BLE001
                continue
            total += p
            if (i + j) > line_sets:
                p_over += p
    if total <= 0:
        return None
    return p_over / total                     # нормираме, ако сборът не е точно 1


# Таван на реда за пети сет. Над него числото повтаря КЛАМПА на модела
# (VOL_P_MIN/VOL_P_MAX), а не мери конкретния мач: измерено на живо — всичките
# 110 от 400 истински двойки, при които p_rally опира в границата, дават едно и
# също 97%. Точно капанът „ред, който изглежда като мярка, а е закована стойност".
VOL5_CAP = 0.97


def fifth_set_line(dists):
    """Ще стигне ли мачът до пети сет — от сетовото разпределение.

    ЕДНОПОСОЧЕН НАРОЧНО. Клонът „ДА" е ДОКАЗАНО недостижим: максимумът на
    P(пети сет) е 0.375 (обходени 20001 стойности на p_rally от 0.30 до 0.70),
    а прагът за излизане е 0.57. Тоест „Пети сет: ДА/НЕ" щеше да е фалшив избор —
    човек би чакал някога да види „ДА", а то математически не може да се случи.
    Затова редът казва само това, което наистина мери.

    Числото ОБАЧЕ не е константа: върху 400 истински двойки отбори (FIVB, 7694
    изиграни мача) излизат 35 различни закръглени стойности между 63% и 97%,
    като най-голямата купчина е само 13% от случаите.

    Волейболът е пръв до 3 спечелени сета, затова „без пети сет" значи точно
    „мачът свършва 3:0, 3:1 или огледалното" — тоест до 4 сета.
    """
    p5 = sets_p_over(dists, 4.5)
    if p5 is None:
        return ""
    p_bez = 1.0 - p5
    if p_bez < TOTAL_MIN or p_bez > VOL5_CAP:
        return ""
    return "Мачът свършва до 4 сета: <b>" + pct(p_bez) + "</b>"


def sets_total_line(dists, line_sets):
    """Над/Под N.5 сета — направо от разпределението на сетовете.

    Тук НЯМА никакво допускане: моделът вече е сметнал вероятността на всеки
    точен резултат по сетове (3:0, 3:1, 3:2 и огледалните). Просто събираме
    тези, при които сетовете са повече от линията. Затова този ред е по-твърд
    от точковия — той е точна сметка, не приближение.
    """
    p_over = sets_p_over(dists, line_sets)
    if p_over is None:
        return ""
    if p_over >= TOTAL_MIN:
        return ("Над " + ("%.1f" % line_sets) + " сета: <b>" + pct(p_over) + "</b>")
    if (1.0 - p_over) >= TOTAL_MIN:
        return ("Под " + ("%.1f" % line_sets) + " сета: <b>" + pct(1.0 - p_over) + "</b>")
    return ""


def analyse(fx, ctx):
    """Връща (анализ, причина). Кратък изход: избор, вероятност, две причини."""
    now = ctx["now"]
    b = fx["bucket"]
    need = MIN_PER_SIDE.get(b, 4)
    hr = ar = []
    if need > 0:
        hr, ar = history_for(fx, "home"), history_for(fx, "away")
        if len(hr) < need or len(ar) < need:
            return None, ("няма история (" + str(len(hr)) + " и " + str(len(ar))
                          + " мача, трябват по " + str(need) + ")")

    home, away = esc(fx["home"]), esc(fx["away"])
    # second = кратката добавка на спорта (очакван резултат / най-вероятен сет)
    # third  = ТОТАЛЪТ: над/под голове, точки или сетове. Излиза само когато
    #          едната страна е поне 57% — иначе е шум и се премълчава.
    second, third, why = "", "", []
    # 🔴 ЧИСЛАТА ЗА СБОРА ОЦЕЛЯВАТ СЛЕД analyse (19.08.2026). Дотук моделът
    # `m` умираше вътре във функцията и навън излизаше само готов ТЕКСТ —
    # затова вторият пазар (над/под НА ЛИНИЯТА НА ПАЗАРА) беше невъзможен:
    # линията се научава по-късно, а дотогава нямаше с какво да се смята.
    tot = None

    if b == "football":
        m = model_football(hr, ar, ctx["lvl"], now)
        if not m:
            return None, "няма история"
        p1, px, p2 = m["p_home"], m["p_draw"], m["p_away"]
        # Фиш-език: 1 / Х / 2 / 1Х / Х2. Никакво „не губи" — пише се „или равен".
        pick, p, baza = pick_1x2(p1, px, p2, fx["home"], fx["away"])
        strength = strength_1x2(p, baza)
        # Ред Над/Под 2.5 гола направо от головата матрица, само при >= 57%.
        second = over_under_line(m["p_over"])
        tot = {"vid": "mx", "lam_h": m["lam_h"], "lam_a": m["lam_a"],
               "svii": OU_SHRINK}
        # ГОЛ-ГОЛ — поискан поименно от собственика. Числото p_btts вече се
        # смяташе в matrix_markets и не се четеше от никого.
        third = btts_line(m.get("p_btts"))
        why = [home + ": " + one(m["sh"]["gf"], 2) + " вкарани и " + one(m["sh"]["ga"], 2)
               + " допуснати гола за мач (" + str(m["sh"]["n"]) + " мача)",
               away + ": " + one(m["sa"]["gf"], 2) + " вкарани и " + one(m["sa"]["ga"], 2)
               + " допуснати гола за мач (" + str(m["sa"]["n"]) + " мача)"]
        n_eff = m["sh"]["w"] + m["sa"]["w"]
        sample = samp(m["sh"]["n"], m["sa"]["n"])

    elif b == "basketball":
        m = model_basketball(hr, ar, fx, now)
        if not m:
            return None, "няма история"
        fav_home = m["p_home"] >= 0.5
        pick = pick_win(fav_home, fx["home"], fx["away"])   # в баскетбола няма Х
        p = m["p_home"] if fav_home else m["p_away"]
        strength = strength_binary(m["p_home"])
        second = ("Очакван резултат: ~" + str(int(round(m["exp_h"])))
                  + ":" + str(int(round(m["exp_a"]))))
        third = points_total_line(m.get("total"),
                                  (fx.get("extra") or {}).get("sigma"), "точки")
        # Същото отклонение като в points_total_line: сборът се люлее по-широко
        # от разликата, защото двата отбора вдигат и свалят темпото ЗАЕДНО.
        # 🔴 ОТКЛОНЕНИЕТО НА СБОРА Е 1.90 ПЪТИ ЛИГОВОТО, НЕ 1.25 (19.08.2026).
        # Измерено върху 250 изиграни мача от историята на днешните отбори:
        # среден сбор 165.5, ИСТИНСКО отклонение на сбора 19.96 при лигово
        # sigma 10.5 — тоест множител 1.90.
        #   множител 1.25 (както в реда „И още")  най-голяма грешка +8.8 т
        #   множител 1.90 (измереният)            най-голяма грешка +1.6 т
        # Честно: 19.96 е върху смесени двойки, значи вътре е и разликата
        # между отборите — числото е по-скоро ГОРНА граница. По-широко
        # отклонение значи по-предпазлив процент, тоест греши в наша вреда.
        tot = {"vid": "normal", "mean": m.get("total"), "svii": 1.0,
               "sd": max(4.0, float((fx.get("extra") or {}).get("sigma") or 11.5)
                         * BASK_TOTAL_SD)}
        why = [home + ": " + one(m["sh"]["gf"]) + " : " + one(m["sh"]["ga"])
               + " точки за мач (" + str(m["sh"]["n"]) + " мача)",
               away + ": " + one(m["sa"]["gf"]) + " : " + one(m["sa"]["ga"])
               + " точки за мач (" + str(m["sa"]["n"]) + " мача)"]
        n_eff = m["sh"]["w"] + m["sa"]["w"]
        sample = samp(m["sh"]["n"], m["sa"]["n"])

    elif b == "volleyball":
        m = model_volleyball(fx, now)
        if not m:
            return None, "няма история"
        if min(m["n_h"], m["n_a"]) < 6:
            return None, "няма история (" + str(m["n_h"]) + " и " + str(m["n_a"]) + " мача)"
        fav_home = m["p_home"] >= 0.5
        p = m["p_home"] if fav_home else m["p_away"]
        strength = strength_binary(m["p_home"])
        dist = m["dist_h"] if fav_home else m["dist_a"]
        best = max(dist, key=lambda x: x[2])
        # 🔴 ОПРАВЕНО 11.08.2026. Дотук сетовият резултат влизаше В САМАТА
        # прогноза: „1 · победа Корея (3:0) — 92%". Човекът чете „3:0 с 92%",
        # а 92% е вероятността да СПЕЧЕЛИ МАЧА — точното 3:0 е далеч по-рядко
        # (тук 52%). Тоест картата обещаваше нещо, което моделът не твърди, а
        # оценителят и без това отсъждаше само победителя. Числото си остава,
        # но слиза на свой ред, със своята си вероятност.
        pick = pick_win(fav_home, fx["home"], fx["away"])
        # Волейболът е до 3 спечелени сета: „над 3.5" значи мач в 4 или 5 сета.
        third = sets_total_line([m.get("dist_h"), m.get("dist_a")], 3.5)
        # Числото се сверява с обявеното: сборът на разпределението е СУРОВАТА
        # вероятност за победа, а на картата стои свитата. Показваме дела на
        # този резултат ВЪТРЕ в обявеното, иначе двете числа си противоречат.
        _sur = sum(float(x[2]) for x in dist) or 1.0
        second = ("Най-вероятен резултат: " + str(best[0]) + ":" + str(best[1])
                  + " (" + pct(float(best[2]) / _sur * p) + ")")
        if not third:
            # Редът 3.5 мълчи — тогава втората рубрика поема дължината на мача.
            third = fifth_set_line([m.get("dist_h"), m.get("dist_a")])
        rate = m["p_rally"] if fav_home else 1.0 - m["p_rally"]
        kosh = VOL_BUCKET_BG.get(m.get("vb"), m.get("vb"))
        why = [(home if fav_home else away) + " печели " + one(rate * 100.0)
               + "% от разиграванията срещу този съперник",
               "Сила по точки, а не по 3-0/3-1, и само при " + str(kosh)
               + " — мъже, жени и юноши не се смесват"]
        n_eff = min(m["n_h"], m["n_a"])
        if m.get("thin"):
            n_eff = min(n_eff, 9.0)     # тънка кошница = най-много една звезда
        sample = samp(m["n_h"], m["n_a"])

    elif b == "tabletennis":
        # Местните лиги имат СВОЙ модел със своя ширина. Вж. TTLOKAL_SCALE:
        # заемането на WTT ширината тук дава Брайер, ПО-ЛОШ от монета.
        m = (model_tt_lokal(fx, now)
             if str(fx.get("src") or "") == "ttligi"
             else model_tabletennis(fx, now))
        if not m:
            return None, "няма история"
        if not m["ok"]:
            return None, "няма история (под 5 мача за 18 месеца)"
        fav_home = m["p_home"] >= 0.5
        pick = pick_name(fav_home, fx["home"], fx["away"])
        p = m["p_home"] if fav_home else m["p_away"]
        strength = strength_binary(m["p_home"])
        dist = m["dist_h"] if fav_home else m["dist_a"]
        best = max(dist, key=lambda x: x[2])
        second = ("Най-вероятен резултат: <b>" + str(best[0]) + ":" + str(best[1]) + "</b>")
        # Тенисът на маса е до 3 спечелени гейма: „над 4.5" = мач в 6 или 7.
        third = sets_total_line([m.get("dist_h"), m.get("dist_a")], 4.5)
        # 🔴 ПРЕПИСАНО 11.08.2026 след като прочетох картата в стаята.
        # Пишеше „Lily ZHANG: 10-21 за 18 месеца". Човек не знае 10 победи ли
        # са, или 10 мача, или резултат. Сега си го казваме с думи.
        # 🔴 ПРОЗОРЕЦЪТ ИДВА ОТ МОДЕЛА, НЕ Е ЗАКОВАН (02.09.2026).
        # WTT гледа 548 дни и си остава „за година и половина“. Местните
        # лиги гледат 14 и трябва да го КАЖАТ. Един и същ клон, два прозореца.
        _tt_dni = m.get("dni")
        if _tt_dni:
            _tt_kogа = ("за последните " + str(int(_tt_dni)) + " дни")
        else:
            _tt_kogа = "за година и половина"
        why = [home + ": " + pobedi_zagubi(m["a"]["w"], m["a"]["l"]) + " " + _tt_kogа,
               away + ": " + pobedi_zagubi(m["b"]["w"], m["b"]["l"]) + " " + _tt_kogа]
        n_eff = (m["a"]["w"] + m["a"]["l"] + m["b"]["w"] + m["b"]["l"]) / 2.0
        sample = samp(m["a"]["w"] + m["a"]["l"], m["b"]["w"] + m["b"]["l"])

    # 🔴 МАЛКИЯТ ТУР СЕ СЪДИ ПО ДРУГО (19.08.2026). Кошницата е същата
    # („tennis"), защото стаята, оценителят и таванът на звездите са същите —
    # но моделът НЕ може да е същият: на ITF/Challenger ранглиста в източника
    # НЯМА, а model_tennis стъпва точно на нея и би дал 50% на всяка среща.
    # Затова разклонението е по fx["src"], и то ПРЕДИ общия тенис клон.
    elif b == "tennis" and str(fx.get("src") or "") == "itf":
        m = model_tennis_itf(fx)
        if m is None:
            return None, "източникът за малкия тур мълчи"
        if not m["ok"]:
            return None, ("няма история (" + str(m["n_a"]) + " и " + str(m["n_b"])
                          + " мача, трябват по " + str(ITF_MIN_MACHOVE) + ")")
        fav_home = m["p_home"] >= 0.5
        pick = pick_name(fav_home, fx["home"], fx["away"])
        p = m["p_home"] if fav_home else m["p_away"]
        strength = strength_binary(m["p_home"])
        # 🔴 ЛИЧНИТЕ СРЕЩИ СЕ ПОКАЗВАТ, НО НЕ УЧАСТВАТ В СМЕТКАТА.
        # Измерено в itf.py: с тегло 0.1 грешката РАСТЕ (0.1221 срещу 0.1220),
        # с 0.5 става 0.1240 — и е ясно защо: само 21 от 98 мача изобщо имат
        # лични срещи. Тук са ФАКТ на картата, не вход на модела.
        _n = str((fx.get("extra") or {}).get("nastilka") or "")
        if m["h2h_dom"] != m["h2h_gost"]:
            _vodi = home if m["h2h_dom"] > m["h2h_gost"] else away
            second = ("Лични срещи: <b>" + _vodi + "</b> води "
                      + str(max(m["h2h_dom"], m["h2h_gost"])) + ":"
                      + str(min(m["h2h_dom"], m["h2h_gost"])))
        elif m["h2h_dom"]:
            second = ("Лични срещи: <b>" + str(m["h2h_dom"]) + ":"
                      + str(m["h2h_gost"]) + "</b> — поравно")
        else:
            second = ("Настилка: <b>" + esc(_n) + "</b>") if _n else ""
        # ITF и Challenger сингълът е винаги до два спечелени сета.
        third = tennis_sets_line(max(m["p_home"], m["p_away"]), 3)
        why = [home + ": " + pobedi_zagubi(m["a"].get("pobedi"), m["a"].get("zagubi"))
               + " в последните " + str(m["n_a"]) + " мача",
               away + ": " + pobedi_zagubi(m["b"].get("pobedi"), m["b"].get("zagubi"))
               + " в последните " + str(m["n_b"]) + " мача"]
        n_eff = min(ITF_N_EFF_TAVAN, float(m["n_a"] + m["n_b"]))
        sample = samp(m["n_a"], m["n_b"])

    elif b == "tennis":
        m = model_tennis(fx, now)
        if not m["ok"]:
            return None, "няма история (некласиран и без изиграни мачове)"
        fav_home = m["p_home"] >= 0.5
        pick = pick_name(fav_home, fx["home"], fx["away"])
        p = m["p_home"] if fav_home else m["p_away"]
        strength = strength_binary(m["p_home"])
        def _pl(nm, r, f):
            s = nm
            if r.get("rank"):
                s += ": №" + str(r["rank"]) + " в ранглистата"
            else:
                s += ": извън първите 150"
            if (f[0] + f[1]) >= 3:      # 0-1 не е форма, а шум — не го пишем
                s += ", " + pobedi_zagubi(f[0], f[1]) + " в последните седмици"
            return s
        # ФОРМАТЪТ СТИГА ДОТУК. Дотогава редът беше закован на „до два спечелени
        # сета" и в мачовете до три печаташе „Под 2.5 сета" — невъзможно
        # твърдение, защото там минимумът е 3 сета.
        third = tennis_sets_line(max(m["p_home"], m["p_away"]),
                                 (fx.get("extra") or {}).get("best_of") or 3)
        why = [_pl(home, m["ra"], m["fa"]), _pl(away, m["rb"], m["fb"])]
        # Ранглистата е силен ориентир, но е ЕДИН показател, не двайсет мача.
        # Брои се за шест мача на играч, не повече — иначе картата се хвали с
        # „добра увереност" върху три видени мача, което е точно лъжата,
        # която не искаме да продаваме.
        ranked = (1 if m["ra"].get("rank") else 0) + (1 if m["rb"].get("rank") else 0)
        n_eff = min(30.0, m["n_a"] + m["n_b"] + 6.0 * ranked)
        if min(m["n_a"], m["n_b"]) < 6:
            n_eff = min(n_eff, 19.0)    # под 6 видени мача = най-много две звезди
        sample = ("ранглиста и " + str(m["n_a"] + m["n_b"]) + " скорошни мача")

    elif b == "mma":
        m = model_mma(fx, now)
        if not m["ok"]:
            return None, "няма история (под 3 боя в кариерата)"
        fav_home = m["p_home"] >= 0.5
        pick = pick_name(fav_home, fx["home"], fx["away"])
        p = m["p_home"] if fav_home else m["p_away"]
        strength = strength_binary(m["p_home"])
        fin = m["fin_h"] if fav_home else m["fin_a"]
        # Знаменателят е броят победи с ИЗВЕСТЕН начин, не всички победи —
        # инак дробта и текстът щяха да си противоречат.
        wins = m.get("znaem_h") if fav_home else m.get("znaem_a")
        wins = int(wins or 0)
        if fin is not None and fin >= 0.6 and wins >= 4:
            second = ("Печели предсрочно в " + str(int(round(fin * wins))) + " от "
                      + str(wins) + " победи в индекса")
        rh, ra_ = m["rec_h"], m["rec_a"]
        why = [home + ": " + pobedi_zagubi(rh[0], rh[1]) + " в кариерата"
               + boeve_index(m["na"]),
               away + ": " + pobedi_zagubi(ra_[0], ra_[1]) + " в кариерата"
               + boeve_index(m["nb"])]
        n_eff = m["na"] + m["nb"] + 0.4 * (rh[0] + rh[1] + ra_[0] + ra_[1])
        # „0+0 боя в индекса" не значеше нищо за читателя. Ако никой от двамата
        # не е следен от нас, това е ГЛАВНОТО, което трябва да знае.
        _nab = m["na"] + m["nb"]
        sample = (("не сме следили нито един от двамата")
                  if _nab == 0
                  else (mn(_nab, "следен ", "следени ") + str(_nab)
                        + mn(_nab, " техен бой", " техни боя")))

    elif b == "hockey":
        m = model_hockey(fx)
        if not m:
            return None, "няма история"
        fav_home = m["p_home"] >= 0.5
        # Моделът дели равенството от редовното време наполовина (продължения =
        # монета), затова изборът е 1/2 и важи ЗА МАЧА, не за редовното време.
        pick = pick_win(fav_home, fx["home"], fx["away"]) + " (в мача)"
        p = m["p_home"] if fav_home else m["p_away"]
        strength = strength_binary(m["p_home"])
        # Опашката „· над 5.5" беше махната оттук: тя дублираше новия трети ред
        # в 588 от 992 карти. Едно и също число два пъти на една карта.
        second = "Очаквани голове " + one(m["lam_h"]) + " : " + one(m["lam_a"])
        third = hockey_goals_line(m.get("lam_h"), m.get("lam_a"))
        why = [home + " у дома: " + one(m["hgf"], 2) + " вкарани и " + one(m["hga"], 2)
               + " допуснати гола за мач",
               away + " на гости: " + one(m["agf"], 2) + " вкарани и " + one(m["aga"], 2)
               + " допуснати; равен няма, продълженията са близо до монета"]
        n_eff = m["gp_h"] + m["gp_a"]
        sample = samp(m["gp_h"], m["gp_a"])

    elif b == "rugby":
        # 🏉 СЪЩИЯТ МОДЕЛ като американския футбол — точки за и против, два
        # изхода — но с РЪГБИ константи. σ идва през `extra.sigma` (21.85,
        # измерено на 639 мача), което `model_amfootball` вече чете.
        #
        # 🔴 ТОЗИ КЛОН НЕ ВРЪЩА СВОЙ РЕЧНИК, И ТОВА Е ВАЖНО. Първата ми
        # версия връщаше — и изгуби `"fx"` и `"bucket"`, които общият изход
        # долу слага. `ima_pazar` чете кофата, видя празно и отряза
        # ВСИЧКИТЕ осем ръгби кандидата с „без пазар при букмейкър: 8 (? 8)",
        # докато цените им бяха налични (2.01, 1.40, 1.45, 1.20). Знакът „?"
        # в отчета БЕШЕ доказателството. Клонът пълни променливи и пада
        # надолу, точно като останалите десет спорта.
        m = model_amfootball(hr, ar, fx, now)
        if not m:
            return None, "няма история"
        fav_home = m["p_home"] >= 0.5
        pick = pick_win(fav_home, fx["home"], fx["away"])   # равен няма
        p = m["p_home"] if fav_home else m["p_away"]
        strength = strength_binary(m["p_home"])
        second = ("Очакван резултат: ~" + str(int(round(m["exp_h"])))
                  + ":" + str(int(round(m["exp_a"]))))
        third = points_total_line(m.get("total"), m.get("sigma"), "точки")
        why = [home + ": " + one(m["sh"]["gf"]) + " : " + one(m["sh"]["ga"])
               + " точки за мач (" + str(m["sh"]["n"]) + " мача)",
               away + ": " + one(m["sa"]["gf"]) + " : " + one(m["sa"]["ga"])
               + " точки за мач (" + str(m["sa"]["n"]) + " мача)"]
        n_eff = min(m["sh"]["w"], m["sa"]["w"])
        sample = "точки за и против"
        tot = {"line": None, "over": None, "total": m.get("total")}

    elif b == "amfootball":
        m = model_amfootball(hr, ar, fx, now)
        if not m:
            return None, "няма история"
        fav_home = m["p_home"] >= 0.5
        pick = pick_win(fav_home, fx["home"], fx["away"])   # равен няма
        p = m["p_home"] if fav_home else m["p_away"]
        strength = strength_binary(m["p_home"])
        second = ("Очакван резултат: ~" + str(int(round(m["exp_h"])))
                  + ":" + str(int(round(m["exp_a"]))))
        third = points_total_line(m.get("total"), m.get("sigma"), "точки")
        why = [home + ": " + one(m["sh"]["gf"]) + " : " + one(m["sh"]["ga"])
               + " точки за мач (" + str(m["sh"]["n"]) + " мача)",
               away + ": " + one(m["sa"]["gf"]) + " : " + one(m["sa"]["ga"])
               + " точки за мач (" + str(m["sa"]["n"]) + " мача)"]
        n_eff = m["sh"]["w"] + m["sa"]["w"]
        sample = samp(m["sh"]["n"], m["sa"]["n"])

    elif b == "baseball":
        m = model_baseball(hr, ar, now)
        if not m:
            return None, "няма история"
        fav_home = m["p_home"] >= 0.5
        pick = pick_name(fav_home, fx["home"], fx["away"])
        p = m["p_home"] if fav_home else m["p_away"]
        strength = strength_binary(m["p_home"])
        second = "Очаквани рънове " + one(m["exp_h"]) + " : " + one(m["exp_a"])
        tot = {"vid": "poisson", "lam": m["exp_h"] + m["exp_a"],
               "disp": MLB_DISP, "svii": 1.0}
        # 🔴 ДВЕ ПОПРАВКИ НА ЕДНО МЯСТО (11.08.2026):
        #
        # 1. В „рънa“ последната буква беше ЛАТИНСКО a (U+0061) в българска
        #    дума. Не се вижда с око, но чупи всяко търсене и всяка проверка
        #    по текста. Същият знак стоеше на три места в този файл.
        #
        # 2. Шаблонът „X : Y“ значеше ДВЕ РАЗЛИЧНИ НЕЩА на една и съща карта:
        #    два реда по-горе стои „Очаквани рънове 5.0 : 4.2“ (прогноза за
        #    ТОЗИ мач), а тук „5.1 : 4.3“ беше среден вкаран : среден допуснат
        #    за сезона. Читателят вижда един и същ вид число два пъти и няма
        #    как да разбере кое какво е. Сега числата си носят думите —
        #    точно както вече е при футбола и хокея.
        why = [home + ": " + one(m["sh"]["gf"]) + " вкарани и "
               + one(m["sh"]["ga"]) + " допуснати ръна за мач ("
               + str(m["sh"]["n"]) + " мача)",
               away + ": " + one(m["sa"]["gf"]) + " вкарани и "
               + one(m["sa"]["ga"]) + " допуснати ръна за мач ("
               + str(m["sa"]["n"]) + " мача)"]
        n_eff = m["sh"]["w"] + m["sa"]["w"]
        sample = samp(m["sh"]["n"], m["sa"]["n"])

    elif b == "boxing":
        _e = fx.get("extra") or {}
        pd, pg = _e.get("p_dom"), _e.get("p_gost")
        cd, cg = _e.get("cena_dom"), _e.get("cena_gost")
        if pd is None or pg is None or cd is None or cg is None:
            return None, "няма цена — бокс без цена е бокс без число"
        fav_home = pd >= 0.5
        pick = pick_name(fav_home, fx["home"], fx["away"])
        p = pd if fav_home else pg
        strength = strength_binary(pd)
        # 🔴 ЧИСЛОТО Е НА ПАЗАРА, НЕ НАШЕ — И ТОВА СЕ ЗНАЕ ПРЕДВАРИТЕЛНО.
        # Безплатен източник за боксова история НЯМА: проверено от автора
        # на boks.py на 25.08.2026 — ESPN дава 404/400 на пет адреса, а
        # TheSportsDB знае, че мачът съществува, но два дни след боя пише
        # strStatus „NS" и intHomeScore null. Значи модел няма, значи
        # единственото честно число е свитата пазарна вероятност (маржът
        # при бокса е измерен: 4.4%, медиана 1.0439 върху 22 мача).
        # СЛЕДСТВИЕТО, КОЕТО ДА СЕ ЗНАЕ: CLV за тези карти е нула ПО
        # УСТРОЙСТВО — не защото не бием пазара, а защото сме преписали от
        # него. Картата е честна за читателя; тя просто не е доказателство.
        why = [home + ": цена " + one(cd, 2), away + ": цена " + one(cg, 2)]
        # Нула видени мача. grade() без това би дала звезди за
        # категоричност, а категоричността тук е ЧУЖДА. STAR_CAP го
        # заковава и втори път.
        n_eff = 0.0
        sample = "цена на пазара, без история"

    elif b == "esports":
        m = model_esports(fx)
        if not m:
            return None, "няма две цени — без тях числото не е честно"
        fav_home = m["p_home"] >= 0.5
        pick = pick_win(fav_home, fx["home"], fx["away"])
        p = m["p_home"] if fav_home else m["p_away"]
        strength = strength_binary(m["p_home"])
        # ФАКТ, без лекция: какво плаща пазарът. Обяснението защо го плаща
        # няма място на картата.
        why = [home + ": цена " + one(m["cena_dom"], 2) + " · "
               + away + ": цена " + one(m["cena_gost"], 2)]
        # 🔴 НУЛА, А НЕ ИЗМИСЛЕНО ЧИСЛО. n_eff е РАЗМЕРЪТ НА ИЗВАДКАТА, а
        # тук извадка нямаме. grade() при n_eff < 10 дава една звезда —
        # точно това е честният отговор.
        n_eff = 0.0
        # 🔴 НЕ „без дела на БУКМЕЙКЪРА" (поправено 25.08.2026).
        # Тази дума е в BANNED_TOKENS, а sample СЕ ПЕЧАТА на картата
        # (реда 📚). Пуснато и видяно: banned_word върна „букмейкър",
        # post_predict върна False — тоест ВСЯКА еспорт карта се
        # отказваше на единствения изход, тихо и без нито едно червено.
        # Смисълът се пази дословно: маржът е махнат. Само думата е друга.
        sample = "цената на пазара, без надценката"

    else:
        return None, "непознат спорт"

    # ПРАГЪТ „няма превес" Е МАХНАТ КАТО ОТКАЗ.
    # По-рано срещата с 51% просто изчезваше. Собственикът реши друго: канал
    # за прогнози значи, че излиза и близката среща — с истинското си число.
    # 51% си е 51% и всеки го чете. Прагът остава само като БЕЛЕГ: под него
    # картата получава една звезда, тоест „равностойно".
    if strength < MIN_STRENGTH:
        return {"fx": fx, "bucket": b, "pick": pick, "p": p, "second": second,
                "third": third, "tot": tot,
                "why": ([w for w in why if w][:2]
                        + ["Числата са близки — превесът е малък."])[:2],
                "sample": sample,
                "n_eff": float(n_eff), "strength": float(strength),
                "stars": 1}, ""

    return {"fx": fx, "bucket": b, "pick": pick, "p": p, "second": second,
            "third": third, "tot": tot,
            "why": [w for w in why if w][:2], "sample": sample,
            "n_eff": float(n_eff), "strength": float(strength),
            "stars": grade(b, n_eff, strength)}, ""


# ================================================================= КАРТИТЕ
# Показва ли картата историята на бота за своя спорт. Може да се изключи с
# PREDICT_SHOW_RECORD=0, без да се пипа код.
SHOW_RECORD = (os.environ.get("PREDICT_SHOW_RECORD") or "1").strip() not in ("0", "false", "не")
RECORD_MIN = 10          # под толкова отсъдени казваме, че е рано за извод
_record_cache = {}

SPORT_DUMA = {
    "football": "Футболът", "basketball": "Баскетболът", "volleyball": "Волейболът",
    "tennis": "Тенисът", "tabletennis": "Тенисът на маса", "hockey": "Хокеят",
    "baseball": "Бейзболът", "amfootball": "Американският футбол", "mma": "Бойните",
    "boxing": "Боксът", "esports": "Електронните спортове",
}


def sport_record(bucket, igra=None):
    """Колко е познал ботът в ТОЗИ спорт досега. Празно, ако е рано.

    ДНЕВНИКЪТ САМО СЕ ПИШЕШЕ. `PICKLOG_FILE` се отваряше единствено за да се
    допише номер на фиш — нито един ред не го е ЧЕЛ. Значи 73 публикувани карти
    са минали, без нито една да носи доказателство зад себе си.

    Правилата тук са три, и трите заради честността:
      • само ОТСЪДЕНИ прогнози (hit не е None) — чакащите не се броят;
      • под RECORD_MIN отсъдени числото излиза, но БЕЗ извод — „1 от 1"
        изглежда като 100% и лъже повече, отколкото голата дроб;
      • знаменателят ВИНАГИ се изписва;
      • процент тук НЕ се пише изобщо (25.08.2026) — виж бележката при самия
        ред: картата има ЕДИН процент и той е на прогнозата.

    Всичко е в try/except, защото card() се вика и от самопроверката, а тя е
    портиерът на целия рън. Повреден дневник не бива да спира бота.
    """
    if not SHOW_RECORD or not bucket:
        return ""
    # 🔴 ПАМЕТТА ТРЯБВА ДА ПОМНИ И ИГРАТА. Ключ само по коша значи, че
    # първата еспорт карта за деня заковава реда и следващите две игри
    # получават ЧУЖДАТА сметка — тихо и с вид на успех.
    _kl = (str(bucket), str(igra or ""))
    if _kl in _record_cache:
        return _record_cache[_kl]
    red = ""
    try:
        rows = []
        # 🗄️ 18.08.2026. Оценителят мести приключените стари записи в архив.
        # Рекордът на картата иска ЦЕЛИЯ живот — иначе на всеки 120 дни ще
        # изглежда, че ботът е нов и няма история.
        _arh = (os.environ.get("SCORE_ARHIV_FILE") or "predict_log_arhiv.json").strip()
        for _f in (_arh, PICKLOG_FILE):
            if not os.path.exists(_f):
                continue
            with open(_f, encoding="utf-8-sig") as f:
                _r = json.load(f)
            if isinstance(_r, dict):
                _r = _r.get("rows") or []
            if isinstance(_r, list):
                rows += _r
        if rows or True:
            p = n = 0
            for r in rows:
                if (r or {}).get("bucket") != bucket:
                    continue
                if igra and str((r or {}).get("igra") or "") != str(igra):
                    continue
                if not r.get("scored") or r.get("hit") is None:
                    continue
                n += 1
                if r.get("hit"):
                    p += 1
            ime = SPORT_DUMA.get(bucket, "Спортът")
            if igra:
                # „CS2 досега: ..." е по-вярно от „Електронните спортове
                # досега: ...", когато числото е само на CS2.
                ime = (getattr(ESP, "IGRA_IME", {}) or {}).get(str(igra),
                                                               str(igra))
            # 🔴 ПРОЦЕНТЪТ ПАДА (25.08.2026), ЧИСЛОТО ОСТАВА. На картата вече
            # има ЕДИН процент — този на прогнозата. Втори процент точно под
            # него („62%" и веднага „18%") се чете като втора присъда за същото
            # нещо. Дробта казва същото и не се бие с нищо. Числителят си носи
            # етикета: „2 познати от 11", а не голото „2 от 11".
            # Знакът е 📈, а не 📊: 📊 вече е зает от реда с причината.
            if n >= RECORD_MIN:
                red = ("📈 " + ime + " досега: <b>" + str(p)
                       + mn(p, " позната от ", " познати от ")
                       + str(n) + "</b>")
            elif n > 0:
                red = ("📈 " + ime + " досега: " + str(p)
                       + mn(p, " позната от ", " познати от ")
                       + str(n) + " — още е рано за извод")
    except Exception:                          # noqa: BLE001
        red = ""                               # мълчим, но не чупим картата
    _record_cache[_kl] = red
    return red


# ═══════════════════════════════════ 📐 ОБРАТНОТО НА ПРОЦЕНТА (13.08.2026)
#
# ПОРЪЧКА НА СОБСТВЕНИКА: „искаше ми се и коефициенти да почнеш да даваш,
# поне тези които имаме достъп лайв".
#
# ИЗМЕРЕНО ПЪРВО, ПОСЛЕ ПИСАНО. Живите коефициенти ги има — ESPN ги дава в
# scoreboard за футбола. Но идват така:
#     {"overUnder": 2.5,
#      "link": "https://sportsbook.draftkings.com/gateway?...wpcn=ESPN..."}
# Тоест числото е ОФЕРТА НА БУКМЕЙКЪР, с неговия линк. Точно това реже
# BANNED_TOKENS (bet365, pinnacle, bwin, efbet, winbet, betano, 1xbet,
# „коеф", „букмейкър", „odds") — пазач, сложен, защото българският закон
# забранява рекламата на хазарт. Да ги публикуваме значи да рекламираме
# оператор. Не го правим.
#
# ЗАТОВА ТУК ЧИСЛОТО Е НАШЕ, НЕ ТЯХНО: просто обратното на собствената ни
# вероятност. 56% → 1 към 1.79. Никакъв оператор, никаква оферта, никакъв
# линк — само пренаписване на процента, който така или иначе стои на картата.
#
# Пишем го „1 към 1.79", а не с думата, която пазачът реже: думата носи
# хазартния контекст, а нотацията — само математиката.
KOEF_VKL = (os.environ.get("PREDICT_KOEF") or "1").strip() in ("1", "true", "да")


def obratno_na_procenta(p):
    """56% → „1 към 1.79". Празно при безсмислен вход."""
    try:
        x = float(p)
    except (TypeError, ValueError):
        return ""
    if not (0.01 < x < 1.0):
        return ""
    return "1 към " + ("%.2f" % (1.0 / x))


# Колко причини стои на картата. Две: нашата страна и противникът — за да
# има с какво да се сравни. Трета вече е стена от текст.
PRICHINI_MAKS = max(1, min(4, int(
    (os.environ.get("PREDICT_PRICHINI") or "2").strip() or 2)))


# ═══════════════════════════════════ 💰 ЦЕНАТА НА КАРТАТА (01.09.2026)
#
# ПОРЪЧКА НА СОБСТВЕНИКА, дословно: „ти си игнорирал както обичаш да правиш
# каквото ти говоря за КОЕФИЦИЕНТИ, БУКМЕЙКЪРИ, ЛИНКОВЕ".
#
# ИЗМЕРЕНОТО ПОЛОЖЕНИЕ: цената Я ИМА и НЕ СЕ ПОКАЗВА. dobavi_pazar() пише
# `pazar_cena` върху анализа (ред ~6543) и log_pick я вписва в дневника
# (ред ~1215), но card() не я печата никъде. По думите на собственика: 512 от
# 1082 живи записа (47%) носят цена — espn 244, pinnacle 239, витрина 24.
# ЧЕСТНО: местното копие predict_log.json е от 11.08 (261 записа, НУЛА с цена),
# тоест тези 512 НЕ са проверени в тази сесия, а са приети от собственика.
#
# РАЗЛИКАТА, КОЯТО РЕШАВА ВСИЧКО — и заради която този ред НЕ е нарушение на
# пазача: САМОТО ЧИСЛО не е нито име на оператор, нито линк към него, нито
# подкана. То е ДАННА за мача, точно както „общо 44.5 точки" на реда 🏈.
# Забранени са ИМЕНАТА и ДУМИТЕ (виж BANNED_TOKENS) — не десетичната дроб.
#
# ЗАЩО НЕ Е ГОЛО ЧИСЛО. Собственият docstring на card() записа стандарта, когато
# старият ред „📊 Пазар: 1.95" беше махнат: „Върне ли се, да е с мерна единица и
# с дума какво значи; голо десетично число е чужда оферта под друго име."
# Затова числото идва с единица („пъти") и с дума какво значи.
#
# ЗАЩО НЕ „10 лв. → 18.50 лв.", както собственикът го написа. Три довода,
# всеки проверим:
#   1. НУЛА нова информация. 18.50 = 10 × 1.85. Множителят казва абсолютно
#      същото; сумата само го умножава по десет.
#   2. ЕДИНИЦАТА Е СБЪРКАНА ОТ ДЕН ПЪРВИ. От 01.01.2026 страната е в еврото —
#      „лв." би било остаряло в мига на качването.
#   3. Именуван залог в пари е форматът на ФИША, не на данната. Числото описва
#      мача; сумата описва какво да направи читателят. Пазачът пропуска и
#      двете — разликата е в смисъла, не в буквите.
# Обръща избора: собственикът да каже „искам сумата" — тогава редът става
# „💰 1.85 · 10 € → 18.50 €", смяна на един низ.
#
# 🔴 ДВА КЛЮЧА, НЕ ЕДИН. Числото е данна и стои ВКЛЮЧЕНО. Името на източника е
# решение на СОБСТВЕНИКА заради закона — стои ИЗКЛЮЧЕНО и се пали нарочно.
CENA_VKL = (os.environ.get("PREDICT_POKAZHI_CENA") or "1").strip() in (
    "1", "true", "да")
# 🔴 ДВА ИМЕНА ЗА ЕДНО НЕЩО — ПОПРАВЕНО 01.09.2026.
#
# Одитен агент намери: workflow-ът подава PAZAR_IZTOCHNIK и PAZAR_LINK, а
# живият път (cena_red тук) четеше PREDICT_POKAZHI_IZTOCHNIK, който НЕ Е в
# нито един workflow. Тоест yml обещаваше нещо, което не се случваше:
# сложиш ли PAZAR_IZTOCHNIK=1, читателят пак не виждаше „(ESPN)".
# А ключовете, които действаха, управляваха pazar.red_za_karta_puln —
# функция, която НИКОЙ не вика.
#
# Сега и двете имена водят до едно и също място. PAZAR_* е това, което
# workflow-ът подава; PREDICT_POKAZHI_* остава като второ име, за да не
# се счупи нечия стара настройка.
LINK_VKL = (os.environ.get("PAZAR_LINK")
            or os.environ.get("PREDICT_POKAZHI_LINK") or "1").strip() in (
    "1", "true", "yes", "да")
IZTOCHNIK_VKL = (os.environ.get("PAZAR_IZTOCHNIK")
                 or os.environ.get("PREDICT_POKAZHI_IZTOCHNIK") or "0").strip() in (
    "1", "true", "да")

# Как се казва източникът на човешки. Ключовете са тези, които dobavi_pazar
# пише в `pazar_izt`: "espn", "pinnacle", "vitrina".
#
# 🔴 КАПАНЪТ ОТ ЕСПОРТА, КАЗАН ИЗРИЧНО. Един от трите източника се казва с дума,
# която Е В BANNED_TOKENS. Напечатана, тя не прави червен ред — tg_send мълчаливо
# ОТКАЗВА ЦЯЛАТА КАРТА („zabranena_duma“), точно както на еспорта, който беше тихо
# блокиран цял ден. Затова редът се СВЕРЯВА С ПАЗАЧА, преди да бъде върнат: не
# мине ли, името пада, а числото остава. Включването на ключа не може да убие
# карта — това е изпитано, не обещано.
#
# И ЗАЩО НЯМА ПРИКРИТО ИМЕ ЗА НЕГО: измисленото прозвище е заобикаляне на пазача,
# а не спазване. Или името минава каквото е, или го няма.
IZTOCHNIK_IME = {"espn": "ESPN", "pinnacle": "pinnacle", "vitrina": "витрина"}

# Думата КАКВО ЗНАЧИ числото. Изнесена като константа по две причини, и втората
# е по-важната:
#   1. Формулировката се сменя на едно място.
#   2. 🔴 ВТОРАТА СТЕНА долу става ИЗПИТУЕМА. Преди това мутацията ѝ ОЦЕЛЯВАШЕ:
#      вътрешният пазач вече чистеше реда, значи външният не можеше да сработи
#      никога и беше украса — точно това, срещу което е правилото за мутациите.
#      Сега проверка може да сложи забранена дума ТУК и да види, че редът
#      изчезва, вместо да убие картата.
# 🔴 ПРЕИМЕНУВАНО (02.09.2026). Дотук пишеше «толкова пъти се връща
# вложеното» — вярно описание, но собственикът два пъти каза, че иска
# ДУМАТА: «тука цени няма, има коефициенти». Тя не минаваше през пазача;
# от днес минава (виж бележката в zabraneni.py). Числото е същото — то
# беше там на 48 от 48 карти и преди това.
CENA_OPASHKA = "коеф."

# ➕ ОЩЕ ОТ СЪЩИЯ МАЧ — ИЗКЛЮЧЕН ПО ПОДРАЗБИРАНЕ (01.09.2026).
#
# 🔴 ДВЕ ПОРЪЧКИ НА СОБСТВЕНИКА СИ ПРОТИВОРЕЧАТ И ПО-КЪСНАТА ПЕЧЕЛИ ДНЕС:
#   по-рано: „гол-гол" — поименно поискано (виж ред ~5301)
#   25.08:   „картите са много неясни, не са човешки, дълги и странни"
#   01.09:   „трябва да има ФУЛ ИНФО"
#
# Блокът „И още от същия мач" е махнат на 25.08 и има ЗАКЛЮЧВАЩА проверка
# („блокът И още от същия мач го няма", ~ред 9675) в раздела „МАХНАТОТО
# СИ Е МАХНАТО". Тоест премахването е РЕШЕНИЕ, не пропуск.
#
# НО данните се смятат и се хвърлят: полетата `second` и `third` се пълнят
# на ОСЕМ места (гол-гол, над/под голове, очакван резултат, тотал точки,
# тотал сетове, пети сет, най-вероятен резултат) и card() не ги чете —
# нула читатели в целия проект.
#
# Затова: ключ, ИЗКЛЮЧЕН по подразбиране. Днес нищо не се променя и
# заключващите проверки минават. Собственикът го пуска с една дума:
#     PREDICT_OSHTE=1
# Цената, която плаща: картата расте с ЕДИН ред и получава втори процент.
OSHTE_VKL = (os.environ.get("PREDICT_OSHTE") or "0").strip() in (
    "1", "true", "yes", "да")


def cena_red(an):
    """„💰 1.85 · коеф.“ или „“ при липса на цена.

    Празен низ значи РЕДЪТ НЕ СЕ ПЕЧАТА. Тире, черта или „няма“ биха били
    по-лоши от липсата: празно поле се чете като счупена карта.
    """
    if not CENA_VKL:
        return ""
    try:
        c = float(an.get("pazar_cena"))
    except (TypeError, ValueError):
        return ""
    # Десетичната цена е строго над 1.00 по устройство. Всичко друго е боклук
    # от чужд отговор и няма право да стигне до читателя.
    if not (1.0 < c < 1000.0):
        return ""
    red = "💰 <b>" + ("%.2f" % c) + "</b> · " + CENA_OPASHKA
    # 🔗 АДРЕСЪТ НА САМИЯ МАЧ (01.09.2026, по изрично решение на собственика:
    # „да пускай цените на картите и линкове давай на макс").
    #
    # 🔴 ДОТУК pazar.link_kam_macha БЕШЕ МЪРТЪВ КОД: построен, изпитан с осем
    # проверки, доказан на живо (истински номер → 200, измислен → 404) — и
    # НИКОЙ НЕ ГО ВИКАШЕ. Намерено от оборващ агент. Пети такъв случай в този
    # проект; затова всяка нова връзка се доказва с ЖИВО пускане, не с тест.
    #
    # Адресът се лепи НАКРАЯ на СЪЩИЯ ред, а не на нов: собственикът се е
    # оплаквал, че картите са „дълги и странни".
    #
    # Има го само за футбол, бейзбол и баскетбол през ESPN — 244 от 1082
    # карти. Pinnacle адресите връщат едни и същи 14258 байта за истински
    # номер и за безсмислица, тоест не са доказуеми, и link_kam_macha дава
    # "" за тях НАРОЧНО.
    # 🔴 ПИТА КЛЮЧА (поправено 01.09.2026). Дотук линкът излизаше и при
    # PAZAR_LINK=0 — тоест „пътят назад", записан в workflow-а, беше ЛЪЖА.
    # Правило 3 от протокола: изход, не надежда. Проверено с мутация.
    if PZ is not None and LINK_VKL:
        try:
            _adr = PZ.link_kam_macha(an)
        except Exception:                                    # noqa: BLE001
            _adr = ""
        # 🔗 РЕЗЕРВА: НОМЕРЪТ НА САМАТА СРЕЩА (01.09.2026).
        #
        # `link_kam_macha` иска ЦЕНАТА да е дошла от ESPN. Но номерът на мача
        # при ESPN идва със СРЕЩАТА, не с цената — стои в fx["extra"]["ev_id"]
        # още от събирането. Тоест карта, чиято цена е от Pinnacle, изхвърляше
        # адрес, който сме държали в ръцете си.
        #
        # ИЗМЕРЕНО В ЖИВИЯ ДНЕВНИК: адрес имат 247 от 1105 карти (22%), и то
        # само тези с цена от ESPN. Още 253 карти носят pinnacle-цена; за тях
        # адресът се губеше напразно.
        #
        # ПРОВЕРЕНО ЖИВО — 12 адреса, построени точно по този начин: 12 от 12
        # върнаха HTTP 200 И имената на двата отбора се намират в страницата.
        # Нула сгрешени. Сгрешен адрес е по-лош от липсващ, затова мерих и
        # имената, не само кода.
        if not _adr:
            _ex = ((an.get("fx") or {}).get("extra")) or {}
            _ev = str(_ex.get("ev_id") or "").strip()
            _sp = str(_ex.get("sport_path") or "").strip().lower()
            _lg = str(_ex.get("slug") or "").strip().lower()
            if _ev.isdigit() and len(_ev) <= 12:
                # Същите два клона като в pazar.link_kam_macha: футболът ползва
                # думата „match" и пътя soccer, другите — „game" и пътя на ЛИГАТА.
                if _sp == "soccer":
                    _adr = "https://www.espn.com/soccer/match/_/gameId/" + _ev
                elif _lg and _lg.replace("-", "").replace(".", "").isalnum():
                    _adr = ("https://www.espn.com/" + _lg
                            + "/game/_/gameId/" + _ev)
        if _adr:
            _kand = red + " · " + _adr
            if banned_word(_kand) is None:
                red = _kand
    if IZTOCHNIK_VKL:
        ime = IZTOCHNIK_IME.get(str(an.get("pazar_izt") or "").strip().lower(), "")
        if ime:
            kandidat = red + " · " + esc(ime)
            if banned_word(kandidat) is None:
                red = kandidat
    # Последната дума е на пазача, не моя. Мръсен ред → нищо, вместо мъртва карта.
    # 🔴 ЧИСЛОТО ОЦЕЛЯВА, ДУМАТА — НЕ (02.09.2026).
    #
    # Дотук редът падаше ЦЯЛ, ако опашката съдържа забранена дума. Открито
    # живо същия ден: с `GREENPICKS_ZABRANI_KOEF=1` — собствения ни път
    # назад — думата «коеф» се връща в забранените, редът гърми на пазача и
    # КОЕФИЦИЕНТЪТ ИЗЧЕЗВА ОТ ВСЯКА КАРТА. Тоест пътят назад не връщаше
    # стария вид, а трошеше картата. Път назад, който чупи, не е път назад.
    #
    # Сега при мръсна опашка се пробва ГОЛОТО ЧИСЛО. То е ценното; думата е
    # етикет. «💰 <b>1.85</b>» не съдържа нищо забранено и точно това се
    # изпитва долу, в двете посоки.
    if banned_word(red) is None:
        return red
    _golo = "💰 <b>" + ("%.2f" % c) + "</b>"
    return _golo if banned_word(_golo) is None else ""


def card(an, now):
    """Кратка карта. Прогнозата е ГЕРОЯТ — вижда се, без да се чете нищо друго.

    ПРЕПИСАНА 25.08.2026 по дословната поръчка на собственика: „мачовете като ги
    пускаш пак са много неясни, не са човешки и са дълги и странни".
    Измерено преди преписването върху жива футболна карта: 16 реда / 484 знака.

    КАКВО ОТПАДА И КАКВО ГУБИ ЧИТАТЕЛЯТ (казано, не премълчано):

      • 📐 „1 към 1.61 — обратното на процента" — това е 1/p, тоест същият
        процент, написан втори път с други знаци. Читателят не губи информация.
        obratno_na_procenta() остава жива и изпитана — само вече не се печата.
      • 📊 „Пазар: 1.95" — тук загубата е истинска: това беше ЕДИНСТВЕНОТО число
        на картата, което не е наше, тоест външната котва. Цената продължава да
        се вписва в дневника (log_pick → pazar_cena), значи измеримостта не
        страда — страда читателят. Върне ли се, да е с мерна единица и с дума
        какво значи; голо десетично число е чужда оферта под друго име.
      • ➕ „И още от същия мач" — тоталът вече излиза като СВОЯ карта
        (pazaren_total, vid_karta="total"), значи блокът беше второ изписване на
        същото нещо в същия екран. НО когато PAZAREN_TOTAL е изключен или
        пазарът няма линия за този мач, втората прогноза (над/под, очакван
        резултат, най-вероятен сет-резултат) вече не се вижда НИКЪДЕ. Това е
        реална загуба и се знае. В същия блок стоеше и „Настилка: клей" — ФАКТ
        под заглавие за ПРОГНОЗИ; той също си отива.
      • 📋 „Защо точно това" — от двете причини остава ЕДНА. Читателят вече не
        може да сравни двата отбора един срещу друг: вижда числата само на
        страната, която сме посочили. Реална загуба, платена за реда.
      • Думата за дълбочината на данните („богата история") — grade() я смята
        като 0.55·извадка + 0.45·КАТЕГОРИЧНОСТ, тоест картата се хвалеше сама с
        това колко е уверена. Остава суровият брой мачове, който не може да си
        противоречи. Читателят губи готовата оценка колко да вярва на извадката
        и трябва сам да прецени дали 76 мача са много.
      • Цветната точка 🟢🟡🟠🔴 — знак, повторен на всяка карта, се чете като
        рейтинг, точно както звездите на 11.08. P_DUMI НЕ СЕ ПИПА: думата пак
        идва право от процента и пак не може да го излъже. Маха се само глифът,
        и то тук, при градежа — стълбицата остава заключена и изпитана.

    КАКВО НЕ Е МАХНАТО, ВЪПРЕКИ ЧЕ И ТРИТЕ ПРЕДЛОЖЕНИЯ ГО ИСКАХА:

      • „· пазете се, стъпката е тънка" ОСТАВА. Това е единственият ред на
        картата, който казва на читателя ДА НЕ ВЯРВА на картата. Махането му не
        се вижда никъде — затова се маха най-лесно и затова остава.
      • Историята на бота в спорта ОСТАВА, но на ЕДИН ред и БЕЗ процент.
        Оправданието „то е и в обзора" е невярно: sport_record() сумира ЦЕЛИЯ
        живот (дневник + архив), а обзорът брои САМО деня. Махне ли се оттук,
        всеживотното число изчезва отвсякъде. Процентът му пада, за да остане на
        картата ЕДИН измерител: 62% е за този мач, „2 познати от 11" е сметката
        на бота — два процента един под друг се четат като две присъди за едно.
      • „1 · " пред избора ОСТАВА, макар да изглежда жаргон. Същият низ се пише
        в дневника (log_pick → pick) и същият низ оценителят печата в обзора
        („1 · победа Nashville SC"). Махнат само тук, картата и обзорът щяха да
        назовават една и съща прогноза с различни думи. Смяната е една, за двата
        файла — не половин, в единия.
      • Двойната извадка НЕ се слива в едно число: „76 мача на единия и 74 на
        другия" казва кой от двата е тънкият, „по 75 мача" го крие.
    """
    fx = an["fx"]
    # Турнирът се подрязва по-късо от подразбирането на liga_bg: тук той дели
    # ред с часа, а на телефон дългият ред се пренася и „икономията" изчезва.
    # Стойността по подразбиране (44) НЕ се пипа — тя важи за другите викания.
    lg = liga_bg(fx.get("league"), cap=28)
    koga = esc(fx.get("time") or when_label(fx.get("when"), now))
    total = str(an.get("vid_karta") or "") == "total"

    # РЕД 1: кога и къде. РЕД 2: кой срещу кого — сам, за да се вижда отдалеч.
    glava = [x for x in [("<b>" + koga + "</b>") if koga else "", esc(lg)] if x]
    lines = [(fx["emoji"] + " " + " · ".join(glava)) if glava else fx["emoji"]]
    lines.append("<b>" + esc(fx["home"]) + " " + chr(8212) + " "
                 + esc(fx["away"]) + "</b>")

    # ГЕРОЯТ и присъдата под него. Присъдата идва ПРАВО от процента (p_duma),
    # затова не може да му противоречи. Светофарът се маха ТУК, при печата, и
    # се маха по самата стълбица — добави ли някой ново стъпало с нов цвят,
    # махането го следва само.
    duma = p_duma(an["p"])
    for _prag, _stapalo in P_DUMI:
        _glif = str(_stapalo).split(" ", 1)[0]
        if _glif and not _glif[0].isalpha():
            duma = duma.replace(_glif, "")
    duma = duma.strip()
    # 🔴 ВТОРАТА СТЕНА (26.08.2026). Карта под собствената ни летва не бива
    # да стига дотук изобщо — за това има гейт (`pod_prag_sled_pazar`) и
    # летва при подбора. Но на 25.08, 13:38 такава карта ИЗЛЕЗЕ: моделът
    # даде 45% (резервна сметка, „без история"), мина летвата, после
    # dobavi_pazar замени числото с пазарното 20% и картата отиде в стаята
    # с 🎯 отпред. Днешният файл я спира (`pod_prag_sled_pazar`, ред ~6312,
    # прилаган на редове 7342 и 7403) — тоест кодът в 13:38 се е различавал
    # на поне едно от тези места. Кога точно се е появил гейтът: няма го в
    # копието от 19.08 18:08, има го в копието от 25.08 20:19.
    # Тук картата САМА казва, че е под летвата. Ако някога гейтът пак
    # бъде заобиколен, читателят ще види предупреждението, не само 🎯.
    # Знакът 🎯 остава: същият низ се търси от осем самопроверки и от
    # обзора; смяната му е отделна поръчка, описана в mishena.md.
    #
    # ЕДНО ПРАВИЛО ЗА ЦЕЛИЯ РЕД: и думата, и предупреждението се съдят по
    # ПОКАЗАНОТО число, не по суровото. Инак картата пак би могла да си
    # противоречи — „45% · почти равностойни · под нашата летва" при летва
    # точно 45%. Сливърът, който това пропуска, е широк половин точка
    # (0.445 – 0.4499) и НЕ стига до читателя: гейтът на ред ~7233 съди по
    # суровото p и такава карта изобщо не влиза в кандидатите.
    _letva = dolen_prag(an.get("bucket"))
    _pod = (int(round(float(an.get("p") or 0.0) * 100.0)) / 100.0) < _letva
    lines += ["",
              "🎯 <b>" + esc(an["pick"]) + "</b>",
              "<b>" + pct(an["p"]) + "</b>" + (" · " + duma if duma else "")
              + (" · под нашата летва" if _pod else "")]

    # Тотал-картата казва СА́МА какво е. Без този ред читателят вижда втора карта
    # за същия мач и не разбира защо ботът се повтаря. Думата „пазар" отпадна:
    # тя е от речника на залозите, а редът трябва да го разбере човек, който
    # никога не е залагал.
    if total:
        lines.append("<i>тук гледаме колко общо, не кой печели</i>")

    # ЕДНА причина. Моделът НЕ подрежда причините по сила — затова не се
    # преструвам, че избирам „най-силната": избирам ТОЧНАТА, реда, който говори
    # за страната, която сме посочили. Няма ли такъв, взима се първият.
    # Причината носи етикетите си наготово („Арсенал: 2.10 вкарани и 0.95
    # допуснати гола за мач (76 мача)") — затова числата тук не са голи.
    # 🔴 ВТОРАТА ПРИЧИНА Е ВЪРНАТА (25.08.2026). Съкращаването я махна и
    # собственият ми доклад го записа честно: „читателят вече не може да
    # сравни двата отбора един срещу друг — вижда числата само на страната,
    # която сме посочили." Собственикът поиска обратното същия ден.
    # Затова: ПЪРВАТА е за нашата страна, ВТОРАТА за противника — точно за да
    # има с какво да се сравни. Не две случайни, а двете страни на един кантар.
    prichini = [w for w in (an.get("why") or []) if w]
    izbrani = []
    if prichini:
        _pk = str(an.get("pick") or "")
        _nasha, _druga = "", ""
        if _pk.startswith("1"):
            _nasha, _druga = str(fx.get("home") or ""), str(fx.get("away") or "")
        elif _pk.startswith("2"):
            _nasha, _druga = str(fx.get("away") or ""), str(fx.get("home") or "")
        if _nasha:
            for w in prichini:
                if str(w).startswith(_nasha + ":"):
                    izbrani.append(w)
                    break
        if not izbrani:
            izbrani.append(prichini[0])
        if _druga:
            for w in prichini:
                if w not in izbrani and str(w).startswith(_druga + ":"):
                    izbrani.append(w)
                    break
        if len(izbrani) < PRICHINI_MAKS:
            for w in prichini:
                if w not in izbrani:
                    izbrani.append(w)
                    break
    for _w in izbrani[:PRICHINI_MAKS]:
        lines.append("📊 " + esc(_w))

    # 🔴 ВЪНШНАТА КОТВА Е ВЪРНАТА — НО В ПРОЦЕНТИ, НЕ В КОЕФИЦИЕНТ.
    # Старият ред беше „📊 Пазар: 1.95" и си отиде с право: голо десетично
    # число е чужда оферта под друго име, а думата „коеф" е забранена в целия
    # продукт. Но заедно с него си отиде ЕДИНСТВЕНОТО число на картата, което
    # не е наше — тоест читателят изгуби всяка външна котва.
    #
    # Числото се връща в СЪЩИТЕ единици като нашето, за да е сравнимо с очи:
    # 62% срещу 55%. Това не е оферта, а мнение — и стои редом с нашето, без
    # да се преструва, че е по-важно.
    #
    # Ползва се `pazar_p` — вероятността БЕЗ дела на букмейкъра. Суровото
    # 1/цена надува пазара със 7.4% при футбола, тоест голото деление би
    # показало пазара по-уверен, отколкото е.
    _pp = an.get("pazar_p")
    # 🔴 И РЕДЪТ ОТПАДА ЗА БОКСА И ЕСПОРТА. Там нашето число Е пазарното,
    # тоест този ред щеше да пише „пазарът мисли същото" на ВСЯКА тяхна
    # карта — вярно по конструкция и празно като смисъл. Прескачането на
    # смесването (dobavi_pazar) не стига: този ред се смята отделно.
    if _pp and SG is not None and str(an.get("bucket") or "") not in BEZ_SMESVANE:
        try:
            # 🔴 СРАВНЯВА СЕ НАШАТА СМЕТКА, НЕ ПУБЛИКУВАНОТО ЧИСЛО.
            # Публикуваното вече Е пазарното (теглото е 0.00), тоест
            # сравнението му с пазара винаги дава „мислим същото" — вярно по
            # конструкция и празно като смисъл. Читателят има право да види
            # ДВЕТЕ мнения: какво казва нашата сметка и какво казва пазарът.
            _nash = an.get("p_model")
            if _nash is None:
                _nash = an.get("p")
            _sg, _raz = SG.sglasni_li(_nash, _pp)
            _opashka = ("мислим същото" if _sg
                        else ("ние сме по-смели с %.0f т" % abs(_raz)) if _raz > 0
                        else ("пазарът е по-уверен с %.0f т" % abs(_raz)))
            # Когато двете съвпадат, редът казва точно това. Когато се
            # разминават, казва НАШЕТО число — то вече не е на заглавния ред.
            if _sg:
                lines.append("📐 пазарът мисли същото")
            else:
                lines.append("📐 нашата сметка казваше <b>" + pct(_nash)
                             + "</b> · " + _opashka)
        except Exception:                                    # noqa: BLE001
            pass

    # ➕ ОЩЕ ОТ СЪЩИЯ МАЧ. Виж бележката при OSHTE_VKL: изключено по
    # подразбиране, защото махането е било РЕШЕНИЕ на 25.08. С
    # PREDICT_OSHTE=1 гол-голът и очакваният резултат се връщат — на
    # ЕДИН ред, не на два.
    if OSHTE_VKL:
        _ost = [x for x in (str(an.get("second") or "").strip(),
                            str(an.get("third") or "").strip()) if x]
        if _ost:
            _kand = "➕ " + " · ".join(_ost)
            if len(_kand) <= 150 and banned_word(_kand) is None:
                lines.append(_kand)

    # 💰 ЦЕНАТА. Стои до 📐, защото и двете са мнението на пазара: единият ред
    # го казва в проценти, другият — в пъти. Излиза САМО когато цената я има.
    _cr = cena_red(an)
    if _cr:
        lines.append(_cr)

    # Извадката: суровите числа, без оценъчна дума. Предупреждението за тънката
    # стъпка язди тук, защото говори точно за тези числа.
    _st = [x for x in [esc(an.get("sample") or "")] if x]
    if int(an.get("stars") or 0) <= 1 and float(an.get("n_eff") or 0.0) < 10.0:
        _st.append("пазете се, стъпката е тънка")
    if _st:
        lines.append("📚 " + " · ".join(_st))

    # 🏈 РАЗЛИКАТА ПО ПАЗАРА. ФАКТ, не прогноза — затова до него няма процент,
    # няма звезди и НЕ се отсъжда. Измерено защо съществува: в колежанската
    # лига чистата победа е медиана 74.6% (максимум 98%), тоест „домакинът
    # печели" там е прочитане на таблото, а не твърдение. Медианната разлика,
    # която пазарът иска, е 16.5 точки в NCAA срещу 3.5 в НФЛ — точно това
    # число казва на читателя колко е неравен мачът, а процентът го крие.
    _amh = an.get("amf_h") if not total else None
    if _amh and _amh.get("liniya") is not None:
        try:
            _aln = float(_amh["liniya"])
        except (TypeError, ValueError):
            _aln = 0.0
        if _aln:
            _akoi = fx.get("home") if _aln < 0 else fx.get("away")
            _ared = ("🏈 По пазара: <b>" + esc(_akoi) + " " + chr(8722)
                     + ("%.1f" % abs(_aln)) + "</b> точки")
            try:
                _ared += (" · общо <b>" + ("%.1f" % float(_amh["total"]))
                          + "</b>") if _amh.get("total") is not None else ""
            except (TypeError, ValueError):
                pass
            lines.append(_ared)

    # ⚾ Стартиращите питчъри. Факт, не оценка — затова стои като факт и няма
    # дума какво значи. Показва се само когато знаем И ДВАМАТА: един питчър без
    # другия не казва нищо, а изглежда сякаш казва.
    # 🔴 РЕДЪТ Е ДОМАКИН → ГОСТ, като заглавието на картата (18.08.2026).
    # Първата версия ги нареждаше гост → домакин, защото MLB пише „Toronto at
    # Tampa Bay". Никой тест не гръмна: собственият тест заключваше грешния ред.
    _ex = (fx.get("extra") or {}) if fx else {}
    _ph, _pa = str(_ex.get("pit_home") or ""), str(_ex.get("pit_away") or "")
    if _ph and _pa:
        lines.append("⚾ Хвърлят: " + esc(_ph) + " срещу " + esc(_pa))

    # И накрая — сметката на бота в този спорт. Единственото на картата, което
    # читателят може да провери сам, и единственото, което може да я направи да
    # изглежда зле. Затова остава.
    # 🔴 ИСТОРИЯТА НЕ СЕ ЛЕПИ НА ЧУЖД ПАЗАР (19.08.2026). „Футболът досега: 21 от
    # 42" се брои върху карти 1/Х/2. Сложен под карта за тотал, същият ред би се
    # прочел като история НА ТОТАЛИТЕ — а такава още нямаме нито една отсъдена.
    rec = ("" if total
           else sport_record(an.get("bucket") or (fx.get("bucket") if fx else ""),
                             (fx.get("extra") or {}).get("igra") if fx else None))
    if rec:
        lines.append(rec)
    return NL.join(lines)


def header_card(now, count, seen):
    """Заглавието на деня. Кой е ботът и колко карти идват сега — и нищо друго.

    🔴 „ОТ 14 СРЕЩИ ПОД ЛУПАТА" ОТПАДНА (25.08.2026). Това е отчет за труда на
    бота — точно каквото собственикът забрани на 05.08 с „спри да ми казваш
    какво следихме". Пазачът в самопроверката съществува от същия ден, но той
    търси пет думи („гледахме, следихме, погледнахме, прегледахме,
    разгледахме"), а „под лупата" е шеста дума за същото. Списък от думи не
    пази смисъл — затова заглавието вече не носи и самото ЧИСЛО на прегледаните.
    """
    _ = seen                       # броят прегледани срещи вече не се обявява
    n = int(count or 0)
    kolko = ("Първа карта за деня" if n == 1
             else "Първите <b>" + str(n) + "</b> за деня")
    return (chr(129504) + " <b>БОТА ПРЕДРИЧА</b> · " + date_bg(now) + NL
            + kolko + " — идват още.")


def footer_card(seen, thin, weak, sports):
    """Подписът под последната карта за деня. Обяснява САМО каквото е на картата.

    ТУК СТОЕШЕ ЗАБРАНЕНИЯТ ЕЗИК (махнат 05.08.2026). Пишеше „Гледахме 11 срещи
    от 9 спорта · 2 без история · 3 без превес" — точно това, което собственикът
    забрани с думите „спри да ми казваш какво следихме".

    🔴 ЛЕГЕНДАТА ОБЯСНЯВАШЕ РЕД, КОЙТО ВЕЧЕ ГО НЯМА (25.08.2026). Тя учеше
    читателя на трите думи за дълбочината на данните („малко данни / прилична
    история / богата история"). Тези думи паднаха от картата заедно с оценката
    зад тях, а подписът остана да ги обяснява — същият дефект като на 11.08:
    поправка без близнак е половин поправка. Останаха двата реда, които картата
    НАИСТИНА носи и които нов читател не може да отгатне сам.
    """
    _ = seen, thin, weak, sports
    return NL.join([
        "📘 <b>Как се чете картата</b>",
        "• Процентът е шансът на избора. Думата до него казва само колко е ясен"
        " изборът.",
        "• Редът с 📚 казва върху колко мача стъпваме. Той НЕ оценява прогнозата.",
        "🟢 THE GREEN ROOM",
    ])


def nothing_card(now, seen, thin, weak):
    """Когато няма какво да се посочи — казва го и спира.

    🔴 „ПОГЛЕДНАХМЕ 14 СРЕЩИ: 3 БЕЗ ИСТОРИЯ, 2 БЕЗ ПРЕВЕС" ОТПАДНА
    (25.08.2026). Това е отчет за труда на бота, забранен от собственика на
    05.08. Пазачът срещу тези думи е от същия ден, но беше насочен САМО към
    заглавната карта и подписа — този текст никога не мина през него и затова
    оцеля двайсет дни с „Погледнахме" в първата си дума. Сега през пазача
    минават и трите служебни текста.
    """
    _ = seen, thin, weak
    return NL.join([
        chr(129504) + " <b>БОТА ПРЕДРИЧА</b> · " + date_bg(now),
        "",
        "<b>Днес няма прогнози.</b>",
        "Числата не дадоха превес никъде. Утре пак.",
    ])


# ================================================================= ПОДБОР
def collect_all(now):
    ymd = now.strftime("%Y%m%d")
    ymd_dash = now.strftime("%Y-%m-%d")

    # 🔴 ДИАПАЗОН ЗА СПОРТОВЕТЕ, КОИТО НЕ ИГРАЯТ ВСЕКИ ДЕН (01.09.2026).
    #
    # ВТОРАТА ЗАПУШАЛКА НА АМЕР. ФУТБОЛА, намерена след първата. Дотук
    # ESPN се питаше за ЕДИН ден — днешния. Другите спортове работят,
    # защото играят всеки ден; колежанският футбол играе в СЪБОТА и на
    # 01.09 отговорът беше НУЛА мача.
    #
    # Измерено живо, същият адрес:
    #     ?dates=20260901              →   0 мача
    #     ?dates=20260906              →   3 мача
    #     ?dates=20260901-20260906     →  90 мача
    #     ?dates=20260901-20260913     → 177 мача
    #
    # Тоест спортът беше недостижим на ДВЕ места наведнъж: хоризонтът го
    # режеше и въпросът изобщо не стигаше до дните, в които има мачове.
    # Точно затова се търси КРЪСТОСВАНЕТО, а не отделните числа.
    #
    # Диапазонът важи САМО за спортовете със свой хоризонт. За всички
    # останали въпросът си остава един ден — по-широк прозорец значи
    # повече заявки и по-стари цени без никаква полза.
    buckets = {}
    for b in ACTIVE_SPORTS:
        rows = []
        _zp, _pr, _gr = _http_used[0], len(_http_why), ""
        try:
            if b == "football":
                rows = football_fixtures(now, ymd)
            elif b == "basketball":
                rows = basketball_fixtures(now, ymd)
            elif b == "tennis":
                rows = tennis_fixtures(now, ymd)
                # 🔴 МАЛКИЯТ ТУР СЕ ДОБАВЯ, НЕ ЗАМЕСТВА (19.08.2026).
                # Редът тук е без значение — три реда по-долу кошницата се
                # подрежда по −weight, а ITF/Challenger носят 2 и 3 срещу
                # 4..9 на главния тур. Тоест главният винаги е отгоре.
                rows = rows + itf_fixtures(now)
            elif b == "hockey":
                # 🏒 МНОГОДНЕВНИЯТ ВЪПРОС (02.09.2026). hockey_fixtures пита
                # за ЕДИН ДЕН, а HORIZONT_PO_SPORT["hockey"] е 120 ч — лостът
                # беше мъртъв и бележката на ред 617 го признаваше.
                # HOK.kosnica пита api-web /schedule, който носи СЕДЕМ дни за
                # ЕДНА заявка, тоест ширината е БЕЗПЛАТНА. Измерено живо
                # 02.09.2026 за 29.09: 43 срещи с една заявка, от тях 34
                # оцеляват в прозореца, срещу 5 по стария път.
                # ПЪТ НАЗАД: махни тези редове — hockey_fixtures е непокътнат.
                # Или PREDICT_HORIZON_HOK=30 свива прозореца до днешния.
                _hr = HOK.kosnica(now.timestamp(), ime=bg_name) if HOK else None
                _nhl_mylchi = False
                if _hr is None:
                    rows = hockey_fixtures(now, ymd_dash)
                elif _hr is HOK.NEPITAN:
                    _nhl_mylchi = True
                    rows = []
                else:
                    rows = _hr

                # 🏒 И ЕВРОПА (02.09.2026). Слива се, НЕ заменя: НХЛ и
                # европейските лиги са различни мачове, не различни изгледи
                # към едни и същи. Измерено живо в деня на вплитането: 36
                # срещи за 168 ч (24 Шампионска лига + 12 СМ Лига), от които
                # 28 имат и двата отбора в таблицата.
                _evr = None
                if EVH is not None:
                    try:
                        _evr = EVH.srechti(now, ime=bg_name)
                    except Exception as _e_evh:              # noqa: BLE001
                        print("   ⚠ европейски хокей: " + str(_e_evh)[:70])
                        _evr = None
                if _evr is not None and _evr is not EVH.NEPITAN:
                    if _evr:
                        print("   🏒 Европа: %d срещи (%s)"
                              % (len(_evr), ", ".join(sorted(
                                  {r["league"] for r in _evr}))[:60]))
                    rows = list(rows) + list(_evr)
                elif _evr is not None:
                    print("   ⚠ европейски хокей: НЕ МОЖАХ ДА ПИТАМ.")

                # 🔴 МЪЛЧАНИЕТО СЕ ОБЯВЯВА САМО КОГАТО Е ПЪЛНО. Дотук
                # редът за НХЛ се печаташе винаги при NEPITAN; сега, ако
                # Европа е донесла мачове, „не можах да питам" е подвеждащо —
                # питали сме и сме получили, просто не от НХЛ.
                if _nhl_mylchi and not rows:
                    print("   \u26a0 хокей: НЕ МОЖАХ ДА ПИТАМ (изворът мълчи)"
                          " — това НЕ е «няма мачове».")
                elif _nhl_mylchi:
                    print("   \u26a0 НХЛ мълчи, но Европа отговори — "
                          "картите долу са европейски.")
            elif b == "rugby":
                # 🏉 Измерено живо в деня на вплитането: 45 предстоящи мача в
                # трите играещи лиги (Топ 14 22, НПС 19, тестови 4).
                _rr = RAG.srechti(now, ime=bg_name) if RAG else None
                if _rr is None:
                    rows = []
                elif _rr is RAG.NEPITAN:
                    print("   ⚠ ръгби: НЕ МОЖАХ ДА ПИТАМ (изворът мълчи) — "
                          "това НЕ е «няма мачове».")
                    rows = []
                else:
                    rows = _rr
            elif b == "amfootball":
                rows = amfootball_fixtures(now, ymd_za(now, b))
                # 🔴 ТАВАНЪТ ДЕЙСТВА И ТУК, не само през ACTIVE_SPORTS. Една
                # колежанска събота е 60+ срещи наведнъж (измерено: дъската на
                # ESPN за 30.08.2025 дава 62), а всяка от тях иска история за
                # два отбора. Подредбата е по тегло: НФЛ носи 10, колежанската
                # 5 — тоест НФЛ никога не бива изядена от обема на другата.
                rows.sort(key=lambda fx: -fx.get("weight", 0))
                rows = rows[:AMFUTBOL_MAX]
            elif b == "baseball":
                rows = baseball_fixtures(now, ymd_dash)
                # ⚾ АЗИЯ СЕ ДОБАВЯ, НЕ ЗАМЕСТВА — както малкият тур при
                # тениса. Редът е без значение: кошницата се подрежда по
                # −weight и МЛБ (5) остава над NPB/KBO (4).
                rows = rows + azia_fixtures(now)
            elif b == "mma":
                rows = mma_fixtures(now)
            elif b == "boxing":
                rows = boks_fixtures(now)
            elif b == "esports":
                rows = esport_fixtures(now)
            elif b == "volleyball":
                rows = vol_fixtures(now, ymd_dash)
            elif b == "tabletennis":
                rows = tt_fixtures(now, ymd_dash)
                # 🏓 МЕСТНИТЕ СЕ ДОБАВЯТ, НЕ ЗАМЕСТВАТ — по образеца на
                # малкия тур при тениса и на Азия при бейзбола. WTT остава
                # главният; тези влизат до него и оцеляват, когато той падне.
                rows = rows + ttlokal_fixtures(now)
        except Exception as e:      # noqa: BLE001
            print("   ⚠ " + b + ": " + str(e)[:90])
            _gr = str(e)[:90]
            rows = []
        if not rows and b in ("football", "basketball", "volleyball", "tabletennis"):
            rows = sdb_fixtures(b)
            if rows:
                print("   " + b + ": " + str(len(rows)) + " срещи от резервата TheSportsDB.")
        rows = [r for r in rows
                if not is_placeholder(r.get("home")) and not is_placeholder(r.get("away"))]
        # Пазачът на часа. Осем пускания на ден значи, че в 19:00 списъкът още
        # съдържа мачовете от 13:00 — а прогноза за започнал мач е по-лоша от
        # мълчание. Режем всичко, което тръгва до LEAD_MIN минути.
        n_all = len(rows)
        rows = [r for r in rows if not started(r, now)]
        gone = n_all - len(rows)
        n_near = len(rows)
        rows = [r for r in rows if not too_far(r, now, b)]
        far = n_near - len(rows)
        rows.sort(key=lambda fx: -fx.get("weight", 0))
        buckets[b] = rows
        # ЧЕРНАТА КУТИЯ. Дневникът на GitHub се чете само с админски права, а
        # страницата му не се рендира навсякъде — тоест отвън НЕ СЕ ВИЖДА защо
        # един спорт мълчи. Три спорта не дадоха карта НИТО ВЕДНЪЖ и никой не
        # разбра, защото числото живееше само в един изчезващ дневник.
        # Затова цифрите се записват във файл, който се връща в хранилището.
        DIAG[b] = {"suredi": len(rows), "surovi": n_all,
                   "zapochnali": gone, "daleche": far,
                   "zaqvki": _http_used[0] - _zp,
                   "gr": ([_gr] if _gr else []) + _http_why[_pr:][:4]}
        print("   " + SPORTS[b]["emoji"] + " " + b + ": " + str(len(rows))
              + mn(len(rows), " среща", " срещи")
              + ((" (" + str(gone) + " вече започнали)") if gone else "")
              + ((" (" + str(far) + " далече — чакат)") if far else ""))
    return buckets


# ═══════════════════════════════════════ ПРОГНОЗА ВИНАГИ (резервната стълба)
# РЕШЕНИЕ НА СОБСТВЕНИКА (29.07.2026, казано два пъти и ясно):
#   „Това е спортен канал за прогнози. Пишеш каквото може."
# Затова отказът „няма история — не гадаем" е МАХНАТ като краен изход.
#
# Честността не изчезва, а се мести на две места, които остават:
#   • ПРОЦЕНТЪТ — при празна извадка той е близо до 50 и не се разкрасява
#   • ЗВЕЗДИТЕ — една звезда и изписано на какво стъпва картата
# Читателят вижда и двете и си преценява сам. Това беше и уговорката.
#
# Стълбата отгоре надолу:
#   1. пълен модел (когато има история)          — до три звезди
#   2. частични данни (ранглиста, форма, H2H)    — една звезда
#   3. нищо                                       — предимството на домакина
FALLBACK_HOME = {
    # Колко често печели домакинът/първият в двойката, когато не знаем нищо.
    # Числата са общоприети за съответния спорт, не са измислени в движение.
    "football": 0.45,       # 1X2: равенството яде част от масата
    "basketball": 0.60,
    "volleyball": 0.55,
    "hockey": 0.55,
    "baseball": 0.54,
    "tabletennis": 0.50,    # „домакин" няма — двойката е неутрална
    "tennis": 0.50,
    "mma": 0.50,
}
# Колко често мачът свършва равен, когато не знаем нищо за отборите. Числото
# не е избрано тук — то се чете направо от реда отгоре: щом домакинът взима
# 0.45, а гостът около 0.27, за равенството остава останалото.
FALLBACK_DRAW = 0.28

# Спортовете с ЕДИН човек от страна се пишат само с име („1 · Синер"), а
# отборните — с „победа" пред името. Разликата беше пропусната в резервния
# път и там картите излизаха ГОЛИ, без 1/2 отпред: „Andrey Rublev 50%".
# Оценителят чете точно този код, за да отсъди — без него присъдата увисва
# на съвпадение по име.
# 🥊 Боксът е личен спорт: пише се „1 · Lester Martinez", не „1 · победа
# Lester Martinez". Еспортът НЕ е — там играят отбори.
LICHNI_SPORTOVE = {"tennis", "tabletennis", "mma", "boxing"}


def fallback_analyse(fx, ctx, reason):
    """Карта дори когато моделът е замълчал. Никога не връща None."""
    b = fx.get("bucket") or ""
    home = esc(fx.get("home") or "")
    away = esc(fx.get("away") or "")
    p = float(FALLBACK_HOME.get(b, 0.52))

    # Ако знаем поне тежестта на турнира или подредбата, накланяме мъничко.
    ex = fx.get("extra") or {}
    if ex.get("neutral"):
        p = 0.50 + (p - 0.50) * 0.35      # неутрален терен: предимството пада

    fav_home = p >= 0.50
    if b == "football":
        # ТУК СТОЕШЕ ОБЪРНАТА КАРТА (намерено и оправено 04.08.2026).
        # Старият ред беше: fav_home = p >= 0.50, а за футбола p e 0.45.
        # Значи при НУЛА информация ботът посочваше ГОСТА, и то с „55%" —
        # число, което не е вероятността гостът да спечели, а вероятността
        # гостът ИЛИ равен. Гостът сам е около 27%.
        # В дневника има точно два футболни избора на гост и двата идват
        # оттук: Omonia Nicosia (домакинът спечели 1:0) и Boca Juniors (2:2).
        # И двата загубени.
        # Същият избор както при пълния модел, за да няма два различни езика:
        # под 50% за едната страна значи двоен шанс, не гол победител.
        # FALLBACK_HOME за футбола ВЕЧЕ е вероятност по 1X2 (виж бележката при
        # него), затова се взима както си е. Остатъкът отива при госта.
        px = FALLBACK_DRAW
        p1 = clampf(p, 0.05, 1.0 - px - 0.05)
        p2 = 1.0 - px - p1
        pick, p_show, _ = pick_1x2(p1, px, p2, fx.get("home"), fx.get("away"))
    elif b in LICHNI_SPORTOVE:
        pick = pick_name(fav_home, fx.get("home"), fx.get("away"))
        p_show = max(p, 1.0 - p)
    else:
        pick = pick_win(fav_home, fx.get("home"), fx.get("away"))
        p_show = max(p, 1.0 - p)

    kratko = (reason or "").split("(")[0].strip().rstrip(".")
    why = ["Малко данни за тази среща: " + (kratko or "няма история в източника") + ".",
           "Картата стъпва на предимството на домакина за този спорт."]
    if b in ("tennis", "tabletennis", "mma"):
        why[1] = "Двойката е неутрална — числото е близо до равностойно."

    return {"fx": fx, "bucket": b, "pick": pick, "p": p_show,
            "second": "", "third": "",
            "why": why, "sample": "без история",
            "n_eff": 0.0, "strength": 0.0, "stars": 1}


# ═══════════════════════════════════ 📊 ЦЕНАТА КЪМ АНАЛИЗА (13.08.2026)
#
# Взима се СЛЕД избора, не преди него: пазарът НЕ бива да влияе на решението
# на модела. Ако го питахме преди, щяхме тихо да го препишем — а тогава 70-те
# процента щяха да мерят пазара, не нас.
#
# Заявката е една на мач и само за спортовете, за които ИЗМЕРЕНО има цена
# (бейзбол, баскетбол, футбол). Провал не спира картата — тя просто излиза
# без реда, както преди.
def _pazar_surovo(an):
    """Сърцевината: САМО намирането на цената. Обвивката е dobavi_pazar."""
    if PZ is None or not isinstance(an, dict):
        return an
    fx = an.get("fx") or {}
    ex = fx.get("extra") or {}
    # 🏓 ЦЕНАТА, КОЯТО ВЕЧЕ ДЪРЖИМ (01.09.2026).
    #
    # Срещите от местните лиги идват от Smarkets ЗАЕДНО с цената си —
    # tt_lokal.srechti я слага в extra още при събирането, без нито една
    # допълнителна заявка. А този портиер знаеше само за ESPN и Pinnacle,
    # тоест питаше света за нещо, което е в джоба му.
    #
    # ВИДЯНО В СУХО ПУСКАНЕ, НЕ ПРЕДПОЛОЖЕНО: и седемте срещи паднаха на
    # „без пазар при букмейкър“, докато носеха цени 1.77 / 1.87.
    # Това е ОСМИЯТ случай „построено, но не свързано“ в този проект —
    # и е мой, отпреди половин час.
    #
    # Маржът им е измерен на 0.3% (борса, не букмейкър), тоест тази цена е
    # по-честна от всичко останало, което ботът вижда.
    # 🔴 САМО ЗА МЕСТНИЯ ТЕНИС НА МАСА. Първата ми версия гледаше само
    # „има ли cena_dom в extra“ и връщаше рано — и ПРЕГАЗИ пътя на еспорта,
    # който ползва СЪЩИТЕ полета и има собствена сметка (витрина, pin_mid,
    # ключ „esports_pin“ за затварящата цена). Четири чужди проверки го
    # хванаха веднага. Затова условието пита за КОФАТА и за ИЗТОЧНИКА, а не
    # само за полето: едно и също име на поле не значи един и същ път.
    # 🏓 WTT: ЦЕНАТА СЕ ТЪРСИ, НЕ СЕ ЧАКА (02.09.2026).
    #
    # Местните лиги носят цената със себе си (виж по-долу). WTT — не: тези
    # срещи идват от календара на WTT, а цената им стои при Kambi, под
    # турнир, който `ceni_kambi` дотук изхвърляше. Двете половини бяха
    # поправени заедно; всяка сама по себе си не сменя нищо.
    #
    # Измерено живо в деня на вплитането: 143 WTT срещи, 2 с отворена книга.
    # Kambi отваря пазар малко преди мача — останалите се хващат при
    # следващите пускания, а те са 24 на ден.
    if (TTL is not None and str(an.get("bucket") or "") == "tabletennis"
            and not an.get("pazar_cena")
            and str(fx.get("src") or "") != "ttligi"):
        try:
            _wt_d = str(ex.get("home_en") or fx.get("home") or "")
            _wt_g = str(ex.get("away_en") or fx.get("away") or "")
            _wt_c = TTL.cena(_wt_d, _wt_g, fx.get("league")) if _wt_d and _wt_g else None
        except Exception:                                    # noqa: BLE001
            _wt_c = None
        if isinstance(_wt_c, dict):
            _wt_pd, _wt_pg = _wt_c.get("dom"), _wt_c.get("gost")
            try:
                _wt_pd, _wt_pg = float(_wt_pd), float(_wt_pg)
            except (TypeError, ValueError):
                _wt_pd = _wt_pg = 0.0
            # Десетичната цена е строго над 1.00 по устройство. Всичко друго
            # е боклук от чужд отговор и няма право да стигне до читателя.
            if 1.0 < _wt_pd < 1000.0 and 1.0 < _wt_pg < 1000.0:
                # Чия страна сме взели: „1 · име" е домакинът, „2 · име" —
                # гостът. Същото правило като при местните лиги три реда
                # по-долу; НЕ се измисля второ.
                _wt_nash_dom = not str(an.get("pick") or "").startswith("2")
                an["pazar_cena"] = _wt_pd if _wt_nash_dom else _wt_pg
                an["pazar_cena_drug"] = _wt_pg if _wt_nash_dom else _wt_pd
                an["pazar_izt"] = str(_wt_c.get("izvor") or "kambi")
                an["pazar_sport"] = "tabletennis"
                an["pazar_liga"] = str(_wt_c.get("liga") or "")
                _wt_p = _wt_c.get("p_dom")
                try:
                    _wt_p = float(_wt_p)
                except (TypeError, ValueError):
                    _wt_p = None
                if _wt_p is not None and 0.0 < _wt_p < 1.0:
                    an["pazar_p"] = round(
                        _wt_p if _wt_nash_dom else 1.0 - _wt_p, 4)
                return an

    _sm_d, _sm_g = ex.get("cena_dom"), ex.get("cena_gost")
    _sm_moe = (str(an.get("bucket") or "") == "tabletennis"
               and str(fx.get("src") or "") == "ttligi")
    if _sm_moe and _sm_d and _sm_g and not an.get("pazar_cena"):
        try:
            _sm_d, _sm_g = float(_sm_d), float(_sm_g)
        except (TypeError, ValueError):
            _sm_d = _sm_g = 0.0
        if 1.0 < _sm_d < 1000.0 and 1.0 < _sm_g < 1000.0:
            _sm_nash = str(an.get("pick") or "")
            # Чия страна сме взели: „1 · име“ е домакинът, „2 · име“ — гостът.
            _sm_dom = not _sm_nash.startswith("2")
            an["pazar_cena"] = _sm_d if _sm_dom else _sm_g
            an["pazar_cena_drug"] = _sm_g if _sm_dom else _sm_d
            # 📈 ТУК НЯМА РЕД ЗА ТЕФТЕРА НА ЦЕНИТЕ — И ТОВА Е ИЗМЕРЕНО.
            # Написах го, мутирах го (M16, 02.09.2026) и НУЛА проверки
            # паднаха: този път има само ДВА изхода и ДВЕТЕ цени вече стоят в
            # pazar_cena / pazar_cena_drug, тоест резервният път в
            # zapishi_cena дава СЪЩИТЕ етикети. Ред, който нищо не сменя, е
            # лъжа за читателя. Ако някой ден тук се появи трети изход или
            # pazar_cena_drug спре да се пълни, редът трябва да се върне —
            # заедно с проверката, която доказва, че върши работа.
            an["pazar_izt"] = str(ex.get("cena_izvor") or "smarkets")
            an["pazar_sport"] = "tabletennis"
            _sm_p = ex.get("p_pazar")
            try:
                _sm_p = float(_sm_p)
            except (TypeError, ValueError):
                _sm_p = None
            if _sm_p is not None and 0.0 < _sm_p < 1.0:
                an["pazar_p"] = round(_sm_p if _sm_dom else 1.0 - _sm_p, 4)
            return an
    ev_id, slug = ex.get("ev_id"), ex.get("slug")
    sport = ex.get("sport_path")
    # 🔴 ДВА ПЪТЯ (13.08.2026). Срещите от ESPN носят номер и цената идва
    # направо. Бейзболът обаче идва от statsapi.mlb.com и НЯМА такъв номер —
    # а там са 48 от прогнозите. За него търсим по ИМЕНА в ESPN scoreboard-а
    # за същия ден. Без този втори път най-големият спорт остава без цена.
    if not sport:
        sport = {"baseball": "baseball", "basketball": "basketball",
                 "football": "soccer"}.get(str(an.get("bucket") or ""))
    if not slug:
        slug = {"baseball": "mlb"}.get(str(an.get("bucket") or ""))
    # 🔴 БЕЗ РАНЕН ИЗХОД (18.08.2026). Тук стоеше `return an`, ако ESPN няма
    # адрес за спорта — и заради него тенисът, ММА и тенисът на маса излизаха
    # от функцията ПРЕДИ да се стигне до втория източник. Тоест новият
    # източник беше написан, вързан и НЕДОСТИЖИМ. Видя се само в сухо
    # пускане: четири карти с цена, четирите тенис-карти без.
    dom = gost = raven = None
    # 🔴 ЗАДАЧА 1 (25.08.2026): ПОСТРОЕН ДВИГАТЕЛ, КОЙТО НЕ БЕШЕ ВКЛЮЧЕН.
    # pinnacle.nomer_strana() съществува от 21.08 и никой не я викаше. Измерено
    # в живия дневник (predict_log.json, sha a78efaf1, 737 записа, свален през
    # api.github.com — raw кешира): 73 от 73 записа с pazar_izt="pinnacle" стоят
    # с pazar_ev=null. Тоест тенисът — най-силният ни спорт — няма НИТО ЕДНА
    # затваряща цена, значи нула CLV, а CLV е мярката, която дава отговор за 2
    # дни вместо за 36.
    # Цената: измерена ЖИВО днес с шпионин върху urllib.request.urlopen —
    # nomer_strana след ceni_za прави 0 ДОПЪЛНИТЕЛНИ заявки (същият кеш).
    pin_mid, pin_obarnat = None, False
    # ⚾ АЗИЯ НЕ МИНАВА ПРЕЗ ESPN. Кошницата ѝ е „baseball", тоест два реда
    # по-горе sport/slug станаха „baseball"/„mlb" и функцията щеше да пита
    # американското разписание за „Yomiuri Giants". Отговорът е известен
    # предварително: няма го. Заявката е кеширана и евтина, но питане, за
    # което отговорът се знае, е шум в дневника.
    _sam_si = str(fx.get("src") or "") == "azia"
    try:
        if _sam_si or not (sport and slug):
            pass                          # ESPN няма адрес — минаваме нататък
        elif ev_id:
            dom, gost, raven = PZ.cena_za(sport, slug, ev_id)
        else:
            s = fx_start(fx, datetime.now(SOFIA))
            ymd = (s.astimezone(SOFIA) if s is not None
                   else datetime.now(SOFIA)).strftime("%Y%m%d")
            # 🔴 ЧАСЪТ СЕ ПОДАВА (18.08.2026). Без него серия от три вечери
            # между едни и същи отбори връщаше цената на грешната вечер —
            # измерено, 5 от 15 бейзболни мача, при това маркирани като чисти.
            dom, gost, raven = PZ.cena_po_imena(sport, slug, ymd,
                                                fx.get("home"), fx.get("away"), s)
            # Номерът от СЪЩИЯ кеширан индекс — нула нови заявки. Влиза в
            # дневника, за да вземе оценителят затварящата цена. Затова е
            # критично да е НАШИЯТ мач: сгрешен номер = чужда затваряща цена.
            ev_id = PZ.ev_za_imena(sport, slug, ymd,
                                   fx.get("home"), fx.get("away"), s)
    except Exception:                                        # noqa: BLE001
        dom = gost = raven = None
    izt = "espn" if (dom or gost) else None

    # ═══ МОДУЛЪТ НА СПОРТА ИМА ПРЕВЕС ПРЕД ОБЩИЯ ПЪТ (25.08.2026) ═══
    # Трите блока по-долу стоят ПРЕДИ общия Pinnacle-път нарочно. Общият
    # път свежда третата си стъпка до „едното име се съдържа в другото" и
    # точно тя вече е лепвала ЧУЖДА цена (Bury FC върху карта от МЛС).
    # Тук цената идва от СЪЩИЯ запис, от който е дошла срещата — сверяване
    # по имена изобщо не се прави.

    # ⚾ АЗИАТСКИЯТ БЕЙЗБОЛ НОСИ ЦЕНАТА СЪС СЕБЕ СИ.
    # 🔴 ЧЕСТНО ЗА ЕДНА ЛИПСА: номерът на мача при Pinnacle НЕ излиза от
    # azia.s_ceni, значи тези карти остават без pazar_ev, значи БЕЗ CLV.
    # Не си измислям номер — по-добре липсваща мярка, отколкото чужда
    # затваряща цена, която изглежда наред. Лекът е един ред в azia.py
    # (s_ceni да върне и номера) и е описан в отчета.
    if not (dom or gost) and str(fx.get("src") or "") == "azia":
        _cd, _cg = ex.get("cena_dom"), ex.get("cena_gost")
        if _cd or _cg:
            dom, gost, raven = _cd, _cg, None
            izt = "pinnacle"
            sport = "baseball"

    # 🥊 БОКСЪТ НОСИ И ЦЕНАТА, И НОМЕРА. Номерът влиза в дневника, значи
    # този спорт ИМА затваряща цена от първия ден — „boxing" е в
    # pinnacle.SPORT_ID от внасянето на boks.py, а точно това чете
    # pazar.pat_do_zatvaryane.
    if not (dom or gost) and str(an.get("bucket") or "") == "boxing":
        _cd, _cg = ex.get("cena_dom"), ex.get("cena_gost")
        if _cd and _cg:
            dom, gost, raven = _cd, _cg, None
            izt = "pinnacle"
            sport = "boxing"
            pin_mid = str(ex.get("boks_id") or "") or None
            pin_obarnat = False        # редът е НАШИЯТ — оттам е дошъл

    # 🎮 ЕСПОРТЪТ ИМА СОБСТВЕН ПЪТ ДО ЦЕНАТА — и това НЕ е излишество.
    # Измерено от автора на модула живо 25.08.2026:
    # pinnacle.nameri("esports","paiN","Peladona") връща мача на „paiN
    # Academy" (цена 1.20), докато главният състав paiN играе срещу FURIA
    # на 5.05. Четирикратно разминаване, което изглежда напълно наред в
    # дневника. esport.cena сравнява ЦЕЛИ имена и МЪЛЧИ при спор; играта
    # разделя 9z-в-LoL от 9z-в-CS2 (един и същи ден).
    #
    # 🔴 СПОРТЪТ В ДНЕВНИКА Е „esports_pin", НЕ „esports". Това е ключът,
    # под който esport.py се вписва в pinnacle.SPORT_ID, и точно него иска
    # pazar.pat_do_zatvaryane, за да намери затварящата цена. Двете имена
    # НАРОЧНО се различават: изравнят ли се, общият Pinnacle-път по-долу
    # ще прегази целия модул и цената пак ще идва от съвпадане по подниз.
    if not (dom or gost) and ESP is not None \
            and str(an.get("bucket") or "") == "esports":
        try:
            _c = ESP.cena(fx.get("home"), fx.get("away"), ex.get("igra"))
            if _c and (_c.get("dom") or _c.get("gost")):
                dom, gost, raven = _c.get("dom"), _c.get("gost"), None
                izt = "pinnacle"
                sport = getattr(ESP, "PIN_KLYUCH", "esports_pin")
                pin_mid = _c.get("nomer")
                pin_obarnat = bool(_c.get("obarnat"))
        except Exception:                                    # noqa: BLE001
            pass
        if not (dom or gost):
            # Витрината мълчи за този мач — ползваме цената, с която
            # срещата дойде преди минути. По-стара е, но е НАША и е за
            # ТОЗИ мач; номерът пътува с нея, значи CLV не се губи.
            _cd, _cg = ex.get("cena_dom"), ex.get("cena_gost")
            if _cd and _cg:
                dom, gost, raven = _cd, _cg, None
                izt = "pinnacle"
                sport = getattr(ESP, "PIN_KLYUCH", "esports_pin")
                pin_mid = str(ex.get("pin_mid") or "") or None

    # 🏈 АМЕРИКАНСКИЯТ ФУТБОЛ ИМА СОБСТВЕН, СТРОГ ПЪТ (26.08.2026).
    # Стои НАД общия Pinnacle-път нарочно, а общият е изрично затворен за него
    # (виж два блока по-долу): amfutbol.cena иска ДВЕТЕ цели имена да съвпаднат,
    # докато общият съди по подниз — а в тази лига подниз-правилото прави 54
    # лъжливи закачания (измерено от автора на модула: „Ohio State" хваща
    # „Ohio", което е ДРУГ отбор).
    # На картата отива ЧИСТАТА ПОБЕДА — само нея оценителят умее да отсъди.
    # Хендикапът и тоталът пътуват като ФАКТ в an["amf_h"] и НЕ са избор.
    if not (dom or gost) and AMFUT is not None and AMFUTBOL_MAX > 0 \
            and str(an.get("bucket") or "") == "amfootball":
        try:
            _ac = amf_cena(fx)
        except Exception:                                    # noqa: BLE001
            _ac = None
        if _ac:
            _amd, _amg = _ac.get("ml_dom"), _ac.get("ml_gost")
            if _amd and _amg:
                dom, gost, raven = _amd, _amg, None
                izt = "pinnacle"
                sport = "amfootball"
                pin_mid = str(_ac.get("nomer") or "") or None
                pin_obarnat = bool(_ac.get("obarnat"))
            # Фактът се пази и когато чистата победа липсва (8 от 40 NCAA мача
            # днес нямат такава цена). Без цена картата и без това не излиза —
            # портиерът ima_pazar я реже — но полето не лъже за това.
            an["amf_h"] = {"liniya": _ac.get("h_liniya"),
                           "total": _ac.get("t_liniya")}

    # 🔴 ВТОРИЯТ ИЗТОЧНИК (18.08.2026). ESPN дава цена само за три спорта —
    # 123 от 400 карти. Тенисът (40), ММА (7) и тенисът на маса (114) оставаха
    # НАВЕКИ без цена, тоест доходността щеше да се мери на 31% от продукта.
    #
    # Измерено живо срещу guest слоя на Pinnacle, върху НАШИТЕ имена:
    #   бейзбол 100% · баскетбол 100% · тенис 78% · футбол 66% · ММА 28%
    #   общо 35 от 49 срещи, с ДЕСЕТ заявки за целия ден.
    # Волейболът е недостъпен там (401) и затова изобщо не се пита.
    #
    # Търсим с ОРИГИНАЛНИТЕ имена: показваме „Фенербахче", те знаят
    # „Fenerbahce" — с преведеното не се намираше нито един голям отбор.
    if not (dom or gost) and PIN is not None:
        try:
            _b = str(an.get("bucket") or "")
            _d = str(ex.get("home_en") or fx.get("home") or "")
            _g = str(ex.get("away_en") or fx.get("away") or "")
            # 🔴 АМЕРИКАНСКИЯТ ФУТБОЛ НЕ МИНАВА ОТТУК (26.08.2026). Той е в
            # PIN.SPORT_ID заради затварящата цена — вписва го amfutbol при
            # внос — но търсенето тук стига до подниз, а точно в тази лига
            # подниз-правилото е измерено: 54 лъжливи закачания. Цената му
            # идва по строгия път по-горе или не идва изобщо.
            if _b in PIN.SPORT_ID and _b != "amfootball" and _d and _g:
                # 🔴 ЛИГАТА СЕ ПОДАВА (26.08.2026). Без нея стъпката по
                # СЪЩИНА в pinnacle.nameri изобщо не се пуска — тя иска лига,
                # за да разбере ПОЛА, защото `kanon` нарочно изхвърля „Women"
                # от името („Italy (W)" и „Italy" стават едно) и при
                # националните отбори полът живее само в лигата.
                #
                # Измерено живо: канонът работи („Словакия" и „Slovakia" дават
                # една и съща същина), а цената пак излизаше „няма" 0 от 8
                # пъти — защото тук се викаше с ТРИ довода и `liga` беше None.
                # Поправката в pinnacle.py беше цяла и НЕДОСТИЖИМА.
                _lg = str(fx.get("league") or "")
                dom, gost, raven = PIN.ceni_za(_b, _d, _g, _lg)
                if dom or gost:
                    izt = "pinnacle"
                    sport = _b            # маржът се маха по НАШЕТО име
                    # Номерът се хваща ТУК, а не по-долу, защото само тук _d и
                    # _g със сигурност съществуват. Долу те може да са
                    # недефинирани и обръщението към тях би вдигнало NameError.
                    # getattr: файлът не бива да гърми при по-стар pinnacle.py.
                    _ns = getattr(PIN, "nomer_strana", None)
                    if _ns is not None:
                        try:
                            _mid, _ob = _ns(_b, _d, _g)
                            if _mid:
                                pin_mid, pin_obarnat = str(_mid), bool(_ob)
                        except Exception:                    # noqa: BLE001
                            pass
        except Exception:                                    # noqa: BLE001
            pass
    # 🔴 ТРЕТИЯТ ИЗТОЧНИК — САМО ЗА ВОЛЕЙБОЛ (19.08.2026).
    # Волейболът няма нито един друг път до цена. Измерено: 5 от 8-те
    # EuroVolley срещи на 21.08 получиха цена (другите три са със затворена
    # линия и нарочно нямат). Питаме с КОДА на държавата — той е един и същ
    # при двата източника, докато името е „Türkiye" тук и „Turkey W" там.
    # 🔴 ПЪРВО PINNACLE (25.08.2026), после витрината. Редът е важен: Pinnacle
    # дава ДВЕ страни, тоест маржът може да се махне и вероятността да е честна;
    # витрината дава едната. Плюс номер, значи и затваряща цена, значи CLV.
    # Мерено живо: 5 от 5 европейски мача получиха цена срещу 0 от 5 преди.
    if not (dom or gost) and PV is not None \
            and str(an.get("bucket") or "") == "volleyball":
        try:
            _pv = PV.cena(fx.get("home"), fx.get("away"), fx.get("league"))
            if _pv and (_pv.get("dom") or _pv.get("gost")):
                dom, gost, raven = _pv.get("dom"), _pv.get("gost"), None
                izt = "pinnacle"
                sport = "volleyball"
                pin_mid = _pv.get("nomer")
                pin_obarnat = bool(_pv.get("obarnat"))
        except Exception:                                    # noqa: BLE001
            pass
    if not (dom or gost) and VOL is not None             and str(an.get("bucket") or "") == "volleyball":
        try:
            _vbk = str(ex.get("vb") or "")
            _c = VOL.cena(fx.get("home_id"), fx.get("away_id"),
                          _vbk[:1] if _vbk[:1] in ("m", "w") else None)
            if _c:
                dom, gost, raven = _c["dom"], _c["gost"], None
                izt = "vitrina"
                sport = "volleyball"
        except Exception:                                    # noqa: BLE001
            pass

    if not (dom or gost):
        return an

    # Кой изход сме посочили. Картата пише „1 · ...", „2 · ..." или „Х · равен".
    pick = str(an.get("pick") or "")
    cena = None
    if pick.startswith("1"):
        cena = dom
    elif pick.startswith("2"):
        cena = gost
    elif pick.startswith("Х") or pick.startswith("X"):
        cena = raven
    if cena:
        # 📈 СУРОВИТЕ ЦЕНИ НА ВСИЧКИ ИЗХОДИ, както са в ТОЗИ момент — за
        # тефтера на цените. Пише се ТУК, защото само тук dom/gost/raven са
        # пълни и още не са пипани от обръщането на избора по-долу. Етикетът
        # е ИЗХОДЪТ, не «наша/друга»: изборът се обръща, изходът не.
        an["_ceni_sur"] = {"1": dom, "2": gost, "Х": raven}
        an["pazar_cena"] = cena
        # 🔴 И ДРУГАТА СТРАНА (01.09.2026). Дотук вадехме dom, gost И raven
        # от една и съща заявка, а записвахме САМО нашата — другата се
        # хвърляше. Одитен агент го измери: половината вече платена цена
        # изчезва, а с нея и възможността да се види КОЛКО НЕРАВЕН е мачът.
        #
        # Читателят вижда „1.25" и не знае дали срещу него стои 3.80 (мач
        # без история) или 1.45 (истински равностоен). Числото само по себе
        # си не казва това — двойката го казва.
        #
        # И оценителят получава с какво да мери грешката в ДРУГАТА посока:
        # без цената на противника не може да се смята какво би върнал
        # обратният залог.
        _dr = None
        if pick.startswith("1"):
            _dr = gost
        elif pick.startswith("2"):
            _dr = dom
        if _dr:
            try:
                _dv = float(_dr)
                if 1.0 < _dv < 1000.0:
                    an["pazar_cena_drug"] = _dv
            except (TypeError, ValueError):
                pass
        # 🔴 МАРЖЪТ НА БУКМЕЙКЪРА (18.08.2026).
        # На КАРТАТА стои суровата цена — тя е това, което пазарът наистина
        # плаща, и читателят има право на нея непокътната.
        # В ДНЕВНИКА обаче влиза вероятността БЕЗ дела на букмейкъра, защото
        # само с нея сравнението „ние срещу пазара" значи нещо. Измерено на
        # живо: суровото 1/цена надува пазара със 7.4% при футбола и 1.9% при
        # бейзбола, а прагът на сравнението е 2%. Тоест почти половината
        # футболни изходи щяха да изглеждат „по-уверени от нас" само заради
        # маржа.
        pd, pg, pr = PZ.bez_marzh(sport, dom, gost, raven)
        chist = {"1": pd, "2": pg, "Х": pr, "X": pr}.get(pick[:1])
        if chist:
            an["pazar_p"] = round(chist, 4)
            # 🔴 ЗНАК ЗА ВЕРСИЯ (18.08.2026). В живия дневник вече стоят 5
            # записа със СУРОВА пазарна вероятност (с маржа вътре) от старата
            # версия. Смесени със свитите, те биха развалили сравнението, а
            # прагът за него е 30 отсъдени — тоест щеше да се прекрачи с
            # мръсна смес и никой нямаше да разбере. Мери се само версия 2+.
            an["pazar_v"] = 2
            # ── СЪГЛАСИЕТО С ПАЗАРА (25.08.2026) ──────────────────────────
            # Измерено на 598 отсъдени карти: Брайер наш 0.2405 срещу
            # пазарен 0.2128 — и в ПЪРВАТА, и във ВТОРАТА половина на
            # дневника поотделно. Тоест числото на картата става по-вярно,
            # ако тежи и пазарното.
            #
            # НИТО ЕДНА КАРТА НЕ ОТПАДА. Собственикът каза: „всичко е
            # прогноза, пускай всичко." Мени се само ЧИСЛОТО — и когато то
            # мине от другата страна на 50%, изборът го следва.
            #
            # Ползата, мерена по истинските резултати: −16.7% → −13.4% общо,
            # а при двуизходните спортове −9.2% → −3.7%. Скромно, но истинско.
            # 🔴 ЗА БОКСА И ЕСПОРТА НЕ СЕ СМЕСВА (25.08.2026). Нашето число
            # ТАМ Е пазарното — смесването на пазара със самия него дава
            # изречение, вярно по конструкция („мислим същото"), тоест
            # празно. Същият капан е описан три реда по-долу за p_model.
            if SG is not None and str(an.get("bucket") or "") not in BEZ_SMESVANE:
                # 🔴 НАШЕТО ЧИСЛО СЕ ПАЗИ, ПРЕДИ ДА БЪДЕ ЗАМЕНЕНО (25.08.2026).
                # Теглото е 0.00, значи `an["p"]` СТАВА пазарното. Без този
                # ред картата после сравнява пазарното със самото себе си и
                # неизбежно пише „мислим същото" — изречение, вярно по
                # конструкция и следователно празно.
                an["p_model"] = float(an.get("p") or 0.0)
                _sm = SG.smesi(an.get("p"), chist)
                if _sm is None:
                    pass
                elif (str(an.get("bucket") or "") in DVA_IZHODA
                        and SG.obrasta_li(an.get("p"), chist)):
                    _og = ogledalo(pick, fx.get("home"), fx.get("away"))
                    _dr_c = {"1": gost, "2": dom}.get(pick[:1])
                    _dr_p = {"1": pg, "2": pd}.get(pick[:1])
                    if _og and _dr_c and _dr_p:
                        an["pick"] = _og
                        # Линейната смес е симетрична: 1−смес(p) Е сместа на
                        # другата страна. Едно правило, не две.
                        an["p"] = round(min(0.95, max(0.05, 1.0 - _sm)), 4)
                        an["pazar_cena"] = _dr_c
                        an["pazar_p"] = round(_dr_p, 4)
                        an["obarnata"] = True
                        # 🔴 ОБЯСНЕНИЕТО Е ПИСАНО ЗА СТАРАТА СТРАНА. Оставено
                        # както си е, картата щеше да казва „2 · Б", а отдолу
                        # „А спечели 7 от последните 10" — да спори сама със
                        # себе си пред читателя. Затова се маха и се заменя с
                        # ЕДИН факт, без лекция защо.
                        an["why"] = ["числото е претеглено с пазарното"]
                else:
                    an["p"] = _sm
            # 🔴 ЗАДАЧА 2 (25.08.2026). ПРАГЪТ СЕ ПРИЛАГАШЕ ПРЕДИ ТОВА МЯСТО.
            # Долната граница се мери на ред ~6191 (`_prag = dolen_prag(...)`),
            # а dobavi_pazar се вика чак на ~6253 — тоест картата минаваше летвата
            # с НАШЕТО число и излизаше с ПАЗАРНОТО, което вече никой не мереше.
            # А теглото в sglasie е 0.00, значи пазарното ЗАМЕСТВА нашето изцяло.
            #
            # ИЗМЕРЕНО на живия дневник (predict_log.json, sha a78efaf1, 737
            # записа): от 232 карти с двете числа, 54 биха излезли ПОД своя праг
            # след смесването — 28 футбол, 13 бейзбол, 8 баскетбол, 4 тенис,
            # 1 волейбол. Най-лошата: футболна карта с наше 49.2%, пазарно 11.6%
            # → на картата щеше да пише „11.6%". Изречение, което само се
            # опровергава — точно това, срещу което прагът е направен.
            #
            # Огледалото спасява ДВУИЗХОДНИТЕ спортове (там 1−p е валиден избор),
            # но футболът има три изхода и няма огледало — затова 28 от 54 са
            # футбол.
            #
            # Тук само се ОТБЕЛЯЗВА. Изхвърлянето става там, където се брои —
            # инак числото пак би изчезнало мълчаливо.
            an["pod_prag_sled_pazar"] = (
                float(an.get("p") or 0.0) < dolen_prag(an.get("bucket")))
        # Адресът за затварящата цена. Без него CLV не може да се смята — а
        # CLV е единственото доказателство за ръб, което работи при 20 залога.
        an["pazar_izt"] = izt
        # Затварящата цена се взима от ESPN по номер.
        # 🔴 И ОТ PINNACLE ВЕЧЕ (25.08.2026). Старият коментар тук твърдеше, че
        # за Pinnacle „още не е направен" подход — това вече не е вярно:
        # pazar.cena_zatvarayashta_pin(sport_key, mid, obarnat) съществува и
        # чака точно тези три полета. „Затваряща" там значи „последната преди
        # началото": Pinnacle маха мача в мига на старта и след това връща
        # празно, тоест нищо не се презаписва.
        if izt == "espn" and ev_id:
            an["pazar_ev"] = str(ev_id)
            an["pazar_sport"] = str(sport)
            an["pazar_liga"] = str(slug)
        elif izt == "pinnacle" and pin_mid:
            # pazar.pat_do_zatvaryane() чете ИМЕННО pazar_ev + pazar_izt, а
            # спортът пада назад към bucket. Затова се пише и pazar_sport —
            # инак пътят се съди по чужд ключ.
            an["pazar_ev"] = pin_mid
            an["pazar_sport"] = str(sport)
            # 🔴 ДВЕ РАЗЛИЧНИ „ОБЪРНАТИ" — ДА НЕ СЕ БЪРКАТ.
            # `obarnata` (без наставка) значи: НИЕ обърнахме избора си на другия
            # изход, защото сместа с пазара мина 50%.
            # `pazar_obarnat` значи: PINNACLE държи нашия домакин като гост.
            # Второто е свойство на чуждата витрина и НЕ се мени, ако първото
            # се случи — cena_zatvarayashta_pin връща страните в НАШИЯ ред.
            an["pazar_obarnat"] = bool(pin_obarnat)
        # Непълен набор → `pazar_p` НЕ се записва изобщо. По-добре кантарът да
        # мълчи, отколкото да мери с крив аршин. Цената на картата остава.
    return an


def dobavi_pazar(an):
    """Цената + една точка в редицата ѝ. Нула нови заявки.

    🔴 ОБВИВКА, А НЕ РЕД ВЪТРЕ В ТЯЛОТО (02.09.2026). `_pazar_surovo` има ДВА
    изхода, през които минава цена — местният тенис на маса излиза рано — и
    утре може да има трети. Ред, сложен на единия, би пропуснал другия
    мълчаливо: точно шаблонът «построено, но не свързано», който в този
    проект е ударил осем пъти. Обвивката няма как да бъде заобиколена.
    """
    an = _pazar_surovo(an)
    return zapishi_cena(an)


