    # 🔴 ХОКЕЯТ ПАЗИ ОРИГИНАЛНОТО ИМЕ (21.08.2026). Той не минава през
    # ESPN и досега оставяше extra празно — а имената му СЕ ПРЕВЕЖДАТ.
    # Проверката е поведенческа: подхвърлям отговора на НХЛ и гледам
