    # ── СМЕТКАТА НА ТРИТЕ ИГРИ НЕ СЕ СЛИВА ───────────────────────────────
    # Дневник от 24 отсъдени: 12 CS2 (2 познати) и 12 LoL (10 познати).
    # Слеят ли се, картата и на двете би казала „12 познати от 24" — число,
