    # ═══════════════════════ 💰 ЦЕНАТА НА КАРТАТА (01.09.2026)
    # Всяка от тези проверки е убита с мутация, преди да бъде оставена тук —
    # изброени са в отчета. Нито една не гледа календара.
    _cn_sega = datetime(2026, 9, 1, 12, 0)
